def get_team_name(team_id):
    """Obtém o nome oficial da equipe."""
    try:
        url = f"{BASE_URL}/teams"
        params = {"id": team_id}
        response = requests.get(url, headers=headers, params=params)
        response.raise_for_status()
        data = response.json()
        if data["response"]:
            return data["response"][0]["team"]["name"]
        return "Desconhecido"
    except Exception as e:
        print(f"⚠️ Erro ao buscar nome do time {team_id}: {e}. Usando padrão.")
        return "Desconhecido"


def get_league_name(league_id):
    """Obtém o nome oficial da liga."""
    try:
        url = f"{BASE_URL}/leagues"
        params = {"id": league_id}
        response = requests.get(url, headers=headers, params=params)
        response.raise_for_status()
        data = response.json()
        if data["response"]:
            return data["response"][0]["league"]["name"]
        return "Liga Desconhecida"
    except Exception as e:
        print(f"⚠️ Erro ao buscar nome da liga {league_id}: {e}. Usando padrão.")
        return "Liga Desconhecida"


def get_team_leagues(team_id, season="2024"):
    """Lista as ligas disponíveis do time para o modo clássico."""
    try:
        url = f"{BASE_URL}/leagues"
        params = {"team": team_id, "season": season}
        response = requests.get(url, headers=headers, params=params)
        response.raise_for_status()
        data = response.json()

        if data["response"]:
            leagues = []
            for league in data["response"]:
                leagues.append(league["league"]["id"])
            return leagues[0]
        return None
    except Exception as e:
        print(f"⚠️ Erro ao buscar ligas do time: {e}.")
        return None


# =====================================================================
# FUNÇÕES DE DADOS REAIS PARA O PAINEL PRÉ-LIVE (ODDS, LESÕES, H2H, GRUPO)
