def get_fixture_odds(fixture_id):
    """Busca odds reais 1X2 da API. Retorna None se indisponível (jogo futuro
    demais, mercado não aberto, ou plano sem cobertura de odds)."""
    try:
        url = f"{BASE_URL}/odds"
        params = {"fixture": fixture_id, "bet": 1}  # bet=1 costuma ser o mercado "Match Winner"
        res = requests.get(url, headers=headers, params=params).json()
        response = res.get("response", [])
        if not response:
            return None

        # Percorre bookmakers até achar o mercado 1X2 com as 3 odds completas
        for bookmaker_entry in response[0].get("bookmakers", []):
            for bet in bookmaker_entry.get("bets", []):
                if bet.get("name") in ("Match Winner", "1X2"):
                    values = {v["value"]: float(v["odd"]) for v in bet.get("values", [])}
                    odd_h = values.get("Home")
                    odd_d = values.get("Draw")
                    odd_a = values.get("Away")
                    if odd_h and odd_d and odd_a:
                        return {"home": odd_h, "draw": odd_d, "away": odd_a, "bookmaker": bookmaker_entry.get("name")}
        return None
    except Exception:
        return None


def get_team_injuries(team_id, fixture_id):
    """Busca lesões/suspensões reais relacionadas à equipe para essa partida."""
    try:
        url = f"{BASE_URL}/injuries"
        params = {"team": team_id, "fixture": fixture_id}
        res = requests.get(url, headers=headers, params=params).json()
        response = res.get("response", [])
        out = []
        for item in response:
            player = item.get("player", {})
            out.append({
                "name": player.get("name", "Desconhecido"),
                "type": player.get("type", "Indisponível"),
                "reason": player.get("reason", "Não especificado")
            })
        return out
    except Exception:
        return []


def get_head_to_head_matches(home_id, away_id, limit=5):
    """Busca o histórico real de confrontos diretos entre as duas equipes."""
    try:
        url = f"{BASE_URL}/fixtures/headtohead"
        params = {"h2h": f"{home_id}-{away_id}", "last": limit}
        res = requests.get(url, headers=headers, params=params).json()
        return res.get("response", [])
    except Exception:
        return []


def get_group_standing(team_id, league_id, season):
    """Busca a posição real do time na fase de grupos/chave do torneio."""
    try:
        url = f"{BASE_URL}/standings"
        params = {"league": league_id, "season": season, "team": team_id}
        res = requests.get(url, headers=headers, params=params).json()
        response = res.get("response", [])
        if not response:
            return None
        standings_groups = response[0]["league"]["standings"]
        for group in standings_groups:
            for team_row in group:
                if int(team_row["team"]["id"]) == int(team_id):
                    return {
                        "rank": team_row["rank"],
                        "points": team_row["points"],
                        "goalsDiff": team_row["goalsDiff"],
                        "group": team_row.get("group", "")
                    }
        return None
    except Exception:
        return None


def calculate_rest_days(last_match_date_str):
    """Calcula dias reais de descanso desde a última partida disputada."""
    if not last_match_date_str:
        return None
    try:
        last_date = dt_datetime.strptime(last_match_date_str[:10], "%Y-%m-%d")
        today = dt_datetime.now()
        delta = (today - last_date).days
        return max(delta, 0)
    except Exception:
        return None


# =====================================================================
# EVENTOS MAIS PROVÁVEIS (NÍVEL JOGADOR E NÍVEL EQUIPE)
# =====================================================================
#
# NOTA DE TRANSPARÊNCIA IMPORTANTE: a API não fornece a escalação titular
# com antecedência suficiente para uma análise pré-live (lineups só ficam
# disponíveis 20-40 min antes do jogo). Por isso, os dados de jogador
# abaixo são HISTÓRICOS -- mostram quem mais gerou esses eventos nos
# jogos recentes da seleção, não uma previsão de quem vai jogar hoje.
# Se um jogador estiver suspenso, lesionado, ou for poupado, esses
# números deixam de valer. Trate como "jogadores em destaque", não
# como previsão de titularidade.

def get_fixture_player_stats(fixture_id):
    """Busca estatísticas reais por jogador de uma partida específica
    (chutes, cartões, faltas, etc.) via /fixtures/players."""
    try:
        url = f"{BASE_URL}/fixtures/players"
        params = {"fixture": fixture_id}
        res = requests.get(url, headers=headers, params=params).json()
        return res.get("response", [])
    except Exception:
        return []


def get_fixture_statistics(fixture_id):
    """Busca estatísticas ao vivo/pós-jogo de uma partida via /fixtures/statistics."""
    try:
        url = f"{BASE_URL}/fixtures/statistics"
        params = {"fixture": fixture_id}
        res = requests.get(url, headers=headers, params=params).json()
        return res.get("response", [])
    except Exception:
        return []


def aggregate_player_event_history(fixtures, team_id):
    """Agrega, a partir de jogos passados reais, quais jogadores mais
    chutaram a gol e mais receberam cartão. Retorna listas ordenadas
    por frequência -- é um retrato do histórico recente, não uma
    previsão de escalação."""
    shots_counter = Counter()
    shots_on_target_counter = Counter()
    cards_counter = Counter()
    appearances = Counter()

    for f in fixtures or []:
        fixture_id = f["fixture"]["id"]
        player_data = get_fixture_player_stats(fixture_id)
        for team_block in player_data:
            if int(team_block.get("team", {}).get("id", -1)) != int(team_id):
                continue
            for p in team_block.get("players", []):
                name = p.get("player", {}).get("name", "Desconhecido")
                stats_list = p.get("statistics", [])
                if not stats_list:
                    continue
                s = stats_list[0]
                minutes = (s.get("games") or {}).get("minutes") or 0
                if not minutes:
                    continue  # não entrou em campo nesse jogo
                appearances[name] += 1

                shots = (s.get("shots") or {}).get("total") or 0
                shots_on = (s.get("shots") or {}).get("on") or 0
                yellow = (s.get("cards") or {}).get("yellow") or 0
                red = (s.get("cards") or {}).get("red") or 0

                shots_counter[name] += shots
                shots_on_target_counter[name] += shots_on
                cards_counter[name] += (yellow + red)

    return {
        "top_shooters": shots_counter.most_common(5),
        "top_shooters_on_target": shots_on_target_counter.most_common(5),
        "top_cards": cards_counter.most_common(5),
        "appearances": appearances
    }


def estimate_team_corners_by_half(team_id, fixtures, sample_size=5):
    """Busca escanteios por tempo (1º/2º) usando o parâmetro half=true
    da API, real, para os jogos recentes da equipe. Retorna médias.

    NOTA TÉCNICA: a documentação pública confirma que o parâmetro
    half=true existe e retorna dados de 1º/2º tempo, mas não documenta
    publicamente o formato exato do campo de período (pode vir como
    'statistics' duplicado com sufixo, ou como bloco 'periods' aninhado,
    dependendo da versão da API). Esta função tenta múltiplos formatos
    plausíveis de forma defensiva. Se nenhum bater, retorna None em vez
    de inventar um número -- e isso deve ser ajustado após confirmar o
    formato real na primeira chamada (consulte a resposta crua se
    precisar depurar)."""
    first_half_corners = []
    second_half_corners = []

    for f in (fixtures or [])[:sample_size]:
        fixture_id = f["fixture"]["id"]
        try:
            url = f"{BASE_URL}/fixtures/statistics"
            params = {"fixture": fixture_id, "half": "true"}
            res = requests.get(url, headers=headers, params=params).json()
            response = res.get("response", [])
            team_block = None
            for block in response:
                if int(block.get("team", {}).get("id", -1)) == int(team_id):
                    team_block = block
                    break
            if not team_block:
                continue

            fh, sh = None, None

            # Formato possível 1: bloco aninhado "periods"
            periods = team_block.get("periods")
            if periods:
                fh = (periods.get("first_half") or {}).get("Corner Kicks")
                sh = (periods.get("second_half") or {}).get("Corner Kicks")

            # Formato possível 2: lista "statistics" com campo de período explícito
            if fh is None and sh is None:
                for stat in team_block.get("statistics", []):
                    if stat.get("type") == "Corner Kicks":
                        period = stat.get("period") or stat.get("half")
                        val = stat.get("value")
                        if val is None:
                            continue
                        try:
                            val = int(val)
                        except (TypeError, ValueError):
                            continue
                        if period in ("1H", "first_half", "1st"):
                            fh = val
                        elif period in ("2H", "second_half", "2nd"):
                            sh = val

            if fh is not None:
                first_half_corners.append(fh)
            if sh is not None:
                second_half_corners.append(sh)
        except Exception:
            continue

    return {
        "first_half_avg": (sum(first_half_corners) / len(first_half_corners)) if first_half_corners else None,
        "second_half_avg": (sum(second_half_corners) / len(second_half_corners)) if second_half_corners else None,
        "samples": len(first_half_corners),
        "format_confirmed": len(first_half_corners) > 0 or len(second_half_corners) > 0
    }


def estimate_goals_by_time_window(fixtures, team_id, sample_size=10):
    """Estima, a partir de eventos reais de gol nos jogos passados, em
    quais janelas de tempo a equipe mais marca/sofre. Usa /fixtures/events."""
    windows = {"0-15": 0, "16-30": 0, "31-45": 0, "46-60": 0, "61-75": 0, "76-90+": 0}
    total_goals_found = 0

    for f in (fixtures or [])[:sample_size]:
        fixture_id = f["fixture"]["id"]
        try:
            url = f"{BASE_URL}/fixtures/events"
            params = {"fixture": fixture_id}
            res = requests.get(url, headers=headers, params=params).json()
            events = res.get("response", [])
            for ev in events:
                if ev.get("type") != "Goal":
                    continue
                if int(ev.get("team", {}).get("id", -1)) != int(team_id):
                    continue
                minute = (ev.get("time") or {}).get("elapsed")
                if minute is None:
                    continue
                total_goals_found += 1
                if minute <= 15: windows["0-15"] += 1
                elif minute <= 30: windows["16-30"] += 1
                elif minute <= 45: windows["31-45"] += 1
                elif minute <= 60: windows["46-60"] += 1
                elif minute <= 75: windows["61-75"] += 1
                else: windows["76-90+"] += 1
        except Exception:
            continue

    if total_goals_found == 0:
        return None

    return {
        "windows_pct": {k: round((v / total_goals_found) * 100, 1) for k, v in windows.items()},
        "total_goals_sampled": total_goals_found
    }


def rest_recovery_index(rest_days):
    """Converte dias de descanso num índice de recuperação física (0-100).
    Baseado em literatura esportiva geral: <3 dias = fadiga residual alta;
    5-7 dias = recuperação ótima; >10 dias = sem ganho adicional relevante."""
    if rest_days is None:
        return None
    if rest_days <= 2:
        return 55
    elif rest_days <= 4:
        return 70 + (rest_days - 2) * 7  # 70-84
    elif rest_days <= 7:
        return 85 + (rest_days - 4) * 3  # 85-94
    else:
        return min(98, 94 + (rest_days - 7))


# =====================================================================
# ANÁLISE DE MATCHUP DE ESTILO (LEITURA TÁTICA, NÃO SÓ NÚMEROS BRUTOS)
# =====================================================================

def classify_team_style(metrics):
    """Classifica o perfil tático predominante de uma equipe a partir de
    médias de posse, escanteios e volume de chutes nos jogos recentes.
    Isso é uma heurística descritiva (não preditiva) para ajudar a leitura
    do confronto, como um scout faria ao assistir aos últimos jogos."""
    poss_samples = metrics.get("style_possession_samples") or []
    corner_samples = metrics.get("style_corners_samples") or []
    shots_samples = metrics.get("style_shots_samples") or []

    avg_poss = sum(poss_samples) / len(poss_samples) if poss_samples else metrics.get("avg_poss_calc", 50)
    avg_corners = sum(corner_samples) / len(corner_samples) if corner_samples else metrics.get("avg_corners_calc", 5)
    avg_shots = sum(shots_samples) / len(shots_samples) if shots_samples else metrics.get("avg_shots_calc", 12)

    # Heurística simples de classificação de perfil
    if avg_poss >= 55 and avg_shots >= 13:
        profile = "Protagonista (controla posse e volume ofensivo)"
    elif avg_poss < 45 and avg_shots >= 10:
        profile = "Contra-ataque direto (pouca posse, mas finaliza em transição)"
    elif avg_poss < 45 and avg_shots < 10:
        profile = "Retranca / Bloco baixo (cede posse e produz pouco volume)"
    else:
        profile = "Equilibrado (sem domínio claro de posse ou volume)"

    return {
        "profile": profile,
        "avg_possession": round(avg_poss, 1),
        "avg_corners": round(avg_corners, 1),
        "avg_shots": round(avg_shots, 1)
    }


def analyze_style_matchup(h_style, a_style):
    """Cruza os dois perfis para gerar uma leitura textual do confronto,
    no estilo de uma nota de scouting -- não é probabilidade, é contexto."""
    notes = []

    poss_diff = h_style["avg_possession"] - a_style["avg_possession"]
    if abs(poss_diff) >= 15:
        dominant = "mandante" if poss_diff > 0 else "visitante"
        notes.append(f"Forte assimetria de posse esperada, favorecendo o {dominant} controlar o ritmo do jogo.")
    else:
        notes.append("Disputa de posse equilibrada; o jogo tende a ser decidido em duelos individuais e transições.")

    if "Retranca" in h_style["profile"] and "Protagonista" in a_style["profile"]:
        notes.append("Mandante tende a jogar fechado e explorar contra-ataques contra um visitante que domina a posse — atenção a jogos de poucos gols com chances claras raras.")
    elif "Retranca" in a_style["profile"] and "Protagonista" in h_style["profile"]:
        notes.append("Visitante tende a se fechar; mandante pode esbarrar em bloco baixo — paciência ofensiva será decisiva.")
    elif "Contra-ataque" in h_style["profile"] and "Contra-ataque" in a_style["profile"]:
        notes.append("Ambos preferem jogar em transição — jogo aberto, com espaços nas costas das defesas, tende a favorecer mais gols.")
    elif "Protagonista" in h_style["profile"] and "Protagonista" in a_style["profile"]:
        notes.append("Duas equipes que buscam o controle do jogo — disputa direta pela posse, volume ofensivo alto dos dois lados.")

    return notes


# =====================================================================
# VALIDAÇÃO E CALIBRAÇÃO DO MODELO (BACKTESTING HONESTO)
# =====================================================================
#
# Diferença importante: isto NÃO mede "confiabilidade" inventando uma
# fórmula arbitrária. Mede se as probabilidades que o modelo geraria
# para jogos PASSADOS (cujo resultado já é conhecido) foram, na média,
# consistentes com o que de fato aconteceu. Isso é a única forma honesta
# de saber se o modelo tem algum valor preditivo real.
#
# Duas métricas padrão da literatura de previsão probabilística:
#   - Brier Score: erro quadrático médio entre prob. prevista e resultado
#     real (0 = perfeito, 1 = pior possível). Para 3 desfechos (V/E/D),
#     o Brier score de um "modelo" que sempre chuta as odds de mercado
#     costuma ficar entre 0.55 e 0.65 no futebol — é a régua realista.
#   - Hit rate do favorito: quantas vezes o lado com maior probabilidade
#     prevista realmente venceu.
#
# Isso não garante lucro nem "acerto" futuro -- mercados eficientes
# tendem a já precificar a maior parte do que esse tipo de modelo capta.
# O valor real do backtest é te mostrar se o modelo é apenas RUIDO
# (Brier perto de 0.667, que é o "chute aleatório" para 3 resultados)
# ou se tem alguma calibração mínima.

def backtest_model_on_history(team_id, league_id=WORLD_CUP_LEAGUE_ID, season=WORLD_CUP_SEASON, sample_size=10):
    """Roda uma validação simplificada: para cada jogo passado do time,
    compara o resultado real com uma estimativa baseada em gols marcados/
    sofridos médios até aquele ponto (proxy simplificado do modelo Poisson).
    Retorna métricas agregadas de calibração."""
    try:
        url = f"{BASE_URL}/fixtures"
        params = {"team": team_id, "status": "FT", "last": sample_size + 5}
        res = requests.get(url, headers=headers, params=params).json()
        fixtures = res.get("response", [])
        fixtures.sort(key=lambda f: f["fixture"]["date"])  # ordem cronológica
    except Exception:
        return None

    if len(fixtures) < 6:
        return None  # amostra insuficiente para validar com seriedade

    brier_scores = []
    hits = 0
    total = 0

    rolling_gf, rolling_gc = [], []

    for f in fixtures:
        is_home = int(f["teams"]["home"]["id"]) == int(team_id)
        gf = f["goals"]["home"] if is_home else f["goals"]["away"]
        gc = f["goals"]["away"] if is_home else f["goals"]["home"]

        # Só valida a partir do 4º jogo em diante (precisa de histórico mínimo antes)
        if len(rolling_gf) >= 3:
            avg_gf = sum(rolling_gf) / len(rolling_gf)
            avg_gc = sum(rolling_gc) / len(rolling_gc)

            lam_for = max(0.3, avg_gf)
            lam_against = max(0.3, avg_gc)

            p_win = p_draw = p_loss = 0.0
            for hg in range(10):
                for ag in range(10):
                    p = poisson_probability(lam_for, hg) * poisson_probability(lam_against, ag)
                    if hg > ag: p_win += p
                    elif hg == ag: p_draw += p
                    else: p_loss += p

            _bt_sum = p_win + p_draw + p_loss
            if _bt_sum > 0:
                p_win /= _bt_sum
                p_draw /= _bt_sum
                p_loss /= _bt_sum

            if gf > gc: actual = (1, 0, 0)
            elif gf == gc: actual = (0, 1, 0)
            else: actual = (0, 0, 1)

            predicted = (p_win, p_draw, p_loss)
            brier = sum((predicted[i] - actual[i]) ** 2 for i in range(3))
            brier_scores.append(brier)

            predicted_outcome = predicted.index(max(predicted))
            actual_outcome = actual.index(1)
            if predicted_outcome == actual_outcome:
                hits += 1
            total += 1

        rolling_gf.append(gf)
        rolling_gc.append(gc)
        if len(rolling_gf) > 5:
            rolling_gf.pop(0)
            rolling_gc.pop(0)

    if total == 0:
        return None

    avg_brier = sum(brier_scores) / len(brier_scores)
    hit_rate = (hits / total) * 100

    return {
        "samples_validated": total,
        "brier_score": round(avg_brier, 3),
        "hit_rate": round(hit_rate, 1),
        "reference_random": 0.667,   # Brier de um "chute" uniforme entre V/E/D
        "reference_market": "0.55–0.65 (faixa típica de mercados eficientes)"
    }


# =====================================================================
# MATEMÁTICA OPERACIONAL E DISTRIBUIÇÃO DE POISSON
# =====================================================================

def poisson_probability(lmbda, goals):
    """Calcula a probabilidade utilizando a distribuição clássica de Poisson."""
    if lmbda <= 0:
        return 1.0 if goals == 0 else 0.0
    return (math.exp(-lmbda) * (lmbda ** goals)) / math.factorial(goals)


