def list_world_cup_matches_today():
    """Busca as partidas da Copa aplicando o fuso horário oficial de Brasília."""
    print("\n=== CALENDÁRIO DA COPA DO MUNDO ===")
    print("Digite a data que deseja analisar no formato AAAA-MM-DD")
    print("Ou pressione ENTER para usar a data de HOJE.")

    input_date = input("Data (Ex: 2026-06-19): ").strip()

    if not input_date:
        today_str = datetime.datetime.now().strftime("%Y-%m-%d")
    else:
        try:
            datetime.datetime.strptime(input_date, "%Y-%m-%d")
            today_str = input_date
        except ValueError:
            print("❌ Formato inválido! Utilizando a data de hoje.")
            today_str = datetime.datetime.now().strftime("%Y-%m-%d")

    url = f"{BASE_URL}/fixtures"
    params = {
        "league": WORLD_CUP_LEAGUE_ID,
        "season": WORLD_CUP_SEASON,
        "date": today_str,
        "timezone": "America/Sao_Paulo"
    }

    try:
        response = requests.get(url, headers=headers, params=params)
        response.raise_for_status()
        data = response.json()

        matches = data.get("response", [])
        matches_list = []

        if not matches:
            print(f"\nNenhum jogo da Copa do Mundo agendado para {today_str} no fuso de Brasília.")
            return

        print(f"\n⚽ JOGOS LOCALIZADOS EM {today_str}:")
        print("-" * 60)

        for i, match in enumerate(matches, start=1):
            fixture_id = match["fixture"]["id"]
            home_team = match["teams"]["home"]
            away_team = match["teams"]["away"]
            date_str = match["fixture"]["date"]

            try:
                time_str = date_str.split("T")[1][:5]
            except IndexError:
                time_str = "--:--"

            matches_list.append({
                "fixture_id": fixture_id,
                "home_id": home_team["id"],
                "home_name": home_team["name"],
                "away_id": away_team["id"],
                "away_name": away_team["name"],
                "time": time_str,
                "raw_data": match
            })

            print(f"{i}. {home_team['name']} x {away_team['name']}")
            print(f"   Horário: {time_str} Horário de Brasília | ID: {fixture_id}\n")

        choice = input("Escolha o número da partida para abrir o painel: ")
        try:
            choice = int(choice)
            if 1 <= choice <= len(matches_list):
                global selected_match
                selected_match = matches_list[choice - 1]
                world_cup_match_menu()
            else:
                print("❌ Seleção inválida.")
        except ValueError:
            print("❌ Entrada inválida.")

    except Exception as e:
        import traceback
        print(f"❌ Erro na requisição do calendário: {e}")
        traceback.print_exc()


