# MÓDULO 2 - CASA X FORA (HOME/AWAY SPLIT)
# =====================================================================

def fetch_home_away_fixtures(team_id, venue="home", n=10):
    """
    Busca os últimos N jogos do time apenas como mandante ou visitante.
    venue = 'home' ou 'away'
    """
    import requests as _req
    try:
        res = _req.get(
            f"{BASE_URL}/fixtures",
            headers=headers,
            params={"team": team_id, "status": "FT", "last": 30}
        ).json()
        all_fixtures = res.get("response", [])
        filtered = []
        for f in all_fixtures:
            if venue == "home" and int(f["teams"]["home"]["id"]) == int(team_id):
                filtered.append(f)
            elif venue == "away" and int(f["teams"]["away"]["id"]) == int(team_id):
                filtered.append(f)
            if len(filtered) >= n:
                break
        return filtered
    except Exception:
        return []


def compile_home_away_metrics(fixtures, team_id, venue):
    """
    Compila métricas separadas para jogos em casa ou fora.
    Retorna dict com médias de gols, xG proxy, escanteios, cartões, chutes, posse.
    """
    import requests as _req
    if not fixtures:
        return None
    gf_list, gc_list, corners_list, shots_list, sot_list, cards_list, poss_list = [], [], [], [], [], [], []
    for f in fixtures:
        is_home = int(f["teams"]["home"]["id"]) == int(team_id)
        gf = f["goals"]["home"] if is_home else f["goals"]["away"]
        gc = f["goals"]["away"] if is_home else f["goals"]["home"]
        gf_list.append(gf)
        gc_list.append(gc)
        try:
            sr = _req.get(
                f"{BASE_URL}/fixtures/statistics",
                headers=headers,
                params={"fixture": f["fixture"]["id"]}
            ).json().get("response", [])
            for block in sr:
                if int(block.get("team", {}).get("id", -1)) == int(team_id):
                    def _ps(bt, tp):
                        for s in bt.get("statistics", []):
                            if s["type"] == tp:
                                v = str(s.get("value", "0")).replace("%", "").strip()
                                return int(v) if v.isdigit() else 0
                        return 0
                    shots_list.append(_ps(block, "Total Shots"))
                    sot_list.append(_ps(block, "Shots on Goal"))
                    corners_list.append(_ps(block, "Corner Kicks"))
                    cards_list.append(_ps(block, "Yellow Cards") + _ps(block, "Red Cards"))
                    poss_list.append(_ps(block, "Ball Possession"))
        except Exception:
            pass

    def safe_avg(lst):
        return round(sum(lst) / len(lst), 2) if lst else 0.0

    return {
        "venue": venue,
        "n": len(fixtures),
        "avg_gf": safe_avg(gf_list),
        "avg_gc": safe_avg(gc_list),
        "avg_shots": safe_avg(shots_list),
        "avg_sot": safe_avg(sot_list),
        "avg_corners": safe_avg(corners_list),
        "avg_cards": safe_avg(cards_list),
        "avg_possession": safe_avg(poss_list) if poss_list else 50.0,
    }


def blend_home_away_general(ha_metrics, general_metrics, ha_weight=0.70):
    """
    Combina métricas casa/fora (70%) com métricas gerais (30%).
    Retorna dict com valores combinados.
    """
    if ha_metrics is None:
        return general_metrics
    gw = 1.0 - ha_weight
    fields = ["avg_gf", "avg_gc", "avg_shots", "avg_sot", "avg_corners"]
    result = {}
    for f in fields:
        ha_val = ha_metrics.get(f, 0)
        gen_val = general_metrics.get(f, general_metrics.get(f + "_calc", 0))
        result[f] = round(ha_val * ha_weight + gen_val * gw, 3)
    result["avg_possession"] = round(
        ha_metrics.get("avg_possession", 50) * ha_weight
        + general_metrics.get("avg_poss_calc", 50) * gw, 1
    )
    return result


# =====================================================================
# MÓDULO 3 - ELO RATING
# =====================================================================

# Cache global de ELO para evitar recálculo
_elo_cache = {}


def _get_team_fixtures_for_elo(team_id, n=20):
    """Busca jogos passados para calcular ELO."""
    import requests as _req
    try:
        res = _req.get(
            f"{BASE_URL}/fixtures",
            headers=headers,
            params={"team": team_id, "status": "FT", "last": n}
        ).json()
        fixtures = res.get("response", [])
        fixtures.sort(key=lambda x: x["fixture"]["date"])
        return fixtures
    except Exception:
        return []


def calculate_team_elo(team_id, base_elo=1500, k=32, n=20):
    """
    Calcula o ELO do time baseado nos últimos N jogos.
    Começa de 1500 e aplica fórmula ELO padrão em cada resultado.
    Retorna ELO atual e histórico.
    """
    global _elo_cache
    cache_key = str(team_id)
    if cache_key in _elo_cache:
        return _elo_cache[cache_key]

    fixtures = _get_team_fixtures_for_elo(team_id, n)
    if not fixtures:
        result = {"elo": base_elo, "history": [], "games": 0, "trend": 0.0}
        _elo_cache[cache_key] = result
        return result

    elo = float(base_elo)
    history = []

    for f in fixtures:
        is_home = int(f["teams"]["home"]["id"]) == int(team_id)
        gf = f["goals"]["home"] if is_home else f["goals"]["away"]
        gc = f["goals"]["away"] if is_home else f["goals"]["home"]

        if gf is None or gc is None:
            continue

        # ELO contextual: usa cache se disponível, evita recursão infinita
        opp_id_key = str(int(f["teams"]["away"]["id"]) if is_home else int(f["teams"]["home"]["id"]))
        opp_elo = _elo_cache[opp_id_key]["elo"] if opp_id_key in _elo_cache else 1500.0

        # Score esperado usando fórmula ELO oficial
        expected = 1.0 / (1.0 + 10.0 ** ((opp_elo - elo) / 400.0))

        # Score real: vitória=1, empate=0.5, derrota=0
        if gf > gc:
            actual = 1.0
        elif gf == gc:
            actual = 0.5
        else:
            actual = 0.0

        # Atualização com K-factor
        elo = elo + k * (actual - expected)
        history.append(round(elo, 1))

    result = {
        "elo": round(elo, 1),
        "history": history[-5:],
        "games": len(history),
        "trend": round(history[-1] - history[-3], 1) if len(history) >= 3 else 0.0
    }
    _elo_cache[cache_key] = result
    return result


def elo_win_probability(elo_home, elo_away):
    """
    Calcula probabilidades de vitória/empate/derrota baseadas no ELO.
    Usa modelo de Nate Silver (538) adaptado para futebol.
    """
    diff = elo_home - elo_away
    # Probabilidade de vitória do mandante via ELO
    p_home_win = 1.0 / (1.0 + 10.0 ** (-diff / 400.0))
    # Empate modelado como sobreposição gaussiana (aprox.)
    draw_factor = 0.22 * (1.0 - abs(diff) / 1000.0)
    draw_factor = max(0.08, min(0.30, draw_factor))
    p_draw = draw_factor
    p_home_win = p_home_win * (1.0 - draw_factor)
    p_away_win = 1.0 - p_home_win - p_draw
    return {
        "home_win": round(max(0.05, p_home_win), 4),
        "draw": round(max(0.05, p_draw), 4),
        "away_win": round(max(0.05, p_away_win), 4),
        "elo_diff": diff
    }


# =====================================================================
# MÓDULO 4 - PRESSURE INDEX (PRÉ-LIVE, BASEADO EM HISTÓRICO)
# =====================================================================

def calculate_historical_pressure_index(avg_shots, avg_sot, avg_corners,
                                         avg_dangerous_attacks=None,
                                         avg_crosses=None, avg_blocked=None):
    """
    Pressure Index pré-live calculado a partir de médias históricas.
    Fórmula proprietária escalada para 0-100.
    Dangerous attacks e crosses são opcionais (nem sempre disponíveis).
    """
    # Estimativa de dangerous attacks se não disponível: proxy = shots * 2.5
    da = avg_dangerous_attacks if avg_dangerous_attacks is not None else avg_shots * 2.5
    crosses = avg_crosses if avg_crosses is not None else avg_corners * 1.8
    blocked = avg_blocked if avg_blocked is not None else avg_sot * 0.4

    raw = (
        0.25 * avg_shots
        + 0.30 * avg_sot
        + 0.15 * avg_corners
        + 0.20 * (da / 10.0)   # normaliza dangerous attacks
        + 0.05 * (crosses / 5.0)
        + 0.05 * (blocked / 3.0)
    )

    # Escala: raw típico varia ~0-8; mapeia para 0-100
    scaled = min(100.0, max(0.0, raw * 12.5))

    if scaled <= 30:
        label = "Baixa pressão"
    elif scaled <= 60:
        label = "Pressão moderada"
    elif scaled <= 80:
        label = "Alta pressão"
    else:
        label = "Pressão extrema"

    return {"index": round(scaled, 1), "label": label, "raw": round(raw, 3)}


# =====================================================================
# MÓDULO 5 - EXPECTED VALUE AVANÇADO
# =====================================================================

def calculate_advanced_ev(model_probs, odds, label_map=None):
    """
    EV = (Probabilidade_Modelo × Odd) − 1
    model_probs: dict com chaves como 'home', 'draw', 'away', 'btts', 'over25', etc.
    odds: dict com mesmas chaves (odds decimais reais)
    Retorna dict com EV por mercado e alertas.
    """
    if not model_probs or not odds:
        return None
    ev_results = {}
    alerts = []
    for key, prob in model_probs.items():
        odd = odds.get(key)
        if odd is None or odd <= 0:
            continue
        ev = (prob * odd) - 1.0
        ev_pct = ev * 100.0
        ev_results[key] = {
            "ev": round(ev, 4),
            "ev_pct": round(ev_pct, 2),
            "prob_model": round(prob * 100, 1),
            "odd": odd,
            "label": label_map.get(key, key) if label_map else key
        }
        if ev_pct > 15:
            alerts.append(f"🔥 EV ELITE +{ev_pct:.1f}% em {label_map.get(key, key) if label_map else key}")
        elif ev_pct > 10:
            alerts.append(f"✅ EV FORTE +{ev_pct:.1f}% em {label_map.get(key, key) if label_map else key}")
        elif ev_pct > 5:
            alerts.append(f"📊 EV POSITIVO +{ev_pct:.1f}% em {label_map.get(key, key) if label_map else key}")
    return {"markets": ev_results, "alerts": alerts}


def get_additional_odds(fixture_id):
    """
    Busca odds adicionais (BTTS, Over/Under, Escanteios) via API.
    bet IDs: 5=BTTS, 5=Goals Over/Under, 45=Corners
    """
    import requests as _req
    result = {}
    for label, bet_id in [("btts", 5), ("goals_ou", 18), ("corners_ou", 45)]:
        try:
            res = _req.get(
                f"{BASE_URL}/odds",
                headers=headers,
                params={"fixture": fixture_id, "bet": bet_id}
            ).json()
            response = res.get("response", [])
            if not response:
                continue
            for bm in response[0].get("bookmakers", []):
                for bet in bm.get("bets", []):
                    values = {v["value"]: float(v["odd"]) for v in bet.get("values", [])}
                    if label == "btts":
                        if "Yes" in values:
                            result["btts"] = values["Yes"]
                        if "No" in values:
                            result["btts_no"] = values["No"]
                    elif label == "goals_ou":
                        for k, v in values.items():
                            if "Over" in k:
                                try:
                                    line = float(k.replace("Over", "").strip())
                                    result[f"over{str(line).replace('.', '')}"] = v
                                except Exception:
                                    pass
                    elif label == "corners_ou":
                        for k, v in values.items():
                            if "Over" in k:
                                try:
                                    result[f"corners_{k.lower().replace(' ', '')}"] = v
                                except Exception:
                                    pass
                break
        except Exception:
            continue
    return result


# =====================================================================
# MÓDULO 6 - ODDS MOVEMENT
# =====================================================================

# Armazena odds de abertura (primeira consulta) por fixture_id
_odds_opening_store = {}


def track_odds_movement(fixture_id, current_odds):
    """
    Registra a abertura das odds na primeira vez que é chamado para um fixture.
    Subsequentemente, calcula a variação e detecta steam moves.
    """
    global _odds_opening_store
    if not current_odds:
        return None

    fid_key = str(fixture_id)
    if fid_key not in _odds_opening_store:
        _odds_opening_store[fid_key] = {
            "home": current_odds.get("home"),
            "draw": current_odds.get("draw"),
            "away": current_odds.get("away"),
            "timestamp": str(datetime.datetime.now())
        }
        return {"status": "opening_registered", "opening": _odds_opening_store[fid_key]}

    opening = _odds_opening_store[fid_key]
    movement = {}
    alerts = []

    for side in ["home", "draw", "away"]:
        op = opening.get(side)
        cur = current_odds.get(side)
        if op and cur and op > 0:
            chg_pct = ((cur - op) / op) * 100.0
            movement[side] = {
                "opening": op,
                "current": cur,
                "change_pct": round(chg_pct, 2),
                "direction": "queda" if chg_pct < 0 else "subida"
            }
            # Steam move detection
            if chg_pct <= -30:
                alerts.append(f"🚨 MOVIMENTO EXTREMO: {side.upper()} caiu {abs(chg_pct):.1f}% — POSSÍVEL DINHEIRO PROFISSIONAL")
            elif chg_pct <= -20:
                alerts.append(f"🔴 FORTE MOVIMENTO DE MERCADO: {side.upper()} caiu {abs(chg_pct):.1f}%")
            elif chg_pct <= -10:
                alerts.append(f"🟡 MOVIMENTO RELEVANTE: {side.upper()} caiu {abs(chg_pct):.1f}%")

    return {"movement": movement, "alerts": alerts, "opening": opening}


# =====================================================================
# MÓDULO 7 - REFEREE SCORE
# =====================================================================

def get_referee_stats(referee_name, season=2024, sample=20):
    """
    Busca estatísticas históricas do árbitro via /fixtures com filtro de árbitro.
    Calcula: amarelos/jogo, vermelhos/jogo, pênaltis/jogo, faltas/jogo.
    Retorna Referee Score 0-100.
    """
    import requests as _req
    if not referee_name:
        return None
    yellows, reds, games_found = [], [], 0
    try:
        res = _req.get(
            f"{BASE_URL}/fixtures",
            headers=headers,
            params={"referee": referee_name, "season": season, "status": "FT", "last": sample}
        ).json()
        fixtures = res.get("response", [])
        for f in fixtures:
            fid = f["fixture"]["id"]
            try:
                sr = _req.get(
                    f"{BASE_URL}/fixtures/statistics",
                    headers=headers,
                    params={"fixture": fid}
                ).json().get("response", [])
                yel = red = 0
                for block in sr:
                    for stat in block.get("statistics", []):
                        if stat["type"] == "Yellow Cards":
                            v = stat.get("value") or 0
                            try:
                                yel += int(v)
                            except Exception:
                                pass
                        if stat["type"] == "Red Cards":
                            v = stat.get("value") or 0
                            try:
                                red += int(v)
                            except Exception:
                                pass
                yellows.append(yel)
                reds.append(red)
                games_found += 1
            except Exception:
                continue
    except Exception:
        return None

    if games_found == 0:
        return None

    avg_y = sum(yellows) / games_found
    avg_r = sum(reds) / games_found

    # Referee Score: baseado em volume de cartões
    # Mais cartões = score mais alto (árbitro mais rigoroso)
    raw_score = (avg_y * 10) + (avg_r * 25)
    score = min(100, max(0, int(raw_score)))

    if score <= 25:
        label = "Permissivo"
    elif score <= 50:
        label = "Moderado"
    elif score <= 75:
        label = "Rigoroso"
    else:
        label = "Extremamente rigoroso"

    return {
        "referee": referee_name,
        "games_sampled": games_found,
        "avg_yellows_per_game": round(avg_y, 2),
        "avg_reds_per_game": round(avg_r, 2),
        "referee_score": score,
        "label": label
    }


# =====================================================================
# MÓDULO 8 - ESCANTEIOS AVANÇADOS
# =====================================================================

def calculate_advanced_corners(h_metrics_blended, a_metrics_blended,
                                h_pressure_idx, a_pressure_idx):
    """
    Modelo avançado de escanteios usando métricas combinadas casa/fora + Pressure Index.
    Retorna expected corners, probabilidades Over 7.5 até 11.5, e corner_trace.
    Safety cap: total cannot exceed base_historical * 1.50.
    """
    import math as _math

    # Base historical corners
    base_h_hist = h_metrics_blended.get("avg_corners", 5.0)
    base_a_hist = a_metrics_blended.get("avg_corners", 5.0)
    base_historical = base_h_hist + base_a_hist

    # Pressure adjustment component
    h_pressure_adj = (h_pressure_idx / 100.0) * 3.0
    a_pressure_adj = (a_pressure_idx / 100.0) * 3.0

    # Possession adjustment component
    h_possession_adj = h_metrics_blended.get("avg_possession", 50.0) * 0.02
    a_possession_adj = a_metrics_blended.get("avg_possession", 50.0) * 0.02

    h_exp_raw = (
        base_h_hist * 0.35
        + h_metrics_blended.get("avg_shots", 12.0) * 0.15
        + h_metrics_blended.get("avg_sot", 4.0) * 0.20
        + h_pressure_adj
        + h_possession_adj
    )
    a_exp_raw = (
        base_a_hist * 0.35
        + a_metrics_blended.get("avg_shots", 12.0) * 0.15
        + a_metrics_blended.get("avg_sot", 4.0) * 0.20
        + a_pressure_adj
        + a_possession_adj
    )

    total_raw = h_exp_raw + a_exp_raw

    # Safety cap: total cannot exceed base_historical * 1.50
    max_corner_multiplier = 1.50
    cap_total = base_historical * max_corner_multiplier
    cap_applied = total_raw > cap_total
    if cap_applied and total_raw > 0:
        scale = cap_total / total_raw
        h_exp = h_exp_raw * scale
        a_exp = a_exp_raw * scale
    else:
        h_exp = h_exp_raw
        a_exp = a_exp_raw

    total_exp = h_exp + a_exp

    # corner_trace for debugging/display
    corner_trace = {
        "base_historical":   round(base_historical, 2),
        "pressure_adj":      round(h_pressure_adj + a_pressure_adj, 2),
        "possession_adj":    round(h_possession_adj + a_possession_adj, 2),
        "climate_adj":       0.0,  # reserved for future climate integration
        "total_expected":    round(total_exp, 2),
        "max_cap_applied":   cap_applied,
    }

    # Probabilidades via distribuição de Poisson para cada linha
    def poisson_over(lam, line):
        p_under = sum(
            (_math.exp(-lam) * (lam ** k)) / _math.factorial(k)
            for k in range(int(line) + 1)
        )
        return max(0.0, min(1.0, 1.0 - p_under))

    lines = [7.5, 8.5, 9.5, 10.5, 11.5]
    probs = {}
    for line in lines:
        probs[f"over_{str(line).replace('.', '')}"] = round(poisson_over(total_exp, line), 4)

    corner_pressure = round((h_exp - a_exp) / max(total_exp, 0.1) * 100, 1)

    return {
        "h_expected_corners": round(h_exp, 2),
        "a_expected_corners": round(a_exp, 2),
        "total_expected": round(total_exp, 2),
        "corner_pressure": corner_pressure,  # positivo = mandante domina escanteios
        "probabilities": probs,
        "corner_trace": corner_trace,
    }


# =====================================================================
# MÓDULO 9 - MONTE CARLO
# =====================================================================

def run_monte_carlo(lambda_home, lambda_away, n_simulations=100000,
                    elo_weight=0.0, xg_lambda_home=None, xg_lambda_away=None):
    """
    Simula N partidas usando Poisson ajustada com xG e ELO.
    Retorna probabilidades de vitória, empate, derrota, BTTS, Over/Under
    e os 10 placares mais frequentes.
    """
    import random as _rand
    import math as _math

    # lambda_home já é o lambda calibrado (inclui xG blend feito no orchestrator).
    # xg_lambda_home é o mesmo valor — NÃO fazer double-blend.
    # Se por algum motivo lambda_home e xg_lambda_home forem diferentes, usa lambda_home.
    lh = lambda_home
    la = lambda_away

    # Ajuste por ELO: modifica lambda proporcionalmente à diferença de ELO
    if elo_weight != 0.0:
        elo_adj = 1.0 + (elo_weight * 0.001)  # elo_weight = diff em pontos
        lh = lh * max(0.85, min(1.15, elo_adj))
        la = la * max(0.85, min(1.15, 1.0 / max(0.01, elo_adj)))

    lh = max(0.1, lh)
    la = max(0.1, la)

    # Tabela cumulativa de Poisson para sampling eficiente
    def build_cdf(lam, max_goals=10):
        pmf = [(_math.exp(-lam) * (lam ** k)) / _math.factorial(k) for k in range(max_goals + 1)]
        cdf = []
        cumsum = 0.0
        for p in pmf:
            cumsum += p
            cdf.append(cumsum)
        return cdf

    def sample_poisson(cdf):
        r = _rand.random()
        for k, c in enumerate(cdf):
            if r <= c:
                return k
        return len(cdf) - 1

    cdf_h = build_cdf(lh)
    cdf_a = build_cdf(la)

    home_wins = draws = away_wins = 0
    btts = over15 = over25 = over35 = 0
    score_counts = {}

    for _ in range(n_simulations):
        hg = sample_poisson(cdf_h)
        ag = sample_poisson(cdf_a)
        if hg > ag:
            home_wins += 1
        elif hg == ag:
            draws += 1
        else:
            away_wins += 1
        if hg > 0 and ag > 0:
            btts += 1
        total = hg + ag
        if total > 1:
            over15 += 1
        if total > 2:
            over25 += 1
        if total > 3:
            over35 += 1
        key = f"{hg}x{ag}"
        score_counts[key] = score_counts.get(key, 0) + 1

    n = n_simulations
    top_scores = sorted(score_counts.items(), key=lambda x: x[1], reverse=True)[:10]

    return {
        "simulations": n,
        "home_win": round(home_wins / n, 4),
        "draw": round(draws / n, 4),
        "away_win": round(away_wins / n, 4),
        "btts": round(btts / n, 4),
        "over15": round(over15 / n, 4),
        "over25": round(over25 / n, 4),
        "over35": round(over35 / n, 4),
        "top_scores": [(s, round(c / n * 100, 2)) for s, c in top_scores],
        "lambda_used": {"home": round(lh, 3), "away": round(la, 3)}
    }


# =====================================================================
# MÓDULO 10 - MACHINE LEARNING (PIPELINE ESTRUTURAL)
# =====================================================================

def extract_ml_features(h_metrics, a_metrics, h_elo, a_elo,
                         h_pressure, a_pressure, h_rest, a_rest,
                         real_odds, referee_score):
    """
    Extrai feature vector para o modelo de ML.
    Não treina em tempo real — prepara features para modelo pré-treinado futuro.
    Retorna dict com todas as features nomeadas.
    """
    def safe(v, default=0.0):
        try:
            return float(v) if v is not None else float(default)
        except Exception:
            return float(default)

    features = {
        # xG / Ataque
        "h_avg_gf": safe(h_metrics.get("avg_gf")),
        "a_avg_gf": safe(a_metrics.get("avg_gf")),
        "h_avg_gc": safe(h_metrics.get("avg_gc")),
        "a_avg_gc": safe(a_metrics.get("avg_gc")),
        # Chutes
        "h_avg_shots": safe(h_metrics.get("avg_shots")),
        "a_avg_shots": safe(a_metrics.get("avg_shots")),
        "h_avg_sot": safe(h_metrics.get("avg_sot")),
        "a_avg_sot": safe(a_metrics.get("avg_sot")),
        # Posse e Escanteios
        "h_avg_possession": safe(h_metrics.get("avg_possession", 50)),
        "a_avg_possession": safe(a_metrics.get("avg_possession", 50)),
        "h_avg_corners": safe(h_metrics.get("avg_corners")),
        "a_avg_corners": safe(a_metrics.get("avg_corners")),
        # ELO
        "h_elo": safe(h_elo.get("elo", 1500) if h_elo else 1500),
        "a_elo": safe(a_elo.get("elo", 1500) if a_elo else 1500),
        "elo_diff": safe((h_elo.get("elo", 1500) if h_elo else 1500) - (a_elo.get("elo", 1500) if a_elo else 1500)),
        # Pressure Index
        "h_pressure": safe(h_pressure.get("index", 50) if h_pressure else 50),
        "a_pressure": safe(a_pressure.get("index", 50) if a_pressure else 50),
        # Descanso
        "h_rest_days": safe(h_rest),
        "a_rest_days": safe(a_rest),
        # Odds (implied probability)
        "odd_h_implied": safe(1.0 / real_odds["home"] if real_odds and real_odds.get("home") else 0),
        "odd_d_implied": safe(1.0 / real_odds["draw"] if real_odds and real_odds.get("draw") else 0),
        "odd_a_implied": safe(1.0 / real_odds["away"] if real_odds and real_odds.get("away") else 0),
        # Árbitro
        "referee_score": safe(referee_score.get("referee_score", 50) if referee_score else 50),
    }
    return features


def ml_model_predict(features):
    """
    Logistic Regression manual (stdlib only — sem sklearn).
    Delega para ml_logistic_predict() definida na FASE DE CALIBRAÇÃO PROFISSIONAL.
    Python resolve nomes em tempo de execução, então forward-reference é seguro.
    """
    return ml_logistic_predict(features) if features else None


# =====================================================================
# MÓDULO 11 - CONFIDENCE SCORE
# =====================================================================

def calculate_confidence_score(h_count, a_count, poisson_probs, mc_probs,
                                 real_odds, odds_movement, data_quality_score):
    """
    Confidence Score 0-100 baseado em:
    - Quantidade de amostra (30%)
    - Consistência entre modelos (25%)
    - Qualidade dos dados (20%)
    - Disponibilidade de odds (15%)
    - Movimento de mercado (10%)
    """
    # 1. Amostra
    min_games = min(h_count, a_count)
    sample_score = min(100.0, (min_games / 10.0) * 100.0)

    # 2. Consistência entre modelos (diferença entre Poisson e Monte Carlo)
    if poisson_probs and mc_probs:
        diff_home = abs(poisson_probs.get("home_win", 0.33) - mc_probs.get("home_win", 0.33))
        diff_away = abs(poisson_probs.get("away_win", 0.33) - mc_probs.get("away_win", 0.33))
        avg_diff = (diff_home + diff_away) / 2.0
        consistency_score = max(0.0, 100.0 - avg_diff * 300.0)
    else:
        consistency_score = 50.0

    # 3. Qualidade dos dados
    quality = float(data_quality_score)

    # 4. Disponibilidade de odds
    odds_score = 100.0 if real_odds else 0.0

    # 5. Movimento de mercado (alertas = menos confiança que o modelo capture info não-pública)
    if odds_movement and odds_movement.get("alerts"):
        market_score = max(20.0, 80.0 - len(odds_movement["alerts"]) * 15.0)
    else:
        market_score = 70.0

    final = (
        sample_score * 0.30
        + consistency_score * 0.25
        + quality * 0.20
        + odds_score * 0.15
        + market_score * 0.10
    )
    final = max(0.0, min(100.0, final))

    if final >= 80:
        label = "Elite"
    elif final >= 60:
        label = "Alta confiança"
    elif final >= 40:
        label = "Média confiança"
    else:
        label = "Baixa confiança"

    return {"score": round(final, 1), "label": label,
            "components": {
                "amostra": round(sample_score, 1),
                "consistencia": round(consistency_score, 1),
                "qualidade_dados": round(quality, 1),
                "odds_disponiveis": round(odds_score, 1),
                "mercado": round(market_score, 1)
            }}


# =====================================================================
# MÓDULO 12 - ENSEMBLE (CONSENSO ENTRE MODELOS)
# =====================================================================

def _validate_model_probs(name, probs):
    """
    Model Integrity Check: verifica que o dict de probabilidades é válido.
    Retorna (probs_validados, status_msg).
    Critérios: soma 1.0 ± 3%, nenhum valor None/NaN/0 nos 3 outcomes.
    """
    import math as _m
    if probs is None:
        return None, f"{name}: INVÁLIDO (None)"
    outcomes = ["home_win", "draw", "away_win"]
    vals = []
    for o in outcomes:
        v = probs.get(o)
        if v is None:
            return None, f"{name}: INVÁLIDO ('{o}' ausente)"
        try:
            vf = float(v)
        except Exception:
            return None, f"{name}: INVÁLIDO ('{o}' não numérico)"
        if _m.isnan(vf) or _m.isinf(vf):
            return None, f"{name}: INVÁLIDO ('{o}' NaN/Inf)"
        if vf <= 0.0:
            return None, f"{name}: INVÁLIDO ('{o}'=0 ou negativo)"
        vals.append(vf)
    total = sum(vals)
    if abs(total - 1.0) > 0.03:
        # Tentar normalizar
        if total > 0:
            probs = {**probs, **{o: round(probs[o] / total, 4) for o in outcomes}}
        else:
            return None, f"{name}: INVÁLIDO (soma={total:.3f})"
    return probs, f"{name}: OK (soma={total:.3f})"


def calculate_ensemble_probability(poisson_probs, mc_probs, ml_probs,
                                    xg_probs, elo_probs, api_probs=None):
    """
    Ensemble ponderado com Model Integrity Check.
    Pesos: MC=30%, Poisson=25%, ML=20%, API=15%, ELO=10%
    Modelos inválidos são excluídos automaticamente e pesos redistribuídos.
    """
    BASE_WEIGHTS = {
        "monte_carlo": 0.30,
        "poisson":     0.25,
        "ml":          0.20,
        "api":         0.15,
        "elo":         0.10,
    }

    raw_sources = {
        "monte_carlo": mc_probs,
        "poisson":     poisson_probs,
        "ml":          ml_probs,
        "api":         api_probs,
        "elo":         elo_probs,
    }

    # Validar cada modelo
    available  = {}
    audit_log  = []
    for name, probs in raw_sources.items():
        validated, msg = _validate_model_probs(name, probs)
        audit_log.append(msg)
        if validated is not None:
            available[name] = validated

    if not available:
        return None

    # Redistribuir pesos proporcional ao peso base
    total_weight = sum(BASE_WEIGHTS[k] for k in available)
    norm_weights = {k: BASE_WEIGHTS[k] / total_weight for k in available}

    outcomes = ["home_win", "draw", "away_win"]
    ensemble = {}
    for outcome in outcomes:
        val = 0.0
        for src, probs in available.items():
            # Sem fallback silencioso — só usa probs já validados com a chave presente
            val += probs[outcome] * norm_weights[src]
        ensemble[outcome] = round(val, 4)

    # Normaliza final para garantir soma exata = 1.0
    total = sum(ensemble[o] for o in outcomes)
    if total > 0:
        for o in outcomes:
            ensemble[o] = round(ensemble[o] / total, 4)

    # BTTS ensemble
    btts_sources = [(src, probs.get("btts")) for src, probs in available.items() if probs.get("btts") is not None]
    if btts_sources:
        ensemble["btts"] = round(
            sum(p * norm_weights[src] for src, p in btts_sources) /
            sum(norm_weights[src] for src, _ in btts_sources), 4
        )

    # Over 2.5 ensemble
    over25_sources = [(src, probs.get("over25")) for src, probs in available.items() if probs.get("over25") is not None]
    if over25_sources:
        ensemble["over25"] = round(
            sum(p * norm_weights[src] for src, p in over25_sources) /
            sum(norm_weights[src] for src, _ in over25_sources), 4
        )

    ensemble["sources_used"]  = list(available.keys())
    ensemble["excluded"]      = [n for n in raw_sources if n not in available]
    ensemble["audit_log"]     = audit_log
    ensemble["norm_weights"]  = {k: round(v, 3) for k, v in norm_weights.items()}
    ensemble["weights_used"] = {k: round(norm_weights[k], 3) for k in available}
    return ensemble


def calculate_consistency_audit(ensemble, mc_probs, poisson_probs, elo_probs,
                                 ml_probs, api_probs, scenarios):
    """
    CORRECTION 4 — Global Consistency Auditor.
    Collects home_win probability from each model, computes std deviation,
    flags conflicts between ensemble and scenario #1, returns impact on confidence.
    """
    import math as _math

    model_values = {}
    for name, probs in [
        ("monte_carlo", mc_probs),
        ("poisson",     poisson_probs),
        ("elo",         elo_probs),
        ("ml",          ml_probs),
        ("api",         api_probs),
    ]:
        if probs and isinstance(probs, dict) and probs.get("home_win") is not None:
            try:
                model_values[name] = float(probs["home_win"])
            except (TypeError, ValueError):
                pass

    models_used = list(model_values.keys())
    values = list(model_values.values())

    if len(values) >= 2:
        mean_val = sum(values) / len(values)
        variance = sum((v - mean_val) ** 2 for v in values) / len(values)
        std_dev  = _math.sqrt(variance)
    elif len(values) == 1:
        std_dev = 0.0
    else:
        std_dev = 0.0

    if std_dev > 0.15:
        level = "CRÍTICA"
        impact = -20
    elif std_dev > 0.10:
        level = "ALTA"
        impact = -12
    elif std_dev > 0.06:
        level = "MÉDIA"
        impact = -6
    else:
        level = "BAIXA"
        impact = 0

    conflicts = []
    if ensemble and scenarios:
        ens_hw = ensemble.get("home_win", 0)
        ens_aw = ensemble.get("away_win", 0)
        sc1 = scenarios[0] if scenarios else None
        if sc1:
            sc1_title = sc1.get("title", "")
            sc1_favors_home = ("Mandante" in sc1_title or "Home" in sc1_title)
            sc1_favors_away = ("Visitante" in sc1_title or "Away" in sc1_title)
            ens_favors_home = ens_hw > ens_aw
            if sc1_favors_home and not ens_favors_home:
                conflicts.append("Cenário #1 favorece mandante mas ensemble favorece visitante")
            elif sc1_favors_away and ens_favors_home:
                conflicts.append("Cenário #1 favorece visitante mas ensemble favorece mandante")

    return {
        "level":                level,
        "std_dev":              round(std_dev, 4),
        "conflicts":            conflicts,
        "models_used":          models_used,
        "impact_on_confidence": impact,
    }


