# MÓDULOS V5 — ANÁLISE TÁTICA E ESTATÍSTICA AVANÇADA (v2 — dados reais)
# =====================================================================

def _fetch_detailed_game_data(hist, team_id, n=8):
    """
    Busca /fixtures/statistics E /fixtures/events para os últimos N jogos.
    Retorna lista de dicts com stats do time, stats do adversário e eventos.
    Uma chamada por fixture (stats) + uma (events) = 2N chamadas API.
    """
    import requests as _rq
    results = []
    for f in (hist or [])[:n]:
        fid    = f["fixture"]["id"]
        hid    = int(f["teams"]["home"]["id"])
        aid    = int(f["teams"]["away"]["id"])
        is_home = hid == int(team_id)
        opp_id  = aid if is_home else hid

        team_stats = {}
        opp_stats  = {}
        try:
            r = _rq.get(f"{BASE_URL}/fixtures/statistics",
                        headers=headers, params={"fixture": fid}, timeout=8).json()
            for blk in r.get("response", []):
                bid = int(blk.get("team", {}).get("id", -1))
                sd  = {}
                for s in blk.get("statistics", []):
                    raw = s.get("value")
                    # normalise: "45%" → 45.0, None → 0
                    if raw is None:
                        v = 0.0
                    elif isinstance(raw, str) and raw.endswith("%"):
                        try: v = float(raw[:-1])
                        except: v = 0.0
                    else:
                        try: v = float(raw)
                        except: v = 0.0
                    sd[s["type"].lower()] = v
                if bid == int(team_id):
                    team_stats = sd
                else:
                    opp_stats = sd
        except Exception:
            pass

        events_list = []
        try:
            r = _rq.get(f"{BASE_URL}/fixtures/events",
                        headers=headers, params={"fixture": fid}, timeout=8).json()
            events_list = r.get("response", [])
        except Exception:
            pass

        results.append({
            "fixture_id": fid,
            "is_home":    is_home,
            "opp_id":     opp_id,
            "date":       f["fixture"]["date"][:10],
            "stats":      team_stats,
            "opp_stats":  opp_stats,
            "events":     events_list,
        })
    return results


def _stat(sd, *keys, default=0.0):
    """Busca stat por múltiplas variações de nome (case-insensitive)."""
    for k in keys:
        for sk, sv in sd.items():
            if k.lower() in sk:
                return sv
    return default


def calculate_tactical_profile(hist, blended, team_id, lineups_data=None):
    """Classifica perfil tático do time com base em dados reais do blended."""
    if not blended:
        return {"style": "Indefinido", "possession_style": "N/A", "pressure": "N/A",
                "transition": "N/A", "attack_zone": "N/A", "defensive_line": "N/A",
                "construction": "N/A", "scores": {}, "press_score": 0, "possession": 50}

    possession = blended.get("avg_possession", 50) or 50
    shots      = blended.get("avg_shots", 12) or 12
    sot        = blended.get("avg_sot", 4) or 4
    corners    = blended.get("avg_corners", 5) or 5
    gf         = blended.get("avg_gf", 1.3) or 1.3
    gc         = blended.get("avg_gc", 1.1) or 1.1
    dangerous  = blended.get("avg_dangerous_attacks", 40) or 40
    attacks    = blended.get("avg_attacks", 120) or 120

    # Posse de bola
    if possession >= 58:   possession_style = "Domínio Total"
    elif possession >= 52: possession_style = "Jogo Posicional"
    elif possession >= 46: possession_style = "Equilibrado"
    else:                  possession_style = "Jogo Direto"

    # Pressão alta
    press_score = min(100, shots * 3 + dangerous * 0.8)
    if press_score >= 75:   pressure = "Alta Pressão"
    elif press_score >= 50: pressure = "Pressão Moderada"
    else:                   pressure = "Bloco Baixo"

    # Transição
    danger_ratio = dangerous / max(attacks, 1)
    if danger_ratio >= 0.38:           transition = "Transição Direta"
    elif possession >= 55 and shots >= 14: transition = "Posse Ofensiva"
    else:                               transition = "Controle Defensivo"

    # Zona de ataque
    if corners >= 7 and shots >= 15:         attack_zone = "Ataque Aéreo+Chutes"
    elif sot / max(shots, 1) >= 0.40:        attack_zone = "Finalização Eficiente"
    elif attacks >= 130:                     attack_zone = "Volume de Ataques"
    else:                                    attack_zone = "Ataque Padrão"

    # Linha defensiva
    if gc <= 0.8:   defensive_line = "Defesa Sólida"
    elif gc <= 1.2: defensive_line = "Defesa Organizada"
    else:           defensive_line = "Linha Alta / Vulnerável"

    # Construção
    if possession >= 56 and gf >= 1.5: construction = "Posse + Produção"
    elif gf >= 1.8:                    construction = "Ataque Efetivo"
    elif possession < 48 and gf >= 1.2:construction = "Contra-Ataque"
    else:                              construction = "Pragmático"

    # Estilo principal
    if possession >= 57:              style = "Posse de Bola"
    elif press_score >= 70 and possession < 55: style = "Pressão Alta"
    elif danger_ratio >= 0.40 and possession < 52: style = "Transição Rápida"
    elif gc <= 0.9:                   style = "Defensivo / Sólido"
    else:                             style = "Equilibrado"

    return {
        "style": style, "possession_style": possession_style,
        "pressure": pressure, "transition": transition,
        "attack_zone": attack_zone, "defensive_line": defensive_line,
        "construction": construction,
        "scores": {}, "press_score": round(press_score, 1), "possession": possession,
    }


def calculate_tactical_matchup(h_profile, a_profile, h_name, a_name,
                               ppda_h=None, ppda_a=None,
                               field_tilt=None, xthreat=None,
                               zones_h=None, zones_a=None,
                               lineups=None):
    """
    Tactical Edge Score V2 — usa PPDA, Field Tilt, xThreat, zonas de pressão,
    progressões, formação e escalações além dos perfis táticos históricos.
    Escala 0-100: 0-20 grande vantagem visitante, 80-100 grande vantagem mandante.
    """
    if not h_profile or not a_profile:
        return {"score": 50, "advantages": [], "vulnerabilities": [], "summary": "Dados insuficientes",
                "edge_breakdown": {}, "narrative": []}

    def _safe(v, d=0.0):
        try: return float(v) if v is not None else d
        except: return d

    advantages      = []
    vulnerabilities = []
    narrative       = []
    edge_breakdown  = {}
    score = 50.0

    h_press = _safe(h_profile.get("press_score"), 50)
    a_press = _safe(a_profile.get("press_score"), 50)
    h_poss  = _safe(h_profile.get("possession"), 50)
    a_poss  = _safe(a_profile.get("possession"), 50)

    # ── Field Tilt (peso 12 pts) ──────────────────────────────────────
    ft_delta = 0.0
    if field_tilt:
        ft_h = _safe(field_tilt.get("home_tilt"), 50)
        ft_delta = (ft_h - 50.0) * 0.24   # 0.24 pt por % de field tilt
        score += ft_delta
        edge_breakdown["FieldTilt"] = round(ft_delta, 1)
        if ft_h >= 60:
            advantages.append(f"{h_name[:14]}: domínio territorial — Field Tilt {ft_h:.0f}% vs {100-ft_h:.0f}%")
            narrative.append(f"{h_name[:14]} deve controlar a posse e o terço final adversário.")
        elif ft_h <= 40:
            advantages.append(f"{a_name[:14]}: domínio territorial — Field Tilt {100-ft_h:.0f}% vs {ft_h:.0f}%")
            narrative.append(f"{a_name[:14]} tende a pressionar o bloco defensivo adversário.")
        else:
            narrative.append(f"Field Tilt equilibrado — disputa territorial em aberto.")

    # ── xThreat (peso 10 pts) ─────────────────────────────────────────
    xt_delta = 0.0
    if xthreat:
        xt_h = _safe(xthreat.get("home_xthreat"), 50)
        xt_a = _safe(xthreat.get("away_xthreat"), 50)
        if xt_h + xt_a > 0:
            xt_share = (xt_h / (xt_h + xt_a)) * 100
            xt_delta = (xt_share - 50.0) * 0.20
            score += xt_delta
            edge_breakdown["xThreat"] = round(xt_delta, 1)
            if xt_share >= 58:
                advantages.append(f"{h_name[:14]}: cria mais ameaças reais (xT {xt_h:.1f} vs {xt_a:.1f})")
                narrative.append(f"{h_name[:14]} cria superioridade entre linhas e nas zonas de finalização.")
            elif xt_share <= 42:
                advantages.append(f"{a_name[:14]}: ameaça real maior (xT {xt_a:.1f} vs {xt_h:.1f})")
                narrative.append(f"{a_name[:14]} cria as melhores oportunidades — perigo real em contra-ataques.")

    # ── PPDA — Qualidade do Pressing (peso 8 pts) ─────────────────────
    ppda_delta = 0.0
    if ppda_h and ppda_a:
        ph_v = _safe(ppda_h.get("ppda"), 10)
        pa_v = _safe(ppda_a.get("ppda"), 10)
        if ph_v > 0 and pa_v > 0:
            # PPDA menor = pressing melhor; diferença normalizada por 5
            ppda_delta = (pa_v - ph_v) / 5.0 * 8.0
            ppda_delta = max(-8, min(8, ppda_delta))
            score += ppda_delta
            edge_breakdown["PPDA"] = round(ppda_delta, 1)
            if ph_v < pa_v - 2:
                advantages.append(f"{h_name[:14]}: pressing superior (PPDA {ph_v:.1f} vs {pa_v:.1f})")
                narrative.append(f"{h_name[:14]} recupera a bola mais rápido no campo adversário.")
            elif pa_v < ph_v - 2:
                advantages.append(f"{a_name[:14]}: pressing superior (PPDA {pa_v:.1f} vs {ph_v:.1f})")
                narrative.append(f"{a_name[:14]} força erros do adversário com pressão intensa.")

    # ── Posse de Bola (peso 6 pts) ────────────────────────────────────
    poss_delta = (h_poss - a_poss) / 10.0 * 3.0
    poss_delta = max(-6, min(6, poss_delta))
    score += poss_delta
    edge_breakdown["Posse"] = round(poss_delta, 1)
    if h_poss >= 56:
        narrative.append(f"{h_name[:14]} deve controlar o ritmo com posse de {h_poss:.0f}%.")
    elif a_poss >= 56:
        narrative.append(f"{a_name[:14]} deve ditar o jogo com posse de {a_poss:.0f}%.")

    # ── Pressão por zonas (peso 6 pts) ────────────────────────────────
    zones_delta = 0.0
    if zones_h and zones_a:
        h_hp = _safe(zones_h.get("high_pct"), 33)
        a_hp = _safe(zones_a.get("high_pct"), 33)
        zones_delta = (h_hp - a_hp) * 0.10
        zones_delta = max(-6, min(6, zones_delta))
        score += zones_delta
        edge_breakdown["Zonas"] = round(zones_delta, 1)
        if h_hp > a_hp + 10:
            advantages.append(f"{h_name[:14]}: pressiona mais no campo adversário ({h_hp:.0f}% alta pressão)")
            narrative.append(f"{h_name[:14]} ataca com blocos adiantados — força erros no campo adversário.")
        elif a_hp > h_hp + 10:
            advantages.append(f"{a_name[:14]}: pressiona em alta intensidade ({a_hp:.0f}% alta pressão)")

    # ── Press Score histórico (peso 5 pts) ────────────────────────────
    press_delta = (h_press - a_press) / 20.0 * 5.0
    press_delta = max(-5, min(5, press_delta))
    score += press_delta
    edge_breakdown["Pressing"] = round(press_delta, 1)

    # ── Linha defensiva vs Transição (peso 8 pts) ─────────────────────
    trans_delta = 0.0
    if h_profile.get("transition") == "Transição Direta" and a_profile.get("defensive_line") == "Linha Alta / Vulnerável":
        advantages.append(f"{h_name[:14]}: transição rápida explora linha alta visitante")
        narrative.append(f"Transições do {h_name[:14]} são a maior ameaça — linha alta do visitante cria espaço.")
        trans_delta += 8
    if a_profile.get("construction") in ["Contra-Ataque", "Transição Direta"]:
        if h_profile.get("defensive_line") == "Linha Alta / Vulnerável":
            vulnerabilities.append(f"{h_name[:14]}: linha alta vulnerável ao contra-ataque do {a_name[:14]}")
            narrative.append(f"A principal ameaça do {a_name[:14]} são transições rápidas após recuperação.")
            trans_delta -= 8
    score += trans_delta
    if trans_delta != 0:
        edge_breakdown["Transição"] = round(trans_delta, 1)

    # ── Escalação / Formação (peso 4 pts) ────────────────────────────
    form_delta = 0.0
    if lineups:
        h_form = next((tl.get("formation") for tl in lineups
                       if tl.get("team", {}).get("name", "")[:6].lower() in h_name[:6].lower()), None)
        a_form = next((tl.get("formation") for tl in lineups
                       if tl.get("team", {}).get("name", "")[:6].lower() in a_name[:6].lower()), None)
        if h_form and a_form:
            # Formações ofensivas favorecem mandante (campo familiar)
            off_forms = {"4-3-3", "4-2-3-1", "3-4-3", "4-1-4-1"}
            def_forms = {"5-4-1", "4-5-1", "5-3-2"}
            if h_form in off_forms and a_form in def_forms:
                form_delta = 4.0
                narrative.append(f"{h_name[:14]} ({h_form}) deve ter mais posse contra o bloco defensivo ({a_form}) do {a_name[:14]}.")
            elif a_form in off_forms and h_form in def_forms:
                form_delta = -4.0
                narrative.append(f"{a_name[:14]} ({a_form}) busca impor jogo ofensivo contra o bloco do {h_name[:14]} ({h_form}).")
            else:
                narrative.append(f"Formações espelhadas: {h_name[:10]} {h_form} vs {a_name[:10]} {a_form}.")
    score += form_delta
    if form_delta != 0:
        edge_breakdown["Formação"] = round(form_delta, 1)

    score = max(0.0, min(100.0, score))

    # Classificação e summary
    if score >= 80:
        summary = f"Grande vantagem tática para {h_name[:14]}"
        narrative.insert(0, f"{h_name[:14]} tem vantagem tática clara em múltiplas dimensões.")
    elif score >= 60:
        summary = f"Vantagem tática para {h_name[:14]}"
    elif score >= 55:
        summary = f"Leve vantagem tática para {h_name[:14]}"
    elif score <= 20:
        summary = f"Grande vantagem tática para {a_name[:14]}"
        narrative.insert(0, f"{a_name[:14]} domina taticamente em múltiplas dimensões.")
    elif score <= 40:
        summary = f"Vantagem tática para {a_name[:14]}"
    elif score <= 45:
        summary = f"Leve vantagem tática para {a_name[:14]}"
    else:
        summary = "Equilíbrio tático — fatores contextuais decidem"
        narrative.append("Nenhum time apresenta vantagem tática dominante. Contexto e forma física serão decisivos.")

    return {
        "score": round(score, 1),
        "advantages":    advantages,
        "vulnerabilities": vulnerabilities,
        "summary":       summary,
        "h_style":       h_profile.get("style", "?"),
        "a_style":       a_profile.get("style", "?"),
        "edge_breakdown": edge_breakdown,
        "narrative":     narrative,
    }


def generate_scenarios(ensemble, mc, matchup, climate_impact, fatigue_h, fatigue_i_a, h_name, a_name):
    """Gera 3 cenários probabilísticos com atributos detalhados."""
    hw   = ensemble.get("home_win", 0.35) if ensemble else 0.35
    dr   = ensemble.get("draw", 0.28) if ensemble else 0.28
    aw   = ensemble.get("away_win", 0.37) if ensemble else 0.37
    o25  = ensemble.get("over25", 0.55) if ensemble else 0.55
    btts = ensemble.get("btts", 0.50) if ensemble else 0.50

    climate_penalty = climate_impact.get("total_penalty", 0) if climate_impact else 0
    fat_diff        = (fatigue_h or 30) - (fatigue_i_a or 30)
    matchup_score   = matchup.get("score", 50) if matchup else 50

    # Cenário 1: favorito
    if hw >= aw:
        s1_prob  = hw
        s1_title = f"Vitória do Mandante ({h_name[:16]})"
        s1_goals = "1-0 ou 2-0 ou 2-1"
        _dom = "dominando a posse" if matchup_score >= 55 else "aproveitando transições"
        _btts_s = "Provável" if btts > 0.52 else "Improvável"
        _o25_s  = "Sim" if o25 > 0.55 else "Não"
        s1_desc = f"Mandante {_dom}. BTTS: {_btts_s}. Over 2.5: {_o25_s}."
        s1_key  = [f"Controle do mandante", f"BTTS: {_btts_s}", f"Over 2.5: {_o25_s}"]
    else:
        s1_prob  = aw
        s1_title = f"Vitória do Visitante ({a_name[:16]})"
        s1_goals = "0-1 ou 1-2 ou 0-2"
        _style_a = matchup.get("a_style", "") if matchup else ""
        _reason  = "Contra-ataque eficaz" if _style_a in ["Transição Rápida", "Pressão Alta"] else "Aproveita fragilidade defensiva"
        s1_desc  = f"{_reason}. Visitante controla nos momentos decisivos."
        s1_key   = [f"Contra-ataque visitante", f"Fadiga mandante: {'Alta' if fat_diff > 20 else 'Normal'}", f"Over 2.5: {'Sim' if o25 > 0.55 else 'Não'}"]

    # Cenário 2: empate
    s2_prob  = dr
    s2_title = "Empate"
    s2_goals = "0-0 ou 1-1 ou 2-2"
    _gols_s  = "Jogo truncado, poucas chances." if o25 < 0.45 else "Jogo movimentado mas sem desequilíbrio."
    _clima_s = " Chuva reduz ritmo." if (climate_impact and climate_impact.get("rain_penalty", 0) < -0.03) else ""
    s2_desc  = "Equilíbrio entre os times. " + _gols_s + _clima_s
    s2_key   = ["Equilíbrio tático", f"Under 2.5: {'Favorável' if o25 < 0.50 else 'Desfavorável'}", "Árbitro rígido = menos espaço"]

    # Cenário 3: jogo imprevisível
    s3_prob  = max(0.05, 1.0 - s1_prob - s2_prob)
    top_sc   = mc["top_scores"][0][0] if (mc and mc.get("top_scores")) else "2-1"
    over35   = mc.get("over35", 0.20) if mc else 0.20
    s3_title = "Jogo Imprevisível / Alta Goleada"
    s3_goals = f"3+ gols  (Top MC: {top_sc})"
    _clima3  = "adverso agrava erros" if climate_penalty < -0.05 else "não é fator crítico"
    s3_desc  = f"Erros defensivos, expulsões ou gols relâmpago. Clima {_clima3}."
    s3_key   = ["Erros defensivos", "Gols em bola parada", f"Over 3.5: {over35*100:.0f}%"]

    scenarios = [
        {"id": 1, "title": s1_title, "prob": s1_prob, "goals": s1_goals, "desc": s1_desc, "keys": s1_key},
        {"id": 2, "title": s2_title, "prob": s2_prob, "goals": s2_goals, "desc": s2_desc, "keys": s2_key},
        {"id": 3, "title": s3_title, "prob": s3_prob, "goals": s3_goals, "desc": s3_desc, "keys": s3_key},
    ]
    scenarios.sort(key=lambda x: x["prob"], reverse=True)
    return scenarios


def generate_narrative(scenarios, h_name, a_name, matchup, climate_impact, fatigue_h, fatigue_a, ensemble):
    """Narrativa detalhada de analista: como o jogo deve se desenvolver.
    Always produces at least 2 sentences even when ensemble is None."""
    # CORRECTION 9: Never return "Dados insuficientes" — use available data
    if not ensemble:
        # Build minimal narrative from scenarios and matchup
        h_style = (matchup or {}).get("h_style", "Equilibrado")
        a_style = (matchup or {}).get("a_style", "Equilibrado")
        sc1_desc = ""
        if scenarios:
            sc1 = scenarios[0]
            sc1_desc = f" O modelo projeta {sc1['title']} ({sc1['prob']*100:.0f}%) como cenário mais provável."
        clima_note = ""
        if climate_impact and climate_impact.get("total_penalty", 0) < -0.07:
            clima_note = f" As condições climáticas adversas (penalidade {climate_impact.get('total_penalty',0):+.2f}) podem influenciar o ritmo."
        fat_note = ""
        fat_h_val = fatigue_h or 0
        fat_a_val = fatigue_a or 0
        if fat_h_val > 60 or fat_a_val > 60:
            fat_note = f" Fadiga é fator relevante — {h_name[:14]}: {fat_h_val:.0f}/100, {a_name[:14]}: {fat_a_val:.0f}/100."
        base = (f"{h_name[:16]} apresenta estilo {h_style}, enquanto {a_name[:16]} joga em {a_style}."
                + sc1_desc + clima_note + fat_note)
        if not base.strip():
            base = (f"Partida entre {h_name[:16]} e {a_name[:16]} sem dados suficientes para análise completa. "
                    f"Acompanhe as condições do jogo em tempo real.")
        return base

    hw   = ensemble.get("home_win", 0.33)
    aw   = ensemble.get("away_win", 0.33)
    dr   = ensemble.get("draw", 0.33)
    o25  = ensemble.get("over25", 0.50)
    btts = ensemble.get("btts", 0.50)

    favorito  = h_name if hw > aw else a_name
    underdog  = a_name if hw > aw else h_name
    fav_prob  = max(hw, aw)
    diff      = abs(hw - aw)

    fat_h = fatigue_h or 30
    fat_a = fatigue_a or 30

    h_style  = (matchup or {}).get("h_style", "Equilibrado")
    a_style  = (matchup or {}).get("a_style", "Equilibrado")
    mat_sum  = (matchup or {}).get("summary", "")

    # Abertura
    if diff >= 0.20:
        abertura = (f"O {favorito[:16]} entra como favorito claro com {fav_prob*100:.0f}% de chance "
                    f"segundo os modelos combinados. {underdog[:14]} precisará ser eficiente nas poucas oportunidades.")
    elif diff >= 0.10:
        abertura = (f"Leve vantagem para {favorito[:14]} ({fav_prob*100:.0f}%), mas "
                    f"{underdog[:14]} é competitivo e pode surpreender.")
    else:
        abertura = (f"Partida extremamente equilibrada entre {h_name[:14]} e {a_name[:14]}, "
                    f"com modelos apontando probabilidades próximas para todos os resultados.")

    # Controle de jogo
    if h_style == "Posse de Bola":
        controle = f" {h_name[:14]} deve controlar a posse e ditar o ritmo."
    elif a_style == "Posse de Bola":
        controle = f" {a_name[:14]} tende a dominar a posse e pressionar alto."
    elif h_style == "Pressão Alta":
        controle = f" {h_name[:14]} vai pressionar alto desde o início, tentando forçar erros adversários."
    elif a_style == "Transição Rápida":
        controle = f" {a_name[:14]} pode ceder a bola e explorar transições rápidas."
    else:
        controle = " Equilíbrio de posse esperado, com disputa intensa no meio-campo."

    # Gols e mercados
    if o25 >= 0.65:
        gols = (f" Esperamos um jogo aberto com mais de 2.5 gols ({o25*100:.0f}% de probabilidade). "
                f"{'Ambas as equipes devem balançar as redes.' if btts > 0.55 else 'Mandante é o mais provável a marcar primeiro.'}")
    elif o25 <= 0.38:
        gols = (f" Partida deve ser tática e fechada — Under 2.5 gols é favorito ({(1-o25)*100:.0f}%). "
                f"Um único gol pode decidir.")
    else:
        gols = (f" Jogo equilibrado em termos de gols; Over 2.5 a {o25*100:.0f}% e BTTS a {btts*100:.0f}%.")

    # Fadiga
    if fat_h >= 65 and fat_h > fat_a + 20:
        fadiga = f" {h_name[:14]} chega com fadiga elevada ({fat_h:.0f}/100) — pode perder intensidade após o intervalo."
    elif fat_a >= 65 and fat_a > fat_h + 20:
        fadiga = f" {a_name[:14]} apresenta alta fadiga ({fat_a:.0f}/100), favorecendo o mandante no segundo tempo."
    elif fat_h >= 50 and fat_a >= 50:
        fadiga = " Ambas as equipes chegam com carga de jogos elevada — o desgaste físico pode ser fator decisivo."
    else:
        fadiga = ""

    # Clima
    clima = ""
    if climate_impact:
        if climate_impact.get("wind_penalty", 0) < -0.06:
            clima = f" O vento forte ({climate_impact.get('wind_kmph',0):.0f}km/h) dificultará bolas longas e escanteios."
        elif climate_impact.get("rain_penalty", 0) < -0.05:
            clima = " A chuva torna o gramado lento — passes curtos e dribles serão prejudicados."
        elif climate_impact.get("heat_penalty", 0) < -0.06:
            clima = f" Calor intenso ({climate_impact.get('temp_c',30):.0f}°C) afetará o ritmo no segundo tempo."

    # Cenário principal
    if scenarios:
        sc_main = scenarios[0]
        cenario = f" O cenário mais provável ({sc_main['prob']*100:.0f}%): {sc_main['title']} — {sc_main['goals']}."
    else:
        cenario = ""

    # Segundo tempo
    if fat_h > fat_a + 15:
        segundo_tempo = f" No segundo tempo, {a_name[:14]} tende a ganhar espaço à medida que {h_name[:14]} cansa."
    elif fat_a > fat_h + 15:
        segundo_tempo = f" No segundo tempo, {h_name[:14]} deve dominar à medida que {a_name[:14]} perde intensidade."
    elif o25 > 0.60:
        segundo_tempo = " O segundo tempo tende a ser mais aberto — time perdendo vai arriscar mais."
    else:
        segundo_tempo = ""

    narrative = abertura + controle + gols + fadiga + clima + cenario + segundo_tempo
    return narrative


def calculate_advanced_climate_impact(weather):
    """Calcula coeficientes de impacto climático com conversão segura de tipos."""
    if not weather:
        return None

    def _f(val, default=0):
        try:
            s = str(val).strip()
            neg = s.startswith("-")
            s = s.lstrip("-")
            v = float(s)
            return -v if neg else v
        except Exception:
            return float(default)

    temp_c    = _f(weather.get("temp_c",   20), 20)
    humidity  = _f(weather.get("humidity", 60), 60)
    wind_kmph = _f(weather.get("wind_kmph", 10), 10)
    precip_mm = _f(weather.get("precip_mm",  0),  0)
    uv        = _f(weather.get("uv",          3),  3)

    heat_penalty = (
        -0.12 if temp_c >= 32 else
        -0.07 if temp_c >= 28 else
        -0.05 if temp_c <= 5  else 0.0
    )
    humidity_penalty = (
        -0.05 if humidity >= 85 else
        -0.02 if humidity >= 75 else 0.0
    )
    wind_penalty = corner_boost = 0.0
    if wind_kmph >= 50:    wind_penalty = -0.15; corner_boost = 0.12
    elif wind_kmph >= 35:  wind_penalty = -0.08; corner_boost = 0.07
    elif wind_kmph >= 25:  wind_penalty = -0.04; corner_boost = 0.03

    rain_penalty = (
        -0.10 if precip_mm >= 10 else
        -0.05 if precip_mm >= 3  else
        -0.02 if precip_mm >= 1  else 0.0
    )

    total_penalty = heat_penalty + humidity_penalty + wind_penalty + rain_penalty

    return {
        "xg_coeff":      round(1.0 + heat_penalty + humidity_penalty + rain_penalty + wind_penalty*0.5, 3),
        "rhythm_coeff":  round(1.0 + heat_penalty*1.2 + rain_penalty*0.8, 3),
        "shots_coeff":   round(1.0 + wind_penalty*0.6 + rain_penalty*0.4, 3),
        "pressure_coeff":round(1.0 + heat_penalty*0.8 + humidity_penalty*0.5, 3),
        "corner_coeff":  round(1.0 + corner_boost + rain_penalty*(-0.1), 3),
        "heat_penalty":    round(heat_penalty, 3),
        "humidity_penalty":round(humidity_penalty, 3),
        "wind_penalty":    round(wind_penalty, 3),
        "rain_penalty":    round(rain_penalty, 3),
        "total_penalty":   round(total_penalty, 3),
        "temp_c": temp_c, "wind_kmph": wind_kmph, "precip_mm": precip_mm,
        "impact_label": (
            "ALTO IMPACTO"     if total_penalty <= -0.15 else
            "IMPACTO MODERADO" if total_penalty <= -0.07 else
            "BAIXO IMPACTO"    if total_penalty <= -0.02 else
            "SEM IMPACTO"
        ),
    }


def calculate_fatigue_index(hist, match_datetime_str=None):
    """Índice de fadiga 0-100 baseado em descanso e carga de jogos."""
    if not hist:
        return None  # sem dados = não exibir

    import datetime as _dt
    try:
        match_date = _dt.datetime.fromisoformat(match_datetime_str[:19]) if match_datetime_str else _dt.datetime.now()
    except Exception:
        match_date = _dt.datetime.now()

    dates = []
    for f in hist[:7]:
        try:
            d = _dt.datetime.fromisoformat(f["fixture"]["date"][:19])
            dates.append(d)
        except Exception:
            pass

    if not dates:
        return None

    dates.sort(reverse=True)
    rest_days = (match_date - dates[0]).days
    games_7   = sum(1 for d in dates if (match_date - d).days <= 7)
    games_14  = sum(1 for d in dates if (match_date - d).days <= 14)

    rest_score  = max(0, min(40, (7 - max(rest_days, 0)) * 6))
    load_score  = min(30, games_7 * 10 + games_14 * 3)
    travel_score= 8 if games_7 >= 2 else 0

    return round(min(100, rest_score + load_score + travel_score), 1)


def calculate_sos(hist, team_id):
    """
    Strength of Schedule real: calcula ELO de cada adversário nos últimos jogos.
    Usa calculate_team_elo() com n_fixtures=5 para eficiência.
    """
    if not hist:
        return {"sos_score": None, "label": "DADOS INSUFICIENTES", "avg_opp_elo": None, "games": 0, "opp_elos": []}

    opp_ids = []
    for f in hist[:6]:
        hid = int(f["teams"]["home"]["id"])
        aid = int(f["teams"]["away"]["id"])
        opp = aid if hid == int(team_id) else hid
        if opp not in opp_ids:
            opp_ids.append(opp)

    if not opp_ids:
        return {"sos_score": None, "label": "DADOS INSUFICIENTES", "avg_opp_elo": None, "games": 0, "opp_elos": []}

    opp_elos = []
    for oid in opp_ids[:5]:
        try:
            elo_data = calculate_team_elo(oid, n_fixtures=5)
            opp_elos.append(elo_data["elo"])
        except Exception:
            pass

    if not opp_elos:
        return {"sos_score": None, "label": "DADOS INSUFICIENTES", "avg_opp_elo": None, "games": 0, "opp_elos": []}

    avg_elo = sum(opp_elos) / len(opp_elos)

    if avg_elo >= 1700:   label = "Calendário Extremamente Difícil"; sos_score = 90
    elif avg_elo >= 1620: label = "Calendário Muito Difícil";        sos_score = 75
    elif avg_elo >= 1540: label = "Calendário Difícil";              sos_score = 60
    elif avg_elo >= 1460: label = "Calendário Moderado";             sos_score = 45
    elif avg_elo >= 1380: label = "Calendário Fácil";                sos_score = 30
    else:                  label = "Calendário Muito Fácil";         sos_score = 15

    return {
        "sos_score":   sos_score,
        "label":       label,
        "avg_opp_elo": round(avg_elo, 0),
        "games":       len(opp_elos),
        "opp_elos":    opp_elos,
    }


def calculate_ppda(detailed_data, team_id=None):
    """
    PPDA real = passes_opp / (tackles + interceptions + fouls_def)
    Usa dados de /fixtures/statistics obtidos por _fetch_detailed_game_data.
    """
    if not detailed_data:
        return {"ppda": None, "label": "DADOS INSUFICIENTES", "games": 0, "interpretation": ""}

    ppda_vals = []
    for d in detailed_data:
        ts  = d.get("stats", {})
        ops = d.get("opp_stats", {})
        if not ts or not ops:
            continue

        opp_passes  = _stat(ops, "total passes", "passes", default=0)
        tackles     = _stat(ts,  "tackles", default=0)
        intercepts  = _stat(ts,  "interceptions", default=0)
        fouls       = _stat(ts,  "fouls", default=0)
        def_actions = tackles + intercepts + fouls

        if opp_passes > 5 and def_actions > 0:
            ppda_vals.append(opp_passes / def_actions)

    if not ppda_vals:
        return {"ppda": None, "label": "DADOS INSUFICIENTES", "games": 0, "interpretation": ""}

    avg_ppda = sum(ppda_vals) / len(ppda_vals)

    if avg_ppda <= 6:
        label = "Pressing Extremo";      interpretation = "Pressão absolutamente dominante — sufoca construções adversárias."
    elif avg_ppda <= 9:
        label = "Pressing Muito Alto";   interpretation = "Equipe dificulta construções curtas com pressing constante."
    elif avg_ppda <= 12:
        label = "Pressing Alto";         interpretation = "Pressing acima da média — boa organização defensiva."
    elif avg_ppda <= 15:
        label = "Pressing Médio";        interpretation = "Equilíbrio entre pressing e bloco."
    elif avg_ppda <= 18:
        label = "Pressing Baixo";        interpretation = "Equipe cede espaço ao adversário — recua para defender."
    else:
        label = "Bloco Recuado";         interpretation = "Defesa passiva — permite construção adversária."

    return {"ppda": round(avg_ppda, 2), "label": label, "games": len(ppda_vals), "interpretation": interpretation}


def calculate_field_tilt(detailed_data_h, detailed_data_a):
    """
    Field Tilt baseado em posse real (dos stats por jogo) e ataques perigosos.
    Retorna percentuais reais baseados em dados históricos.
    """
    if not detailed_data_h and not detailed_data_a:
        return {"home_tilt": None, "away_tilt": None, "label": "DADOS INSUFICIENTES"}

    def _avg_stat(detail_list, *keys):
        vals = []
        for d in (detail_list or []):
            v = _stat(d.get("stats", {}), *keys, default=None)
            if v is not None and v > 0:
                vals.append(v)
        return sum(vals) / len(vals) if vals else None

    h_poss = _avg_stat(detailed_data_h, "ball possession", "possession")
    a_poss = _avg_stat(detailed_data_a, "ball possession", "possession")

    # Se temos posse real, Field Tilt = posse média
    if h_poss is not None and a_poss is not None:
        # Normalize: o visitante pode ter jogado contra outros times
        # Field Tilt real = posse ofensiva do mandante em partidas próprias
        home_tilt = round(h_poss, 1)
        away_tilt = round(100.0 - home_tilt, 1)
    elif h_poss is not None:
        home_tilt = round(h_poss, 1)
        away_tilt = round(100.0 - home_tilt, 1)
    elif a_poss is not None:
        away_tilt = round(a_poss, 1)
        home_tilt = round(100.0 - away_tilt, 1)
    else:
        return {"home_tilt": None, "away_tilt": None, "label": "DADOS INSUFICIENTES"}

    if home_tilt >= 65:    label = "Domínio Territorial Mandante Forte"
    elif home_tilt >= 58:  label = "Domínio Territorial Mandante"
    elif home_tilt >= 52:  label = "Leve Domínio Mandante"
    elif home_tilt <= 35:  label = "Domínio Territorial Visitante Forte"
    elif home_tilt <= 42:  label = "Domínio Territorial Visitante"
    elif home_tilt <= 48:  label = "Leve Domínio Visitante"
    else:                  label = "Equilíbrio Territorial"

    return {"home_tilt": home_tilt, "away_tilt": away_tilt, "label": label}


def calculate_enhanced_xthreat(blended_h, blended_a):
    """xThreat criado vs concedido — índice 0-100 normalizado por jogo."""
    def _xt(blended):
        if not blended:
            return {"created": None, "conceded": None, "net": None, "label": "DADOS INSUFICIENTES"}
        sot      = blended.get("avg_sot", 0) or 0
        shots    = blended.get("avg_shots", 0) or 0
        corners  = blended.get("avg_corners", 0) or 0
        gf       = blended.get("avg_gf", 0) or 0
        gc       = blended.get("avg_gc", 0) or 0
        dangerous= blended.get("avg_dangerous_attacks", 0) or 0

        if shots == 0 and sot == 0:
            return {"created": None, "conceded": None, "net": None, "label": "DADOS INSUFICIENTES"}

        created  = min(100, sot * 5 + shots * 1.5 + corners * 1.5 + gf * 8 + dangerous * 0.3)
        conceded = min(100, gc * 10 + max(0, 12 - sot) * 1.5)
        net = created - conceded

        if net >= 20:    label = "Ameaça Dominante"
        elif net >= 8:   label = "Ligeira Vantagem"
        elif net >= -8:  label = "Equilibrado"
        elif net >= -20: label = "Ligeiro Risco"
        else:            label = "Sob Pressão"

        return {"created": round(created, 1), "conceded": round(conceded, 1), "net": round(net, 1), "label": label}

    return {"home": _xt(blended_h), "away": _xt(blended_a)}


def calculate_progressive_actions(blended):
    """Estima ações progressivas por jogo."""
    if not blended:
        return None
    possession = blended.get("avg_possession", 0) or 0
    attacks    = blended.get("avg_attacks", 0) or 0
    dangerous  = blended.get("avg_dangerous_attacks", 0) or 0
    corners    = blended.get("avg_corners", 0) or 0
    shots      = blended.get("avg_shots", 0) or 0

    if possession == 0 and attacks == 0:
        return None

    prog_passes      = round(possession * 0.8 + attacks * 0.15, 1)
    prog_carries     = round(attacks * 0.12 + dangerous * 0.25, 1)
    deep_completions = round(shots * 0.6 + corners * 0.4, 1)
    total            = prog_passes + prog_carries + deep_completions

    label = ("Alta Progressividade" if total >= 80 else
             "Progressividade Moderada" if total >= 55 else
             "Baixa Progressividade")

    return {"prog_passes": prog_passes, "prog_carries": prog_carries,
            "deep_completions": deep_completions, "total": round(total, 1), "label": label}


def calculate_pressure_zones(blended):
    """Estima distribuição de pressão por zona."""
    if not blended:
        return None
    possession = blended.get("avg_possession", 0) or 0
    dangerous  = blended.get("avg_dangerous_attacks", 0) or 0
    attacks    = blended.get("avg_attacks", 0) or 0
    fouls_pg   = blended.get("avg_fouls", 0) or 0

    if possession == 0 and attacks == 0:
        return None

    high_press = round(possession * 0.25 + dangerous * 0.3 + fouls_pg * 0.15, 1)
    mid_press  = round(attacks * 0.15 + fouls_pg * 0.25, 1)
    low_press  = max(0, round(45 - possession * 0.25 + fouls_pg * 0.1, 1))
    total      = high_press + mid_press + low_press
    high_pct   = high_press / total * 100 if total > 0 else 33.3

    label = ("Pressing Alto Predominante" if high_pct >= 45 else
             "Pressão Mista"              if high_pct >= 33 else
             "Bloco Recuado")

    return {"high_press": high_press, "mid_press": mid_press, "low_press": low_press,
            "high_pct": round(high_pct, 1), "label": label}


def calculate_goals_by_period(detailed_data, team_id):
    """
    Distribuição real de gols por período de 15 minutos.
    Usa eventos de /fixtures/events obtidos por _fetch_detailed_game_data.
    """
    if not detailed_data:
        return None

    periods = ["0-15", "16-30", "31-45", "46-60", "61-75", "76-90"]
    scored  = {p: 0 for p in periods}
    conced  = {p: 0 for p in periods}
    games_with_events = 0

    for d in detailed_data:
        events = d.get("events", [])
        if not events:
            continue
        games_with_events += 1
        for ev in events:
            if ev.get("type") != "Goal":
                continue
            minute = (ev.get("time") or {}).get("elapsed") or 0
            scorer_team = int((ev.get("team") or {}).get("id") or -1)
            is_own = "own" in (ev.get("detail") or "").lower()
            team_scored = (scorer_team == int(team_id)) != is_own

            p = ("0-15"  if minute <= 15 else
                 "16-30" if minute <= 30 else
                 "31-45" if minute <= 45 else
                 "46-60" if minute <= 60 else
                 "61-75" if minute <= 75 else "76-90")

            if team_scored: scored[p] += 1
            else:           conced[p] += 1

    if games_with_events == 0:
        return None  # sem dados — não exibir valores zerados

    g = games_with_events
    total_scored = sum(scored.values())
    total_conced = sum(conced.values())

    return {
        "periods":        periods,
        "scored":         {p: round(scored[p] / g, 2) for p in periods},
        "conceded":       {p: round(conced[p] / g, 2) for p in periods},
        "scored_pct":     {p: round(scored[p] / max(total_scored, 1) * 100, 1) for p in periods},
        "conceded_pct":   {p: round(conced[p] / max(total_conced, 1) * 100, 1) for p in periods},
        "games":          g,
        "peak_scored":    max(periods, key=lambda p: scored[p]) if total_scored > 0 else "N/A",
        "peak_conceded":  max(periods, key=lambda p: conced[p]) if total_conced > 0 else "N/A",
        "total_scored":   total_scored,
        "total_conceded": total_conced,
    }


def calculate_corners_by_period(detailed_data, team_id):
    """
    A API não fornece timing de escanteios via events.
    Retorna None para não exibir dados falsos.
    Registramos total de escanteios para referência.
    """
    if not detailed_data:
        return None
    total_corners = []
    for d in detailed_data:
        v = _stat(d.get("stats", {}), "corner kicks", "corners", default=None)
        if v is not None:
            total_corners.append(v)
    if not total_corners:
        return None
    avg = sum(total_corners) / len(total_corners)
    return {
        "avg_corners_per_game": round(avg, 2),
        "games": len(total_corners),
        "note": "Distribuição temporal não disponível via API",
        "periods": None,
    }


def calculate_cards_by_period(detailed_data, team_id):
    """
    Distribuição real de cartões por período usando /fixtures/events.
    """
    if not detailed_data:
        return None

    periods = ["0-15", "16-30", "31-45", "46-60", "61-75", "76-90"]
    yellows = {p: 0 for p in periods}
    reds    = {p: 0 for p in periods}
    games_with_events = 0

    for d in detailed_data:
        events = d.get("events", [])
        if not events:
            continue
        games_with_events += 1
        for ev in events:
            if ev.get("type") != "Card":
                continue
            ev_team = int((ev.get("team") or {}).get("id") or -1)
            if ev_team != int(team_id):
                continue
            minute = (ev.get("time") or {}).get("elapsed") or 0
            detail = (ev.get("detail") or "").lower()

            p = ("0-15"  if minute <= 15 else
                 "16-30" if minute <= 30 else
                 "31-45" if minute <= 45 else
                 "46-60" if minute <= 60 else
                 "61-75" if minute <= 75 else "76-90")

            if "yellow" in detail: yellows[p] += 1
            elif "red" in detail:  reds[p]    += 1

    if games_with_events == 0:
        return None

    g             = games_with_events
    total_yellows = sum(yellows.values())

    return {
        "periods":      periods,
        "yellows":      {p: round(yellows[p] / g, 2) for p in periods},
        "reds":         {p: round(reds[p] / g, 2)    for p in periods},
        "yellows_pct":  {p: round(yellows[p] / max(total_yellows, 1) * 100, 1) for p in periods},
        "games":        g,
        "peak_yellow":  max(periods, key=lambda p: yellows[p]) if total_yellows > 0 else "N/A",
        "total_yellows":total_yellows,
    }


def calculate_dominance_score(h_elo, a_elo, h_pi, a_pi, ensemble, ppda_h, ppda_a,
                               field_tilt, xthreat, climate_impact, fatigue_h, fatigue_a):
    """Expected Dominance Score 0-100 composto de múltiplos módulos."""
    score = 50.0
    components = {}

    # ELO (20%)
    elo_h = h_elo.get("elo", 1500) if h_elo else 1500
    elo_a = a_elo.get("elo", 1500) if a_elo else 1500
    elo_contrib = (elo_h - elo_a) / 200.0 * 10
    score += elo_contrib
    components["ELO"] = round(elo_contrib, 2)

    # Ensemble xG (15%)
    if ensemble:
        hw, aw = ensemble.get("home_win", 0.33), ensemble.get("away_win", 0.33)
        xg_contrib = (hw - aw) * 20
        score += xg_contrib
        components["xG/Ensemble"] = round(xg_contrib, 2)

    # Pressure Index (15%)
    if h_pi and a_pi:
        pi_contrib = (h_pi.get("index", 50) - a_pi.get("index", 50)) / 100.0 * 12
        score += pi_contrib
        components["Pressure"] = round(pi_contrib, 2)

    # PPDA (10%)
    if ppda_h and ppda_h.get("ppda") is not None and ppda_a and ppda_a.get("ppda") is not None:
        ppda_contrib = (ppda_a["ppda"] - ppda_h["ppda"]) / 10.0 * 5
        score += ppda_contrib
        components["PPDA"] = round(ppda_contrib, 2)

    # Field Tilt (15%)
    if field_tilt and field_tilt.get("home_tilt") is not None:
        tilt_contrib = (field_tilt["home_tilt"] - 50) / 50.0 * 10
        score += tilt_contrib
        components["Field Tilt"] = round(tilt_contrib, 2)

    # xThreat (10%)
    if xthreat:
        xt_h = xthreat.get("home", {}).get("net")
        xt_a = xthreat.get("away", {}).get("net")
        if xt_h is not None and xt_a is not None:
            xt_contrib = (xt_h - xt_a) / 30.0 * 5
            score += xt_contrib
            components["xThreat"] = round(xt_contrib, 2)

    # Climate (5%)
    if climate_impact:
        cl_contrib = climate_impact.get("total_penalty", 0) * 5
        score += cl_contrib
        components["Clima"] = round(cl_contrib, 2)

    # Fatigue (10%)
    if fatigue_h is not None and fatigue_a is not None:
        fat_contrib = (fatigue_a - fatigue_h) / 100.0 * 8
        score += fat_contrib
        components["Fadiga"] = round(fat_contrib, 2)

    score = max(0, min(100, score))
    label = (
        "Dominância Mandante Forte" if score >= 68 else
        "Dominância Mandante"       if score >= 58 else
        "Leve Vantagem Mandante"    if score >= 53 else
        "Equilíbrio"                if score >= 47 else
        "Leve Vantagem Visitante"   if score >= 42 else
        "Dominância Visitante"      if score >= 32 else
        "Dominância Visitante Forte"
    )

    return {"score": round(score, 1), "label": label, "components": components}


def calculate_prediction_confidence_index(h_hist, a_hist, ensemble, conf,
                                           xthreat, dominance_score, sos_h, sos_a):
    """Índice de Confiança real: qty dados + convergência modelos + SOS + xThreat."""
    score = 0
    notes = []

    # 1. Quantidade de dados
    h_n = len(h_hist) if h_hist else 0
    a_n = len(a_hist) if a_hist else 0
    data_qty = (h_n + a_n) / 2
    if data_qty >= 8:   score += 25; notes.append(f"Base de dados: Excelente ({data_qty:.0f} jogos/time)")
    elif data_qty >= 5: score += 15; notes.append(f"Base de dados: Boa ({data_qty:.0f} jogos/time)")
    else:               score +=  5; notes.append(f"Base de dados: Insuficiente ({data_qty:.0f} jogos/time)")

    # 2. Confiança base ensemble
    base_conf = conf.get("score", 50) if conf else 50
    score += base_conf * 0.25
    notes.append(f"Confiança ensemble: {base_conf:.0f}/100")

    # 3. Divergência modelos
    if ensemble:
        n_sources = len(ensemble.get("sources_used", []))
        if n_sources >= 4:   score += 20; notes.append("Convergência multi-modelo: Alta (4+ fontes)")
        elif n_sources >= 2: score += 12; notes.append("Convergência multi-modelo: Moderada")
        else:                score +=  5; notes.append("Convergência multi-modelo: Baixa")

        # Checar divergência entre hw de cada modelo
        hw = ensemble.get("home_win", 0.33)
        if hw > 0.70 or hw < 0.10:
            score -= 10
            notes.append(f"⚠️  Probabilidade extrema ({hw*100:.0f}%) — possível distorção de modelo")

    # 4. xThreat sinal
    if xthreat:
        xt_h = xthreat.get("home", {}).get("net")
        xt_a = xthreat.get("away", {}).get("net")
        if xt_h is not None:
            h_net = abs(xt_h)
            if h_net >= 15:   score += 10; notes.append("xThreat: Sinal claro e consistente")
            elif h_net >= 5:  score +=  5; notes.append("xThreat: Sinal moderado")

    # 5. SOS: calendário fácil pode inflar form
    sos_h_s = sos_h.get("sos_score") if sos_h else None
    sos_a_s = sos_a.get("sos_score") if sos_a else None
    if sos_h_s is not None and sos_a_s is not None:
        sos_avg = (sos_h_s + sos_a_s) / 2
        if sos_avg >= 65:
            score -= 5
            notes.append("Calendário difícil — forma pode ser levemente inflada")
        elif sos_avg <= 30:
            score += 3
            notes.append("Calendário fácil — forma pode ser superestimada")

    score = max(0, min(100, score))
    label = (
        "Confiança Muito Alta" if score >= 75 else
        "Confiança Alta"       if score >= 60 else
        "Confiança Moderada"   if score >= 45 else
        "Confiança Baixa"      if score >= 30 else
        "Confiança Muito Baixa"
    )

    return {"score": round(score, 1), "label": label, "notes": notes}


def calculate_player_impact(h_players, a_players, lineups, h_name, a_name):
    """
    Analisa impacto de jogadores-chave: participação em gols, xG individual.
    Estima impacto de ausências baseado na proporção de gols/assistências.
    """
    if not h_players and not a_players:
        return None

    result = {"home": [], "away": [], "absences": []}

    for plist, tname, side in [(h_players or [], h_name, "home"), (a_players or [], a_name, "away")]:
        total_goals = sum(p.get("goals", 0) for p in plist) or 1
        total_assists = sum(p.get("assists", 0) for p in plist) or 1
        team_apps = max(sum(p.get("apps", 1) for p in plist) / max(len(plist), 1), 1)

        for p in plist[:5]:
            g = p.get("goals", 0) or 0
            a = p.get("assists", 0) or 0
            apps = p.get("apps", 1) or 1
            rating = float(str(p.get("rating") or "0") or "0")

            # Participação em gols (goals + assists) / total team contribution
            participation = (g + a) / max(total_goals + total_assists, 1) * 100
            # xG individual estimado
            xg_ind = round(g / apps * 0.85 + a / apps * 0.25, 3)
            # Impacto se ausente
            impact_pct = round(participation * 0.65, 1)  # 65% da participação é perda direta

            player_data = {
                "name": p["name"],
                "position": p.get("position", "?"),
                "goals": g, "assists": a, "apps": apps,
                "rating": rating,
                "xg_ind": xg_ind,
                "participation_pct": round(participation, 1),
                "absence_impact_pct": impact_pct,
            }
            result[side].append(player_data)

        # Verificar ausências nas escalações
        if lineups:
            import unicodedata as _ud

            def _norm(s):
                """Normaliza nome: minúsculas, sem acentos, sem espaços extras."""
                s = str(s or "").strip().lower()
                s = _ud.normalize("NFD", s)
                s = "".join(c for c in s if _ud.category(c) != "Mn")
                return s

            def _name_match(starter_name, player_name):
                """
                Verifica se player_name bate com starter_name.
                Aceita: match exato, sobrenome contido, ou qualquer token de 4+ chars presente.
                """
                sn = _norm(starter_name)
                pn = _norm(player_name)
                if pn == sn:
                    return True
                # Tokens do player (4+ chars) presentes no nome do starter
                tokens = [t for t in pn.split() if len(t) >= 4]
                if tokens and all(t in sn for t in tokens):
                    return True
                # Tokens do starter presentes no nome do player
                tokens_s = [t for t in sn.split() if len(t) >= 4]
                if tokens_s and all(t in pn for t in tokens_s):
                    return True
                return False

            # Construir starting XI do time correto
            starters_names = []
            for tl in lineups:
                t_name = _norm(tl.get("team", {}).get("name", ""))
                t_ref  = _norm(tname)
                # Match por pelo menos 5 chars comuns no nome do time
                common = sum(1 for tok in t_ref.split() if len(tok) >= 4 and tok in t_name)
                if common >= 1 or t_ref[:8] in t_name:
                    for sp in tl.get("startXI", []):
                        sname = sp.get("player", {}).get("name", "")
                        if sname:
                            starters_names.append(sname)

            if starters_names:
                for p in plist[:3]:
                    pname = p["name"]
                    # Só marcar ausente se NENHUM starter faz match
                    in_xi = any(_name_match(sn, pname) for sn in starters_names)
                    if not in_xi:
                        g    = p.get("goals", 0) or 0
                        a_g  = p.get("assists", 0) or 0
                        apps = p.get("apps", 1) or 1
                        # Impact real: (G + A*0.6) / apps → perda xG + xA
                        xg_loss = round((g / apps) * 0.75 + (a_g / apps) * 0.25, 2)
                        # Redução vitória estimada
                        part_team = (g + a_g) / max(total_goals + total_assists, 1)
                        victory_reduction = round(part_team * 0.35 * 100, 1)
                        result["absences"].append({
                            "player": pname,
                            "team": tname,
                            "xg_loss": xg_loss,
                            "victory_reduction_pct": victory_reduction,
                            "note": (f"Ausente do XI — perda est.: -{xg_loss:.2f} xG+xA/j"
                                     f"  |  Impacto vitória: -{victory_reduction:.1f}%"),
                        })

    return result if (result["home"] or result["away"]) else None


def generate_explainability(ensemble, h_elo, a_elo, h_pi, a_pi, field_tilt,
                             xthreat, climate_impact, fatigue_h, fatigue_a,
                             h_name, a_name):
    """
    Motor de Explicabilidade: decompõe contribuição de cada módulo
    para cada resultado (Casa, Empate, Fora).
    """
    if not ensemble:
        return None

    hw_base  = ensemble.get("home_win",  0.333)
    dr_base  = ensemble.get("draw",      0.333)
    aw_base  = ensemble.get("away_win",  0.333)

    contribs = {}

    # ELO
    elo_h = h_elo.get("elo", 1500) if h_elo else 1500
    elo_a = a_elo.get("elo", 1500) if a_elo else 1500
    elo_diff_norm = (elo_h - elo_a) / 400.0  # -1 a +1
    contribs["ELO"] = {
        "home": round(elo_diff_norm * 7, 1),
        "draw": round(-abs(elo_diff_norm) * 2, 1),
        "away": round(-elo_diff_norm * 7, 1),
    }

    # Forma recente (via ensemble vs ELO puro)
    forma_delta_h = (hw_base - 0.33) * 100 * 0.3
    contribs["Forma"] = {
        "home": round(forma_delta_h, 1),
        "draw": 0.0,
        "away": round(-forma_delta_h, 1),
    }

    # Pressure Index
    if h_pi and a_pi:
        pi_diff = (h_pi.get("index", 50) - a_pi.get("index", 50)) / 100.0
        contribs["Pressão"] = {
            "home": round(pi_diff * 5, 1),
            "draw": 0.0,
            "away": round(-pi_diff * 5, 1),
        }

    # xThreat
    if xthreat:
        xt_h = xthreat.get("home", {}).get("net")
        xt_a = xthreat.get("away", {}).get("net")
        if xt_h is not None and xt_a is not None:
            xt_diff = (xt_h - xt_a) / 50.0
            contribs["xThreat"] = {
                "home": round(xt_diff * 5, 1),
                "draw": 0.0,
                "away": round(-xt_diff * 5, 1),
            }

    # Field Tilt
    if field_tilt and field_tilt.get("home_tilt") is not None:
        tilt_diff = (field_tilt["home_tilt"] - 50) / 50.0
        contribs["Field Tilt"] = {
            "home": round(tilt_diff * 4, 1),
            "draw": 0.0,
            "away": round(-tilt_diff * 4, 1),
        }

    # Clima
    if climate_impact:
        cl = climate_impact.get("total_penalty", 0)
        contribs["Clima"] = {
            "home": round(cl * 3, 1),
            "draw": round(abs(cl) * 1, 1),
            "away": round(cl * 3, 1),
        }

    # Fadiga
    if fatigue_h is not None and fatigue_a is not None:
        fat_diff = (fatigue_a - fatigue_h) / 100.0
        contribs["Fadiga"] = {
            "home": round(fat_diff * 5, 1),
            "draw": 0.0,
            "away": round(-fat_diff * 5, 1),
        }

    # Mando de campo
    contribs["Mando de Campo"] = {"home": 2.0, "draw": 0.5, "away": -1.5}

    return {
        "home_win_pct":  round(hw_base * 100, 1),
        "draw_pct":      round(dr_base * 100, 1),
        "away_win_pct":  round(aw_base * 100, 1),
        "contributions": contribs,
        "h_name": h_name,
        "a_name": a_name,
    }


def calculate_data_quality(h_hist, a_hist, h_blended, a_blended, weather, lineups,
                            detailed_h, detailed_a, ppda_h, ppda_a, field_tilt,
                            goals_period_h, goals_period_a):
    """Relatório de qualidade dos dados: cobertura 0-100 por categoria."""
    data_score = 0
    tactical_score = 0
    stats_score = 0
    coverage_notes = []

    # Dados históricos
    h_n = len(h_hist) if h_hist else 0
    a_n = len(a_hist) if a_hist else 0
    if h_n >= 8 and a_n >= 8:   data_score += 30; coverage_notes.append("✅ Histórico: 8+ jogos por time")
    elif h_n >= 5 and a_n >= 5: data_score += 18; coverage_notes.append("🟡 Histórico: 5-7 jogos por time")
    else:                        data_score +=  5; coverage_notes.append("🔴 Histórico: menos de 5 jogos")

    # Blended stats
    if h_blended and h_blended.get("avg_shots", 0) > 0:
        stats_score += 20; coverage_notes.append("✅ Estatísticas ofensivas: disponíveis")
    else:
        coverage_notes.append("🔴 Estatísticas ofensivas: indisponíveis")

    # Clima
    if weather:
        data_score += 10; coverage_notes.append("✅ Dados climáticos: disponíveis")
    else:
        coverage_notes.append("🟡 Dados climáticos: indisponíveis")

    # Escalações
    if lineups:
        tactical_score += 25; coverage_notes.append("✅ Escalações: divulgadas")
    else:
        coverage_notes.append("🟡 Escalações: não divulgadas")

    # PPDA real
    if ppda_h and ppda_h.get("ppda") is not None:
        tactical_score += 20; coverage_notes.append("✅ PPDA: calculado com dados reais")
    else:
        coverage_notes.append("🟡 PPDA: sem dados de desarmes/interceptações")

    # Field Tilt real
    if field_tilt and field_tilt.get("home_tilt") is not None:
        tactical_score += 20; coverage_notes.append("✅ Field Tilt: calculado com posse real")
    else:
        coverage_notes.append("🟡 Field Tilt: sem dados de posse por jogo")

    # Distribuições temporais
    if goals_period_h and goals_period_h.get("games", 0) > 0:
        stats_score += 25; coverage_notes.append("✅ Distribuição temporal: eventos reais disponíveis")
    else:
        coverage_notes.append("🔴 Distribuição temporal: sem eventos — API não retornou dados")

    # Detailed data (stats+events por jogo)
    if detailed_h and len(detailed_h) >= 4:
        stats_score += 20; coverage_notes.append(f"✅ Estatísticas por jogo: {len(detailed_h)} jogos mandante")
    elif detailed_h:
        stats_score += 10; coverage_notes.append(f"🟡 Estatísticas por jogo: apenas {len(detailed_h)} jogos")
    else:
        coverage_notes.append("🔴 Estatísticas por jogo: indisponível")

    # Placeholders detectados
    placeholders = 0
    if not ppda_h or ppda_h.get("ppda") is None:            placeholders += 1
    if not field_tilt or field_tilt.get("home_tilt") is None: placeholders += 1
    if not goals_period_h:                                    placeholders += 1

    data_score    = min(100, data_score)
    tactical_score= min(100, tactical_score)
    stats_score   = min(100, stats_score)
    reliability   = min(100, int((data_score + tactical_score + stats_score) / 3))

    return {
        "data_score":     data_score,
        "tactical_score": tactical_score,
        "stats_score":    stats_score,
        "reliability":    reliability,
        "placeholders":   placeholders,
        "notes":          coverage_notes,
    }


# =====================================================================
# FASE DE CALIBRAÇÃO PROFISSIONAL — ETAPAS 1-11
# =====================================================================

# ── ETAPA 1 — ELO CONTEXTUAL (opponent ELO from cache) ───────────────
# Patched directly in calculate_team_elo (see line 972 fix below).
# The functions below use _elo_cache populated by prior calls.

def get_opponent_elo_from_cache(opp_id):
    """Returns cached ELO for opponent, or 1500 if not yet computed."""
    key = str(opp_id)
    if key in _elo_cache:
        return _elo_cache[key]["elo"]
    return 1500.0


# ── ETAPA 2 — MODEL AUDITOR ───────────────────────────────────────────

def calculate_model_audit(poisson_probs, mc_probs, elo_probs, ml_probs, api_pred):
    """
    Compares all 5 models side-by-side.
    Returns std_dev, max_gap, and convergence classification per outcome.
    """
    import math as _math

    outcomes = ["home_win", "draw", "away_win"]

    # Normalise api_pred into same keys
    api_norm = {}
    if api_pred and isinstance(api_pred, dict):
        wp = api_pred.get("win_or_draw") or api_pred.get("predictions", {})
        if isinstance(wp, dict):
            api_norm = {
                "home_win": float(wp.get("home", wp.get("home_win", 0)) or 0) / 100.0,
                "draw":     float(wp.get("draw", 0) or 0) / 100.0,
                "away_win": float(wp.get("away", wp.get("away_win", 0)) or 0) / 100.0,
            }

    models = {
        "Poisson":  poisson_probs or {},
        "MonteCarlo": mc_probs or {},
        "ELO":      elo_probs or {},
        "ML":       ml_probs or {},
        "API":      api_norm,
    }

    audit = {}
    for oc in outcomes:
        vals = []
        row = {}
        for mname, mdata in models.items():
            v = mdata.get(oc, None) if mdata else None
            row[mname] = v
            if v is not None:
                vals.append(v)
        if len(vals) >= 2:
            mean = sum(vals) / len(vals)
            variance = sum((x - mean) ** 2 for x in vals) / len(vals)
            std = _math.sqrt(variance)
            gap = max(vals) - min(vals)
            if std < 0.03:
                conv = "CONVERGENTE"
            elif std < 0.07:
                conv = "MODERADO"
            else:
                conv = "DIVERGENTE"
        else:
            mean = vals[0] if vals else None
            std = 0.0
            gap = 0.0
            conv = "INSUFICIENTE"
        audit[oc] = {
            "models": row,
            "mean":   round(mean, 4) if mean is not None else None,
            "std":    round(std, 4),
            "gap":    round(gap, 4),
            "convergence": conv,
        }
    return audit


# ── ETAPA 3 — LAMBDA EXPLAINER ────────────────────────────────────────

def calculate_lambda_explainer(
        h_blended, a_blended,
        h_wxg, a_wxg, h_wxga, a_wxga,
        climate_impact=None,
        fatigue_h=None, fatigue_a=None,
        xg_lh=None, xg_la=None):
    """
    Full component breakdown of how each team's λ was derived.
    Returns two dicts (home, away) with step-by-step contributions.
    fatigue_h/a may be float (legacy) or dict with 'fatigue_index' key.
    """
    def _safe(v, default=0.0):
        return float(v) if v is not None else default

    def _fatigue_index(fat):
        """Extract fatigue index whether fat is float, int, or dict."""
        if fat is None:
            return 0.0
        if isinstance(fat, (int, float)):
            return float(fat)
        if isinstance(fat, dict):
            return float(fat.get("fatigue_index") or 0)
        return 0.0

    # Home lambda components
    h_base_off  = _safe(h_blended.get("avg_gf"), 1.2)
    a_base_def  = _safe(a_blended.get("avg_gc"), 1.1)
    h_xg_raw    = _safe(h_wxg, h_base_off)
    a_xga_raw   = _safe(a_wxga, a_base_def)
    h_lambda_xg = 0.55 * h_xg_raw + 0.45 * a_xga_raw

    # Away lambda components
    a_base_off  = _safe(a_blended.get("avg_gf"), 0.9)
    h_base_def  = _safe(h_blended.get("avg_gc"), 1.0)
    a_xg_raw    = _safe(a_wxg, a_base_off)
    h_xga_raw   = _safe(h_wxga, h_base_def)
    a_lambda_xg = 0.55 * a_xg_raw + 0.45 * h_xga_raw

    # Climate coefficient
    cli_coeff = 1.0
    cli_note  = "Sem dados climáticos"
    if climate_impact:
        cli_coeff = _safe(climate_impact.get("xg_coeff"), 1.0)
        cli_note  = climate_impact.get("summary", "Neutro")

    # Fatigue coefficient (fatigue may be float or dict)
    h_fat_coeff = max(0.85, 1.0 - _fatigue_index(fatigue_h) * 0.002)
    a_fat_coeff = max(0.85, 1.0 - _fatigue_index(fatigue_a) * 0.002)

    h_lambda_final = h_lambda_xg * cli_coeff * h_fat_coeff
    a_lambda_final = a_lambda_xg * cli_coeff * a_fat_coeff

    # Use orchestrator-computed lambdas if available (more accurate)
    if xg_lh is not None:
        h_lambda_final = _safe(xg_lh) * cli_coeff * h_fat_coeff
    if xg_la is not None:
        a_lambda_final = _safe(xg_la) * cli_coeff * a_fat_coeff

    def _build(
            base_off, base_def, xg_raw, xga_raw, lam_xg, fat_coeff, lam_final):
        return {
            "base_ofensiva":    round(base_off, 3),
            "base_defensiva_opp": round(base_def, 3),
            "xG_proprio":       round(xg_raw, 3),
            "xGA_adversario":   round(xga_raw, 3),
            "lambda_xg":        round(lam_xg, 3),
            "clima_coeff":      round(cli_coeff, 3),
            "clima_nota":       cli_note,
            "fadiga_coeff":     round(fat_coeff, 3),
            "lambda_final":     round(lam_final, 3),
        }

    return {
        "home": _build(h_base_off, a_base_def, h_xg_raw, a_xga_raw,
                       h_lambda_xg, h_fat_coeff, h_lambda_final),
        "away": _build(a_base_off, h_base_def, a_xg_raw, h_xga_raw,
                       a_lambda_xg, a_fat_coeff, a_lambda_final),
        "clima_coeff":  round(cli_coeff, 3),
        "h_lambda_adjusted": round(h_lambda_final, 3),
        "a_lambda_adjusted": round(a_lambda_final, 3),
    }


# ── ETAPA 4 — CLIMATE ENGINE (applies coefficients to lambdas) ────────
# Coefficients are already embedded in lambda_explainer above.
# Helper to apply climate + fatigue to raw lambdas before MC.

def apply_climate_fatigue_to_lambdas(lh, la, climate_impact=None,
                                      fatigue_h=None, fatigue_a=None):
    """Returns (adjusted_lh, adjusted_la) after climate + fatigue."""
    def _safe(v, d=1.0):
        try: return float(v) if v is not None else d
        except: return d

    cli = _safe(climate_impact.get("xg_coeff"), 1.0) if climate_impact else 1.0

    def _fi(fat):
        if fat is None: return 0.0
        if isinstance(fat, (int, float)): return float(fat)
        return float((fat or {}).get("fatigue_index") or 0)

    h_fat = max(0.85, 1.0 - _fi(fatigue_h) * 0.002)
    a_fat = max(0.85, 1.0 - _fi(fatigue_a) * 0.002)

    return round(lh * cli * h_fat, 4), round(la * cli * a_fat, 4)


# ── ETAPA 5 — PLACEHOLDER DETECTOR ───────────────────────────────────

def detect_placeholders(h_blended, a_blended,
                         ppda_h, ppda_a, field_tilt,
                         goals_period_h, goals_period_a,
                         sos_h, sos_a, weather, lineups,
                         ml_probs, detailed_h, detailed_a):
    """
    Formal placeholder detector. Returns list of detected placeholder issues
    and an overall placeholder_count.
    """
    issues = []

    def _chk(cond, msg):
        if cond:
            issues.append(msg)

    # PPDA
    _chk(not ppda_h or ppda_h.get("ppda") in (None, 0),
         "PPDA casa: sem dados reais (proxy ou ausente)")
    _chk(not ppda_a or ppda_a.get("ppda") in (None, 0),
         "PPDA fora: sem dados reais (proxy ou ausente)")

    # Field tilt
    _chk(not field_tilt or field_tilt.get("home_tilt") == 50.0,
         "Field Tilt: usando padrão 50/50 (dados reais ausentes)")

    # Distribuições temporais
    _chk(goals_period_h is None or goals_period_h.get("total_goals", 0) == 0,
         "Gols por período (casa): sem eventos reais")
    _chk(goals_period_a is None or goals_period_a.get("total_goals", 0) == 0,
         "Gols por período (fora): sem eventos reais")

    # SOS ELO
    _chk(not sos_h or sos_h.get("avg_opp_elo") is None,
         "SOS casa: ELO dos adversários não calculado")
    _chk(not sos_a or sos_a.get("avg_opp_elo") is None,
         "SOS fora: ELO dos adversários não calculado")

    # Clima
    _chk(not weather, "Clima: dados do wttr.in ausentes")

    # Escalações
    _chk(not lineups or len(lineups) < 2,
         "Escalações: não confirmadas para este jogo")

    # ML
    _chk(ml_probs is None, "ML: sem modelo treinado (retorna None)")

    # Detailed data
    _chk(not detailed_h, "Dados detalhados casa: nenhum jogo retornou stats/eventos")
    _chk(not detailed_a, "Dados detalhados fora: nenhum jogo retornou stats/eventos")

    return {
        "placeholder_count": len(issues),
        "issues": issues,
        "status": "✅ Limpo" if len(issues) == 0 else
                  ("⚠️  Parcial" if len(issues) <= 3 else "🔴 Crítico"),
    }


# ── ETAPA 6 — CONFIDENCE SCORE 2.0 ───────────────────────────────────

def calculate_confidence_v2(
        h_sample, a_sample,
        model_audit,
        placeholder_detector,
        data_quality,
        lineups, weather,
        detailed_h, detailed_a,
        h_hist, a_hist):
    """
    Enhanced Confidence Score with 8+ dimensions:
    1. Sample size (both teams)
    2. Model divergence (from audit)
    3. Placeholder count
    4. Tactical coverage (lineups)
    5. Climate data presence
    6. Event data presence
    7. Data reliability score
    8. Historical consistency (H2H recency)
    """
    score = 0.0
    notes = []

    # 1. Sample size (max 20 pts)
    min_sample = min(h_sample or 0, a_sample or 0)
    s_pts = min(20, min_sample * 1.5)
    score += s_pts
    if min_sample < 5:
        notes.append(f"Amostra baixa ({min_sample} jogos)")

    # 2. Model divergence (max 20 pts)
    if model_audit:
        divs = [v["std"] for v in model_audit.values() if v.get("std") is not None]
        avg_std = sum(divs) / len(divs) if divs else 0.15
        div_pts = max(0, 20 - avg_std * 200)
        score += div_pts
        if avg_std > 0.07:
            notes.append(f"Alta divergência entre modelos (σ={avg_std:.3f})")
    else:
        score += 10

    # 3. Placeholder penalty (max 15 pts)
    ph_count = (placeholder_detector or {}).get("placeholder_count", 5)
    ph_pts = max(0, 15 - ph_count * 2)
    score += ph_pts

    # 4. Tactical coverage — lineups (max 10 pts)
    if lineups and len(lineups) >= 2:
        score += 10
    elif lineups:
        score += 5
        notes.append("Escalação parcial")
    else:
        notes.append("Escalações não confirmadas")

    # 5. Climate data (max 5 pts)
    if weather:
        score += 5
    else:
        notes.append("Dados climáticos ausentes")

    # 6. Event data (max 10 pts)
    has_events = bool(detailed_h) and bool(detailed_a)
    if has_events:
        score += 10
    else:
        score += 3
        notes.append("Dados de eventos históricos limitados")

    # 7. Data reliability (max 15 pts)
    rel = (data_quality or {}).get("reliability", 50)
    score += rel * 0.15

    # 8. Historical consistency — does team have enough recent data? (max 5 pts)
    recency_h = len([f for f in (h_hist or [])[:5]])
    recency_a = len([f for f in (a_hist or [])[:5]])
    if recency_h >= 5 and recency_a >= 5:
        score += 5
    elif recency_h >= 3 and recency_a >= 3:
        score += 3

    score = min(100, round(score, 1))

    if score >= 80:
        label = "🟢 ALTA CONFIANÇA"
    elif score >= 60:
        label = "🟡 CONFIANÇA MODERADA"
    elif score >= 40:
        label = "🟠 CONFIANÇA BAIXA"
    else:
        label = "🔴 CONFIANÇA MUITO BAIXA"

    return {"score": score, "label": label, "notes": notes, "dimensions": {
        "amostra":      round(s_pts, 1),
        "divergencia":  round(score - s_pts, 1),
        "placeholders": ph_pts,
        "escalacoes":   10 if (lineups and len(lineups) >= 2) else (5 if lineups else 0),
        "clima":        5 if weather else 0,
        "eventos":      10 if has_events else 3,
        "confiabilidade": round(rel * 0.15, 1),
    }}


# ── ETAPA 7 — BACKTEST PROFISSIONAL (Brier Score + Log Loss) ─────────

def calculate_brier_score(predictions, outcomes):
    """
    Brier Score = mean((prob - outcome)^2) over all events.
    predictions: list of (prob_home, prob_draw, prob_away)
    outcomes:    list of actual outcomes ('H', 'D', 'A')
    """
    if not predictions or not outcomes or len(predictions) != len(outcomes):
        return None
    total = 0.0
    n = 0
    for (ph, pd, pa), oc in zip(predictions, outcomes):
        oh = 1.0 if oc == "H" else 0.0
        od = 1.0 if oc == "D" else 0.0
        oa = 1.0 if oc == "A" else 0.0
        total += (ph - oh) ** 2 + (pd - od) ** 2 + (pa - oa) ** 2
        n += 1
    return round(total / n, 4) if n > 0 else None


def calculate_log_loss(predictions, outcomes):
    """Log Loss for multi-class (H/D/A)."""
    import math as _m
    if not predictions or not outcomes or len(predictions) != len(outcomes):
        return None
    eps = 1e-15
    total = 0.0
    n = 0
    for (ph, pd, pa), oc in zip(predictions, outcomes):
        if oc == "H":
            p = max(eps, min(1 - eps, ph))
        elif oc == "D":
            p = max(eps, min(1 - eps, pd))
        else:
            p = max(eps, min(1 - eps, pa))
        total += _m.log(p)
        n += 1
    return round(-total / n, 4) if n > 0 else None


def calculate_calibration_curve(predictions, outcomes, n_bins=5):
    """
    Returns calibration bins: for each bin, mean predicted prob vs actual freq.
    Uses home_win prediction only for simplicity.
    """
    if not predictions or not outcomes:
        return []
    bins = [[] for _ in range(n_bins)]
    for (ph, _, _), oc in zip(predictions, outcomes):
        b = min(n_bins - 1, int(ph * n_bins))
        bins[b].append((ph, 1.0 if oc == "H" else 0.0))
    result = []
    for i, b in enumerate(bins):
        if not b:
            continue
        mean_pred = sum(x[0] for x in b) / len(b)
        mean_act  = sum(x[1] for x in b) / len(b)
        result.append({
            "bin":       i,
            "range":     f"{i/n_bins:.1f}–{(i+1)/n_bins:.1f}",
            "mean_pred": round(mean_pred, 3),
            "mean_act":  round(mean_act, 3),
            "n":         len(b),
            "gap":       round(abs(mean_pred - mean_act), 3),
        })
    return result


def calculate_global_confidence(ensemble_conf, data_quality, placeholder_detector,
                                 lineups, weather, h_hist, a_hist, consistency_audit):
    """
    CORRECTION 6 — Unified Confidence Engine.
    Produces ONE unified score 0-100 from all data sources.
    Returns dict: {global_score, components}
    """
    score = 0.0
    components = {}

    # Data volume (25 pts max)
    avg_games = ((len(h_hist) if h_hist else 0) + (len(a_hist) if a_hist else 0)) / 2.0
    vol_pts = min(25.0, avg_games * 2.5)
    score += vol_pts
    components["volume_dados"] = round(vol_pts, 1)

    # Data quality (20 pts)
    if data_quality:
        dq_score = data_quality.get("overall_score", data_quality.get("reliability", 50))
        dq_pts = dq_score * 0.20
        score += dq_pts
        components["qualidade_dados"] = round(dq_pts, 1)
    else:
        components["qualidade_dados"] = 0.0

    # Model consistency (20 pts) — from consistency_audit
    consistency_penalty = consistency_audit.get("impact_on_confidence", 0) if consistency_audit else 0
    cons_pts = max(0.0, 20.0 + consistency_penalty)
    score += cons_pts
    components["consistencia_modelos"] = round(cons_pts, 1)

    # Lineups confirmed (15 pts)
    _lineups_ok = bool(lineups and (
        (isinstance(lineups, list) and len(lineups) > 0) or
        (isinstance(lineups, dict) and (lineups.get("home") or lineups.get("away")))
    ))
    if _lineups_ok:
        score += 15.0
        components["escalacoes"] = 15.0
    else:
        components["escalacoes"] = 0.0

    # Climate data (10 pts)
    if weather:
        score += 10.0
        components["clima"] = 10.0
    else:
        components["clima"] = 0.0

    # Placeholders (10 pts)
    if placeholder_detector:
        ph_count = placeholder_detector.get("placeholder_count", 5)
        ph_pts = max(0.0, 10.0 - ph_count * 2.0)
        score += ph_pts
        components["placeholders"] = round(ph_pts, 1)
    else:
        score += 5.0
        components["placeholders"] = 5.0

    # Ensemble convergence (up to 10 pts via ensemble_conf score)
    if ensemble_conf:
        ens_pts = ensemble_conf.get("score", 50) * 0.10
        score += ens_pts
        components["ensemble_convergencia"] = round(ens_pts, 1)
    else:
        components["ensemble_convergencia"] = 0.0

    return {
        "global_score": round(min(100.0, score), 1),
        "components":   components,
    }


def calculate_backtest_professional(store=None):
    """
    Extends calculate_backtest_metrics with Brier Score, Log Loss,
    and Calibration Curve using the backtest store.
    Returns full professional backtest dict.
    """
    if store is None:
        store = load_backtest_store()

    # Build predictions/outcomes list from settled bets that have prob stored
    predictions = []
    outcomes    = []
    for r in store:
        if r.get("result") not in ("win", "lose"):
            continue
        ph = r.get("prob_home")
        pd = r.get("prob_draw")
        pa = r.get("prob_away")
        oc = r.get("actual_outcome")  # "H", "D", "A"
        if ph is not None and pd is not None and pa is not None and oc in ("H", "D", "A"):
            predictions.append((ph, pd, pa))
            outcomes.append(oc)

    brier = calculate_brier_score(predictions, outcomes)
    logloss = calculate_log_loss(predictions, outcomes)
    calib = calculate_calibration_curve(predictions, outcomes)

    base = calculate_backtest_metrics(store)
    base["brier_score"]       = brier
    base["log_loss"]          = logloss
    base["calibration_curve"] = calib
    base["calibration_n"]     = len(predictions)

    # Calibration quality label
    if brier is None:
        base["calibration_label"] = "INSUFICIENTE (sem dados rotulados)"
    elif brier < 0.20:
        base["calibration_label"] = "🟢 BEM CALIBRADO"
    elif brier < 0.25:
        base["calibration_label"] = "🟡 CALIBRADO ACEITÁVEL"
    else:
        base["calibration_label"] = "🔴 MAL CALIBRADO"

    return base


# ── ETAPA 8 — PROBABILITY CALIBRATION (Platt Scaling, stdlib only) ────

def platt_scaling_calibrate(raw_prob, a_coeff=1.0, b_coeff=0.0):
    """
    Platt Scaling: calibrated = sigmoid(a * logit(p) + b)
    Default a=1, b=0 = identity (no calibration shift).
    a > 1 → spreads probabilities; b > 0 → shifts toward home.
    To fit: call fit_platt_scaling() on historical data.
    """
    import math as _m
    eps = 1e-7
    p = max(eps, min(1 - eps, raw_prob))
    logit = _m.log(p / (1 - p))
    return 1.0 / (1.0 + _m.exp(-(a_coeff * logit + b_coeff)))


def fit_platt_scaling(predictions_h, actuals_h, lr=0.01, epochs=200):
    """
    Fit Platt Scaling parameters (a, b) via gradient descent on log-loss.
    predictions_h: list of floats (predicted P(home_win))
    actuals_h:     list of 0/1 (1 if home won)
    Returns (a, b) to use in platt_scaling_calibrate().
    """
    import math as _m
    if not predictions_h or len(predictions_h) < 3:
        return 1.0, 0.0

    eps = 1e-7
    a = 1.0
    b = 0.0

    for _ in range(epochs):
        da = 0.0
        db = 0.0
        n  = len(predictions_h)
        for p_raw, y in zip(predictions_h, actuals_h):
            p_raw = max(eps, min(1 - eps, p_raw))
            logit = _m.log(p_raw / (1 - p_raw))
            z = a * logit + b
            sig = 1.0 / (1.0 + _m.exp(-z))
            err = sig - y
            da += err * logit / n
            db += err / n
        a -= lr * da
        b -= lr * db

    return round(a, 4), round(b, 4)


def calibrate_ensemble_probabilities(ensemble, platt_a=1.0, platt_b=0.0):
    """
    Applies Platt Scaling to ensemble home_win probability,
    redistributes draw/away_win proportionally.
    """
    if not ensemble:
        return ensemble
    raw_h = ensemble.get("home_win", 0.33)
    cal_h = platt_scaling_calibrate(raw_h, platt_a, platt_b)
    delta = cal_h - raw_h
    # Redistribute delta proportionally from draw + away_win
    raw_d = ensemble.get("draw", 0.33)
    raw_a = ensemble.get("away_win", 0.34)
    total_da = raw_d + raw_a if (raw_d + raw_a) > 0 else 1.0
    cal_d = max(0.0, raw_d - delta * (raw_d / total_da))
    cal_a = max(0.0, raw_a - delta * (raw_a / total_da))
    # Re-normalise
    s = cal_h + cal_d + cal_a
    if s > 0:
        cal_h /= s; cal_d /= s; cal_a /= s
    return {**ensemble, "home_win": round(cal_h, 4),
            "draw": round(cal_d, 4), "away_win": round(cal_a, 4),
            "_calibrated": True, "_platt_a": platt_a, "_platt_b": platt_b}


# ── ETAPA 9 — ML REAL (Logistic Regression, stdlib only) ─────────────

# Pre-computed coefficient vector from manual feature engineering.
# These weights were derived from domain knowledge + approximate gradient
# fitting on synthetic football data. No sklearn required.
_LR_WEIGHTS = {
    "elo_diff_norm":     0.82,
    "xg_diff_norm":      0.61,
    "form_diff":         0.44,
    "pi_diff_norm":      0.35,
    "rest_diff":         0.12,
    "odd_h_implied":    -0.55,
    "odd_a_implied":     0.55,
    "avg_gf_diff":       0.28,
    "avg_gc_diff":      -0.28,
    "ppda_diff":         0.18,
    "_bias_home":        0.15,
    "_bias_draw":       -0.40,
}


def _sigmoid(x):
    import math as _m
    try:
        return 1.0 / (1.0 + _m.exp(-x))
    except OverflowError:
        return 0.0 if x < 0 else 1.0


def ml_logistic_predict(features):
    """
    Logistic Regression with hand-tuned weights (no sklearn).
    Returns {"home_win": p_h, "draw": p_d, "away_win": p_a}
    or None if features are insufficient.
    """
    if not features:
        return None

    def _f(key, default=0.0):
        v = features.get(key, default)
        return float(v) if v is not None else default

    # Normalise ELO diff to [-1, 1]
    elo_diff = (_f("h_elo") - _f("a_elo")) / 400.0
    xg_diff  = (_f("h_wxg") - _f("a_wxg")) / 2.0
    form_h   = _f("h_form_pts", 0)
    form_a   = _f("a_form_pts", 0)
    form_diff = (form_h - form_a) / 15.0  # max ~15 pts in 5 games
    pi_diff  = (_f("h_pi") - _f("a_pi")) / 100.0
    rest_diff = (_f("h_rest_days", 4) - _f("a_rest_days", 4)) / 7.0
    odd_h    = _f("odd_h_implied", 0.33)
    odd_a    = _f("odd_a_implied", 0.33)
    gf_diff  = (_f("h_avg_gf", 1.2) - _f("a_avg_gf", 0.9)) / 2.0
    gc_diff  = (_f("h_avg_gc", 1.1) - _f("a_avg_gc", 1.0)) / 2.0

    # Score for home win
    z_h = (
        _LR_WEIGHTS["elo_diff_norm"] * elo_diff
        + _LR_WEIGHTS["xg_diff_norm"] * xg_diff
        + _LR_WEIGHTS["form_diff"] * form_diff
        + _LR_WEIGHTS["pi_diff_norm"] * pi_diff
        + _LR_WEIGHTS["rest_diff"] * rest_diff
        + _LR_WEIGHTS["odd_h_implied"] * odd_h
        + _LR_WEIGHTS["avg_gf_diff"] * gf_diff
        + _LR_WEIGHTS["avg_gc_diff"] * gc_diff
        + _LR_WEIGHTS["_bias_home"]
    )
    # Score for draw (less sensitive to elo/form)
    z_d = (
        0.3 * _LR_WEIGHTS["elo_diff_norm"] * abs(elo_diff)
        - 0.5 * abs(xg_diff)
        + _LR_WEIGHTS["_bias_draw"]
    )
    # Score for away win (mirror)
    z_a = (
        -_LR_WEIGHTS["elo_diff_norm"] * elo_diff
        - _LR_WEIGHTS["xg_diff_norm"] * xg_diff
        - _LR_WEIGHTS["form_diff"] * form_diff
        + _LR_WEIGHTS["odd_a_implied"] * odd_a
        - _LR_WEIGHTS["_bias_home"]
    )

    # Softmax normalisation
    import math as _m
    try:
        max_z = max(z_h, z_d, z_a)
        e_h = _m.exp(z_h - max_z)
        e_d = _m.exp(z_d - max_z)
        e_a = _m.exp(z_a - max_z)
        total = e_h + e_d + e_a
        ph = e_h / total
        pd = e_d / total
        pa = e_a / total
    except Exception:
        return None

    return {
        "home_win": round(ph, 4),
        "draw":     round(pd, 4),
        "away_win": round(pa, 4),
        "_source": "LR_manual",
    }


def extract_ml_features_v2(h_blended, a_blended, h_elo, a_elo,
                             h_pi, a_pi, h_rest, a_rest,
                             real_odds, ppda_h=None, ppda_a=None,
                             h_hist=None, a_hist=None):
    """Extended feature set for ml_logistic_predict."""
    def _safe(v, d=0.0):
        try: return float(v) if v is not None else d
        except: return d

    def _form_pts(hist, team_id, n=5):
        pts = 0
        for f in (hist or [])[:n]:
            tid = int(team_id)
            is_home = int(f["teams"]["home"]["id"]) == tid
            gf = f["goals"]["home"] if is_home else f["goals"]["away"]
            gc = f["goals"]["away"] if is_home else f["goals"]["home"]
            if gf is None or gc is None: continue
            if gf > gc: pts += 3
            elif gf == gc: pts += 1
        return pts

    return {
        "h_elo":       _safe((h_elo or {}).get("elo"), 1500),
        "a_elo":       _safe((a_elo or {}).get("elo"), 1500),
        "h_wxg":       _safe((h_blended or {}).get("avg_gf"), 1.2),
        "a_wxg":       _safe((a_blended or {}).get("avg_gf"), 0.9),
        "h_form_pts":  _form_pts(h_hist, (h_elo or {}).get("team_id", 0)),
        "a_form_pts":  _form_pts(a_hist, (a_elo or {}).get("team_id", 0)),
        "h_pi":        _safe((h_pi or {}).get("index"), 50),
        "a_pi":        _safe((a_pi or {}).get("index"), 50),
        "h_rest_days": _safe(h_rest, 4),
        "a_rest_days": _safe(a_rest, 4),
        "h_avg_gf":    _safe((h_blended or {}).get("avg_gf"), 1.2),
        "a_avg_gf":    _safe((a_blended or {}).get("avg_gf"), 0.9),
        "h_avg_gc":    _safe((h_blended or {}).get("avg_gc"), 1.1),
        "a_avg_gc":    _safe((a_blended or {}).get("avg_gc"), 1.0),
        "odd_h_implied": _safe(1.0 / real_odds["home"] if real_odds and real_odds.get("home") else None, 0.33),
        "odd_a_implied": _safe(1.0 / real_odds["away"] if real_odds and real_odds.get("away") else None, 0.33),
        "ppda_diff":   _safe((ppda_h or {}).get("ppda"), 10) - _safe((ppda_a or {}).get("ppda"), 10),
    }


# ── ETAPA 10 — EXPLAINABILITY TOTAL ───────────────────────────────────

def generate_explainability_total(
        ensemble, model_audit, lambda_explainer,
        h_elo, a_elo, h_pi, a_pi,
        field_tilt, xthreat, climate_impact,
        fatigue_h, fatigue_a,
        ppda_h, ppda_a, sos_h, sos_a,
        h_name="Casa", a_name="Fora"):
    """
    Extended explainability panel. Shows contribution of each factor
    including lambda decomposition and model divergence.
    """
    def _safe(v, d=0.0):
        try: return float(v) if v is not None else d
        except: return d

    hw = _safe(ensemble.get("home_win") if ensemble else None, 0.33)
    dr = _safe(ensemble.get("draw") if ensemble else None, 0.33)
    aw = _safe(ensemble.get("away_win") if ensemble else None, 0.34)

    contribs = {}

    # ELO
    h_elo_v = _safe((h_elo or {}).get("elo"), 1500)
    a_elo_v = _safe((a_elo or {}).get("elo"), 1500)
    elo_diff = h_elo_v - a_elo_v
    contribs["ELO"] = {
        "home": round(elo_diff * 0.015, 2),
        "draw": round(-abs(elo_diff) * 0.003, 2),
        "away": round(-elo_diff * 0.015, 2),
    }

    # xG / Lambda
    if lambda_explainer:
        lh = _safe(lambda_explainer.get("h_lambda_adjusted"), 1.2)
        la = _safe(lambda_explainer.get("a_lambda_adjusted"), 0.9)
        lam_diff = lh - la
        contribs["xG/Lambda"] = {
            "home": round(lam_diff * 4.5, 2),
            "draw": round(-abs(lam_diff) * 1.5, 2),
            "away": round(-lam_diff * 4.5, 2),
        }

    # Pressure Index
    h_pi_v = _safe((h_pi or {}).get("index"), 50)
    a_pi_v = _safe((a_pi or {}).get("index"), 50)
    pi_diff = h_pi_v - a_pi_v
    contribs["Pressure"] = {
        "home": round(pi_diff * 0.06, 2),
        "draw": 0.0,
        "away": round(-pi_diff * 0.06, 2),
    }

    # Field Tilt
    if field_tilt:
        ft_h = _safe(field_tilt.get("home_tilt"), 50)
        ft_diff = ft_h - 50
        contribs["FieldTilt"] = {
            "home": round(ft_diff * 0.04, 2),
            "draw": 0.0,
            "away": round(-ft_diff * 0.04, 2),
        }

    # Climate
    if climate_impact:
        cli = _safe(climate_impact.get("xg_coeff"), 1.0) - 1.0
        contribs["Clima"] = {
            "home": round(cli * 3.0, 2),
            "draw": round(cli * 1.0, 2),
            "away": round(cli * 3.0, 2),
        }

    # Fatigue differential (fatigue may be float or dict)
    def _fi_val(fat):
        if fat is None: return 0.0
        if isinstance(fat, (int, float)): return float(fat)
        return float((fat or {}).get("fatigue_index") or 0)

    if fatigue_h is not None and fatigue_a is not None:
        fi_h = _fi_val(fatigue_h)
        fi_a = _fi_val(fatigue_a)
        fat_diff = fi_a - fi_h  # positive if away is more fatigued
        contribs["Fadiga"] = {
            "home": round(fat_diff * 0.03, 2),
            "draw": 0.0,
            "away": round(-fat_diff * 0.03, 2),
        }

    # PPDA (pressing quality)
    if ppda_h and ppda_a:
        ph_v = _safe(ppda_h.get("ppda"), 10)
        pa_v = _safe(ppda_a.get("ppda"), 10)
        # Lower PPDA = better pressing; home advantage if lower PPDA
        ppda_diff = pa_v - ph_v
        contribs["PPDA"] = {
            "home": round(ppda_diff * 0.15, 2),
            "draw": 0.0,
            "away": round(-ppda_diff * 0.15, 2),
        }

    # SOS advantage
    if sos_h and sos_a:
        sos_h_v = _safe((sos_h or {}).get("avg_opp_elo"), 1500)
        sos_a_v = _safe((sos_a or {}).get("avg_opp_elo"), 1500)
        sos_diff = sos_a_v - sos_h_v  # away team faced harder opponents → slight boost
        contribs["SOS"] = {
            "home": round(-sos_diff * 0.005, 2),
            "draw": 0.0,
            "away": round(sos_diff * 0.005, 2),
        }

    # Model divergence note
    divergence_note = None
    if model_audit:
        worst = max(model_audit.items(), key=lambda x: x[1].get("std", 0))
        if worst[1].get("std", 0) > 0.07:
            divergence_note = f"Alta divergência em {worst[0]} (σ={worst[1]['std']:.3f})"

    return {
        "home_win_pct":    round(hw * 100, 1),
        "draw_pct":        round(dr * 100, 1),
        "away_win_pct":    round(aw * 100, 1),
        "contributions":   contribs,
        "divergence_note": divergence_note,
        "lambda_home":     (lambda_explainer or {}).get("home"),
        "lambda_away":     (lambda_explainer or {}).get("away"),
    }


# ── ETAPA 11 — EV+ VALIDATION ─────────────────────────────────────────

def validate_high_ev(ev_report, model_audit, ensemble, threshold=0.20):
    """
    Flags any EV > threshold for multi-model divergence audit.
    Returns list of validated/flagged EV opportunities with risk level.
    """
    if not ev_report:
        return []

    flagged = []
    markets = ev_report.get("markets", []) if isinstance(ev_report, dict) else []

    for mkt in markets:
        ev = mkt.get("ev", 0.0) if isinstance(mkt, dict) else 0.0
        if ev >= threshold:
            outcome = mkt.get("outcome", "?")
            odd     = mkt.get("odd", 0.0)

            # Check model divergence for this outcome
            outcome_key = None
            if "casa" in str(outcome).lower() or "home" in str(outcome).lower():
                outcome_key = "home_win"
            elif "empate" in str(outcome).lower() or "draw" in str(outcome).lower():
                outcome_key = "draw"
            elif "fora" in str(outcome).lower() or "away" in str(outcome).lower():
                outcome_key = "away_win"

            divergence = None
            models_row = {}
            if model_audit and outcome_key and outcome_key in model_audit:
                audit_oc = model_audit[outcome_key]
                divergence = audit_oc.get("std", 0.0)
                models_row = audit_oc.get("models", {})
                convergence = audit_oc.get("convergence", "?")
            else:
                convergence = "DESCONHECIDA"

            # Risk level
            if divergence is None or divergence < 0.04:
                risk = "🟢 BAIXO RISCO"
                action = "APOSTAR"
            elif divergence < 0.08:
                risk = "🟡 RISCO MODERADO"
                action = "CAUTELA"
            else:
                risk = "🔴 ALTO RISCO — DIVERGÊNCIA"
                action = "EVITAR"

            flagged.append({
                "outcome":     outcome,
                "odd":         odd,
                "ev":          round(ev, 4),
                "ev_pct":      round(ev * 100, 1),
                "divergence":  round(divergence, 4) if divergence is not None else None,
                "convergence": convergence,
                "risk":        risk,
                "action":      action,
                "models":      models_row,
            })

    return flagged


def _render_calibration_panels(
        lambda_trace=None,
        model_audit=None,
        lambda_explainer=None,
        confidence_v2=None,
        backtest_pro=None,
        placeholder_detector=None,
        ev_validation=None,
        explainability_total=None,
        consistency_audit=None,
        global_confidence=None,
        h_name="Casa", a_name="Fora",
        W=70):
    """Renders all FASE DE CALIBRAÇÃO PROFISSIONAL panels."""

    def _row(txt=""):
        line = f"║  {txt}"
        print(line.ljust(W + 1) + "║")

    def _sep():
        print("╠" + "─" * W + "╣")

    def _section(title):
        print("╠" + "═" * W + "╣")
        _row(title)
        print("╠" + "─" * W + "╣")

    print("╔" + "═" * W + "╗")
    _row("🔬 FASE DE CALIBRAÇÃO PROFISSIONAL")
    print("╠" + "═" * W + "╣")

    # ── LAMBDA TRACE ENGINE ──────────────────────────────────────────
    if lambda_trace:
        _section("🧮 LAMBDA TRACE ENGINE — RASTREAMENTO COMPLETO")
        for side, sname in [("home", h_name), ("away", a_name)]:
            d = lambda_trace.get(side, {})
            if not d:
                continue
            lf = d.get("lambda_final", 0)
            gf = d.get("base_gf", 0)
            compress = d.get("compression_pct", 0)
            warn = d.get("warning", False)
            _row(f"▶ {sname[:30]}")
            _row(f"  GF histórico:      {gf:.3f}  |  xG ponderado:   {d.get('base_xg',0):.3f}")
            _row(f"  Blend (60% xG+40% GF): {d.get('blend_inicial',0):.3f}")
            _row(f"  Defesa adversária: {d.get('def_adj',0):+.3f}  |  Field Tilt: {d.get('field_tilt_adj',0):+.3f}")
            _row(f"  PPDA:              {d.get('ppda_adj',0):+.3f}  |  Clima:     {d.get('clima_adj',0):+.3f}")
            _row(f"  Fadiga:            {d.get('fadiga_adj',0):+.3f}  |  Floor:    {d.get('floor',0):.3f}")
            _row(f"  λ antes do floor:  {d.get('lambda_pre_floor',0):.3f}")
            _row(f"  λ FINAL:           {lf:.3f}   (compressão vs GF: {compress:.1f}%)"
                 + ("  ⚠️ POSSÍVEL COMPRESSÃO EXCESSIVA" if warn else ""))
            if warn:
                _row(f"  ⚠️  λ={lf:.3f} < GF={gf:.3f}×0.60 — Verificar dados de xG")
            if side == "home" and lambda_trace.get("away"):
                _sep()

    # ── MODEL AUDITOR ────────────────────────────────────────────────
    if model_audit:
        _section("📊 AUDITOR DE MODELOS (5 modelos × 3 resultados)")
        _row(f"{'RESULTADO':<12}  {'POISSON':>8}  {'MC':>8}  {'ELO':>8}  {'ML':>8}  {'API':>8}  {'σ':>6}  {'CONV':<14}")
        _sep()
        labels = {"home_win": f"Casa ({h_name[:8]})", "draw": "Empate", "away_win": f"Fora ({a_name[:8]})"}
        for oc, label in labels.items():
            if oc not in model_audit:
                continue
            a = model_audit[oc]
            m = a.get("models", {})
            def _pct(key):
                v = m.get(key)
                return f"{v*100:.0f}%" if v is not None else "N/D"
            std_s = f"{a['std']*100:.1f}%" if a.get("std") is not None else "?"
            _row(f"{label:<12}  {_pct('Poisson'):>8}  {_pct('MonteCarlo'):>8}  "
                 f"{_pct('ELO'):>8}  {_pct('ML'):>8}  {_pct('API'):>8}  "
                 f"{std_s:>6}  {a.get('convergence','?'):<14}")
        _sep()
        worst_oc = max(model_audit.items(), key=lambda x: x[1].get("std", 0))
        _row(f"Maior divergência: {worst_oc[0]}  (σ={worst_oc[1].get('std',0)*100:.1f}%)")

    # ── LAMBDA EXPLAINER ─────────────────────────────────────────────
    if lambda_explainer:
        _section("🧮 LAMBDA EXPLAINER — DECOMPOSIÇÃO COMPLETA")
        for side, sname in [("home", h_name), ("away", a_name)]:
            d = lambda_explainer.get(side, {})
            if not d:
                continue
            _row(f"▶ {sname[:30]}")
            _row(f"  Base ofensiva:      {d.get('base_ofensiva', 0):.3f} avg_gf")
            _row(f"  Defesa adversária:  {d.get('base_defensiva_opp', 0):.3f} avg_gc opp")
            _row(f"  xG próprio (wXG):   {d.get('xG_proprio', 0):.3f}")
            _row(f"  xGA adversário:     {d.get('xGA_adversario', 0):.3f}")
            _row(f"  λ (xG formula):     {d.get('lambda_xg', 0):.3f}  (0.55×xG + 0.45×xGA_opp)")
            _row(f"  Coef. clima:        {d.get('clima_coeff', 1):.3f}  [{d.get('clima_nota','?')[:35]}]")
            _row(f"  Coef. fadiga:       {d.get('fadiga_coeff', 1):.3f}")
            _row(f"  λ FINAL AJUSTADO:   {d.get('lambda_final', 0):.3f}")
            if side == "home" and lambda_explainer.get("away"):
                _sep()

    # ── PLACEHOLDER DETECTOR ─────────────────────────────────────────
    if placeholder_detector:
        _section("🔍 DETECTOR DE PLACEHOLDERS")
        ph = placeholder_detector
        _row(f"Status: {ph.get('status','?')}  |  Total: {ph.get('placeholder_count',0)} placeholder(s)")
        _sep()
        for issue in (ph.get("issues") or []):
            _row(f"  ⚠️  {issue[:62]}")
        if not ph.get("issues"):
            _row("  ✅ Nenhum placeholder crítico detectado")

    # ── CONFIDENCE SCORE 2.0 ─────────────────────────────────────────
    if confidence_v2:
        _section("🎯 CONFIDENCE SCORE 2.0")
        cv2 = confidence_v2
        sc = cv2.get("score", 0)
        bar = "█" * int(sc // 5) + "░" * (20 - int(sc // 5))
        _row(f"Score: {sc:.1f}/100  [{bar}]")
        _row(f"Status: {cv2.get('label','?')}")
        _sep()
        dims = cv2.get("dimensions", {})
        for k, v in dims.items():
            _row(f"  {k:<20}  {v:>5.1f} pts")
        _sep()
        for note in (cv2.get("notes") or []):
            _row(f"  ⚠️  {note[:62]}")

    # ── BACKTEST PROFISSIONAL ────────────────────────────────────────
    if backtest_pro:
        _section("📈 BACKTEST PROFISSIONAL")
        bp = backtest_pro
        _row(f"Apostas: {bp.get('total_bets',0)}  |  ROI: {bp.get('roi',0):+.2f}%  |  Hit Rate: {bp.get('hit_rate',0):.1f}%")
        _row(f"Brier Score: {bp.get('brier_score') or 'N/D'}  |  Log Loss: {bp.get('log_loss') or 'N/D'}")
        _row(f"Calibração: {bp.get('calibration_label', 'INSUFICIENTE (sem dados)')}")
        calib_n = bp.get("calibration_n", 0)
        _row(f"  (baseado em {calib_n} apostas com resultado real rotulado)")
        if bp.get("calibration_curve"):
            _sep()
            _row(f"{'Bin':<8}  {'Pred%':>6}  {'Real%':>6}  {'Gap':>6}  {'N':>4}")
            for bin_d in bp["calibration_curve"]:
                _row(f"  {bin_d['range']:<8}  {bin_d['mean_pred']*100:>5.1f}%  "
                     f"{bin_d['mean_act']*100:>5.1f}%  {bin_d['gap']*100:>5.1f}%  {bin_d['n']:>4}")

    # ── EV+ VALIDATION ────────────────────────────────────────────────
    if ev_validation:
        _section("💰 VALIDAÇÃO EV+ (EV ≥ 20%)")
        if not ev_validation:
            _row("  Nenhum mercado com EV ≥ 20% detectado")
        for item in ev_validation:
            _row(f"  {item['outcome'][:30]}  odd={item['odd']:.2f}  EV={item['ev_pct']:+.1f}%")
            _row(f"     {item['risk']}  |  {item['action']}")
            if item.get("divergence") is not None:
                _row(f"     Divergência modelos: σ={item['divergence']*100:.1f}%  [{item['convergence']}]")
            _sep()

    # ── EXPLAINABILITY TOTAL ──────────────────────────────────────────
    if explainability_total:
        _section("🔎 EXPLICABILIDADE TOTAL")
        et = explainability_total
        hw_p = et.get("home_win_pct", 0)
        dr_p = et.get("draw_pct", 0)
        aw_p = et.get("away_win_pct", 0)
        _row(f"Vitória {h_name[:12]}: {hw_p:.1f}%  |  Empate: {dr_p:.1f}%  |  Vitória {a_name[:12]}: {aw_p:.1f}%")
        if et.get("divergence_note"):
            _row(f"  ⚠️  {et['divergence_note']}")
        _sep()
        _row(f"{'FATOR':<16}  {'CASA':>8}  {'EMPATE':>8}  {'FORA':>8}")
        _sep()
        for factor, contrib in (et.get("contributions") or {}).items():
            h_c = contrib.get("home", 0)
            d_c = contrib.get("draw", 0)
            a_c = contrib.get("away", 0)
            _row(f"{factor:<16}  {h_c:>+7.2f}%  {d_c:>+7.2f}%  {a_c:>+7.2f}%")
        # Lambda breakdown
        lam_h = et.get("lambda_home")
        lam_a = et.get("lambda_away")
        if lam_h:
            _sep()
            _row(f"λ {h_name[:12]}: xG={lam_h.get('xG_proprio',0):.3f} → λ_final={lam_h.get('lambda_final',0):.3f}")
        if lam_a:
            _row(f"λ {a_name[:12]}: xG={lam_a.get('xG_proprio',0):.3f} → λ_final={lam_a.get('lambda_final',0):.3f}")

    # ── CONSISTENCY AUDIT (Correction 4) ─────────────────────────────
    if consistency_audit:
        _section("🔍 AUDITOR DE CONSISTÊNCIA GLOBAL")
        level = consistency_audit.get("level", "?")
        std   = consistency_audit.get("std_dev", 0)
        imp   = consistency_audit.get("impact_on_confidence", 0)
        mods  = ", ".join(consistency_audit.get("models_used", []))
        level_icon = {"CRÍTICA": "🔴", "ALTA": "🟠", "MÉDIA": "🟡", "BAIXA": "🟢"}.get(level, "⚪")
        _row(f"{level_icon} Nível: {level}  |  σ home_win: {std*100:.1f}%  |  Impacto confiança: {imp:+d}pts")
        _row(f"Modelos usados: {mods or 'N/D'}")
        for conf_msg in (consistency_audit.get("conflicts") or []):
            _row(f"  ⚠️  {conf_msg[:65]}")
        if not consistency_audit.get("conflicts"):
            _row("  ✅ Sem conflitos detectados entre ensemble e cenários")

    # ── GLOBAL CONFIDENCE (Correction 6) ─────────────────────────────
    if global_confidence:
        _section("🎯 CONFIANÇA GLOBAL UNIFICADA")
        gs = global_confidence.get("global_score", 0)
        bar = "█" * int(gs // 5) + "░" * (20 - int(gs // 5))
        _row(f"Confiança Global: {gs:.1f}/100  [{bar}]")
        _sep()
        for comp_name, comp_val in (global_confidence.get("components") or {}).items():
            _row(f"  {comp_name:<26}  {comp_val:>5.1f} pts")

    print("╚" + "═" * W + "╝")


def _is_valid_api_pred(api_pred):
    """
    CORRECTION 8 — API Prediction Sanitizer.
    Returns False if api_pred is empty/zeroed, skipping section in render.
    """
    if not api_pred:
        return False
    try:
        ph = float(str(api_pred.get("percent_home", "0")).replace("%", "") or 0)
        pd = float(str(api_pred.get("percent_draw", "0")).replace("%", "") or 0)
        pa = float(str(api_pred.get("percent_away", "0")).replace("%", "") or 0)
    except (TypeError, ValueError):
        return False
    if ph == 0 and pd == 0 and pa == 0:
        return False
    comp = api_pred.get("comparison", {}) or {}
    try:
        att = comp.get("att", {}) or {}
        atk_h = float(str(att.get("home", "0")).replace("%", "") or 0) if att else 0
    except (TypeError, ValueError):
        atk_h = 0
    if atk_h == 0 and ph == 0:
        return False
    return True


def _render_pre_game_dashboard(
        h_name, a_name, fixture_id,
        h_id, a_id,
        h_form, a_form,
        h2h_list,
        h_blended, a_blended,
        h_elo, a_elo, elo_probs,
        h_pi, a_pi,
        adv_corners,
        mc, ref_stats, real_referee,
        ensemble, conf,
        ev_final,
        xg_lh, xg_la,
        h_standing=None, a_standing=None,
        h_players=None, a_players=None,
        lineups=None,
        api_pred=None,
        weather=None,
        venue=None,
        all_odds=None,
        match_datetime=None,
        league_name=None,
        ev_report=None,
        recommendations=None,
        # V5 — new modules
        h_tactical=None, a_tactical=None,
        tactical_matchup=None,
        scenarios=None,
        narrative=None,
        climate_impact=None,
        fatigue_h=None, fatigue_a=None,
        sos_h=None, sos_a=None,
        ppda_h=None, ppda_a=None,
        field_tilt=None,
        xthreat=None,
        prog_h=None, prog_a=None,
        zones_h=None, zones_a=None,
        goals_period_h=None, goals_period_a=None,
        corners_period_h=None, corners_period_a=None,
        cards_period_h=None, cards_period_a=None,
        dominance_score=None,
        prediction_confidence=None,
        player_impact=None,
        explainability=None,
        data_quality=None,
        # FASE DE CALIBRAÇÃO PROFISSIONAL
        lambda_trace=None,
        model_audit=None,
        lambda_explainer_data=None,
        confidence_v2=None,
        backtest_pro=None,
        placeholder_detector=None,
        ev_validation=None,
        explainability_total=None,
        global_confidence=None,
        consistency_audit=None,
        W=70):
    """Renderiza toda a análise pré-jogo em formato visual profissional."""

    res_icon = {"V": "🟢", "E": "🟡", "D": "🔴"}

    def _row(text):
        print(f"║  {text}".ljust(W+1) + "║")

    def _sep():
        print("║" + "─"*W + "║")

    def _section(title):
        print("╠" + "═"*W + "╣")
        print(f"║  {title}".ljust(W+1) + "║")
        _sep()

    # ── HEADER ───────────────────────────────────────────────────────
    print("╔" + "═"*W + "╗")
    print(f"║  ⚽  ANÁLISE PRÉ-JOGO V3 PRO".ljust(W+1) + "║")
    print(f"║  {h_name}  x  {a_name}".ljust(W+1) + "║")
    if match_datetime:
        _row(f"📅 {match_datetime[:16]}  —  {league_name or 'Liga não identificada'}")
    if venue and venue.get("name") and venue["name"] != "?":
        _row(f"🏟️  {venue['name']}, {venue['city']}  |  Capacidade: {venue['capacity']}")

    # ── CLIMA ─────────────────────────────────────────────────────────
    if weather:
        _section(f"{weather['icon']} CONDIÇÕES CLIMÁTICAS — {weather['city']}")
        _row(f"{weather['desc']}  |  {weather['temp_c']}°C  (sensação {weather['feels_like']}°C)")
        _row(f"💨 Vento: {weather['wind_kmph']}km/h {weather['wind_dir']}  |  💧 Precip: {weather['precip_mm']}mm  |  ☁️ Nuvens: {weather['cloud']}%")
        _row(f"💦 Umidade: {weather['humidity']}%  |  👁️ Visib.: {weather['visibility']}km  |  ☀️ UV: {weather['uv']}")
        _sep()
        for imp in weather["impacts"]:
            _row(imp)
        if weather.get("forecast"):
            _sep()
            _row("Previsão hora a hora:")
            buf = ""
            for h in weather["forecast"]:
                hh = str(int(h["time"])//100).zfill(2) + "h"
                buf += f"  {hh}: {h['temp']}°C {h['desc'][:10]:<10}"
            _row(buf.strip())

    # ── CLASSIFICAÇÃO ─────────────────────────────────────────────────
    if h_standing or a_standing:
        _section("📊 CLASSIFICAÇÃO")
        _row(f"{'CLUBE':<24}  {'#':>3}  {'P':>3}  {'J':>3}  {'V':>3}  {'E':>3}  {'D':>3}  {'GF':>4}  {'GC':>4}  {'SG':>4}")
        _sep()
        for name, st in [(h_name, h_standing), (a_name, a_standing)]:
            if st:
                _row(f"{name[:24]:<24}  {st['rank']:>3}  {st['points']:>3}  {st['played']:>3}  {st['won']:>3}  {st['drawn']:>3}  {st['lost']:>3}  {st['gf']:>4}  {st['ga']:>4}  {st['gd']:>+4}")
                form_icons = "".join(
                    "🟢" if r == "W" else ("🟡" if r == "D" else "🔴")
                    for r in (st.get("form") or "")[-5:]
                )
                _row(f"   Forma liga: {form_icons}  |  Casa {st['home_w']}V/{st['home_d']}E/{st['home_l']}D  |  Fora {st['away_w']}V/{st['away_d']}E/{st['away_l']}D")
                if st.get("description"):
                    _row(f"   → {st['description'][:55]}")

    # ── FORMA RECENTE ─────────────────────────────────────────────────
    _section("📋 FORMA RECENTE (últimos 5 jogos)")
    for name, form in [(h_name, h_form), (a_name, a_form)]:
        icons = "   ".join(f"{res_icon.get(g['res'],'⚪')} {g['gf']}-{g['gc']}" for g in form)
        _row(f"{name[:20]:<20}  {icons}")
        for g in form:
            _row(f"   {g['date']}  vs {g['opp']:<17} [{g['venue']}]  {g['gf']}-{g['gc']}  {res_icon.get(g['res'],'⚪')}")
        if name == h_name:
            _sep()

    # ── H2H ──────────────────────────────────────────────────────────
    if h2h_list:
        _section(f"⚔️  CONFRONTO DIRETO — últimos {len(h2h_list)} jogos")
        h_w = a_w = dr = gf_t = gc_t = 0
        for f in h2h_list:
            gh = f["goals"].get("home") or 0
            ga = f["goals"].get("away") or 0
            date = f["fixture"]["date"][:10]
            hn   = f["teams"]["home"]["name"][:14]
            an   = f["teams"]["away"]["name"][:14]
            fid_h = int(f["teams"]["home"]["id"])
            is_h  = fid_h == int(h_id)
            gf = gh if is_h else ga
            gc = ga if is_h else gh
            gf_t += gf; gc_t += gc
            win_icon = "━" if gh == ga else ("◀" if gh > ga else "▶")
            mark = "🟢" if (is_h and gh > ga) or (not is_h and ga > gh) else ("🟡" if gh == ga else "🔴")
            _row(f"{mark} {date}  {hn:<14} {gh}-{ga} {an:<14}  {win_icon}")
            if is_h:
                if gh > ga: h_w += 1
                elif gh == ga: dr += 1
                else: a_w += 1
            else:
                if ga > gh: h_w += 1
                elif gh == ga: dr += 1
                else: a_w += 1
        n  = len(h2h_list)
        _sep()
        _row(f"🟢 {h_name[:14]}: {h_w}V  🟡 Empates: {dr}  🔴 {a_name[:14]}: {a_w}  (total {n} jogos)")
        _row(f"Média gols H2H: {h_name[:10]} {gf_t/n:.2f}/j  |  {a_name[:10]} {gc_t/n:.2f}/j  |  Total: {(gf_t+gc_t)/n:.2f} gols/j")

    # ── ESCALAÇÕES ───────────────────────────────────────────────────
    if lineups:
        _section("👕 ESCALAÇÕES (divulgadas)")
        for tl in lineups[:2]:
            tname = tl.get("team", {}).get("name", "?")[:22]
            form  = tl.get("formation", "?")
            coach = tl.get("coach", {}).get("name", "?")[:20]
            _row(f"{tname:<22}  Formação: {form}  |  Técnico: {coach}")
            starters = [p["player"]["name"][:18] for p in tl.get("startXI", [])]
            for i in range(0, len(starters), 3):
                chunk = starters[i:i+3]
                _row("   " + "   ".join(f"{i+j+1:2}. {n:<18}" for j, n in enumerate(chunk)))
            _sep()

    # ── JOGADORES-CHAVE ───────────────────────────────────────────────
    if h_players or a_players:
        _section("⭐ JOGADORES-CHAVE / ARTILHEIROS")
        _row(f"{'JOGADOR':<22}  {'TIME':<16}  {'POS':<5}  {'J':>4}  {'G':>4}  {'A':>4}  {'NOTA':>6}")
        _sep()
        for plist, tname in [(h_players or [], h_name), (a_players or [], a_name)]:
            for p in plist[:5]:
                _row(f"{p['name'][:22]:<22}  {tname[:16]:<16}  {p['position'][:5]:<5}  {p['apps']:>4}  {p['goals']:>4}  {p['assists']:>4}  {str(p['rating'])[:6]:>6}")

    # ── ELO ──────────────────────────────────────────────────────────
    _section("♟️  ELO RATING")
    _row(f"{h_name[:28]:<28}  ELO: {h_elo['elo']:>4}  Tend: {h_elo['trend']:+.1f}  ({h_elo['games']} jogos)")
    _row(f"{a_name[:28]:<28}  ELO: {a_elo['elo']:>4}  Tend: {a_elo['trend']:+.1f}  ({a_elo['games']} jogos)")
    _row(f"Vitória Mand.: {elo_probs['home_win']*100:.1f}%  |  Empate: {elo_probs['draw']*100:.1f}%  |  Vitória Visit.: {elo_probs['away_win']*100:.1f}%")

    # ── MÉTRICAS OFENSIVAS ────────────────────────────────────────────
    _section("📈 MÉTRICAS OFENSIVAS (70% casa/fora + 30% geral)")
    _row(f"{'MÉTRICA':<24}  {h_name[:14]:>14}  {a_name[:14]:>14}")
    _sep()
    sot_h = h_blended.get("avg_sot", 0)
    sot_a = a_blended.get("avg_sot", 0)
    sh_h  = max(h_blended.get("avg_shots", 1), 1)
    sh_a  = max(a_blended.get("avg_shots", 1), 1)
    for label, key in [
        ("Gols marcados/jogo",   "avg_gf"),
        ("Gols sofridos/jogo",   "avg_gc"),
        ("Chutes totais/jogo",   "avg_shots"),
        ("Chutes no alvo/jogo",  "avg_sot"),
        ("Precisão ofensiva (%)", "_sot_pct"),
        ("Escanteios/jogo",      "avg_corners"),
        ("Posse de bola (%)",    "avg_possession"),
    ]:
        if key == "_sot_pct":
            hv = round(sot_h / sh_h * 100, 1)
            av = round(sot_a / sh_a * 100, 1)
            _row(f"{label:<24}  {hv:>14.1f}%  {av:>14.1f}%")
        else:
            hv = h_blended.get(key, 0)
            av = a_blended.get(key, 0)
            _row(f"{label:<24}  {hv:>14.2f}  {av:>14.2f}")

    # ── PRESSURE INDEX ────────────────────────────────────────────────
    _section("💥 PRESSURE INDEX HISTÓRICO")
    for name, pi in [(h_name, h_pi), (a_name, a_pi)]:
        bar = _render_bar(pi["index"], 100, 22)
        _row(f"{name[:22]:<22}  {pi['index']:>3}/100  {bar}  {pi['label']}")

    # ── ESCANTEIOS ────────────────────────────────────────────────────
    _section("🚩 MODELO DE ESCANTEIOS")
    _row(f"Esperados: {h_name[:14]}={adv_corners['h_expected_corners']}  |  {a_name[:14]}={adv_corners['a_expected_corners']}  |  Total: {adv_corners['total_expected']}")
    dom = "Mandante domina" if adv_corners["corner_pressure"] > 0 else "Visitante domina"
    _row(f"Pressão lateral: {adv_corners['corner_pressure']:+.1f}%  ({dom})")
    over_items = sorted(
        [(k.replace("over_","").replace("_","."), v) for k, v in adv_corners["probabilities"].items()],
        key=lambda x: float(x[0])
    )
    _row("  ".join(
        f"{'🟢' if p>0.60 else ('🟡' if p>0.40 else '🔴')} Over {k}: {p*100:.0f}%"
        for k, p in over_items
    ))
    # Corner Trace (Correction 7)
    ct = adv_corners.get("corner_trace")
    if ct:
        _sep()
        _row(f"Corner Trace — Base histórico: {ct['base_historical']}  |  Pressão: {ct['pressure_adj']:+.2f}  |  Posse: {ct['possession_adj']:+.2f}")
        cap_note = "  ⚠️ CAP 1.50x APLICADO" if ct.get("max_cap_applied") else ""
        _row(f"Total projetado: {ct['total_expected']}{cap_note}")

    # ── ÁRBITRO ───────────────────────────────────────────────────────
    _section("🟨 ÁRBITRO")
    if ref_stats:
        _row(f"{real_referee}  —  {ref_stats['games_sampled']} jogos analisados")
        _row(f"Amarelos/jogo: {ref_stats['avg_yellows_per_game']}  |  Vermelhos/jogo: {ref_stats['avg_reds_per_game']}")
        _row(f"Referee Score: {ref_stats['referee_score']}/100 → {ref_stats['label']}")
    elif real_referee:
        _row(f"{real_referee}  (histórico disciplinar não disponível)")
    else:
        _row("Árbitro não divulgado.")

    # ── PREDIÇÃO NATIVA DA API-FOOTBALL ──────────────────────────────
    if _is_valid_api_pred(api_pred):
        _section("🔮 PREDIÇÃO NATIVA — API-FOOTBALL")
        _row(f"💬 Conselho: {api_pred['advice']}")
        _row(f"🏆 Vencedor previsto: {api_pred['winner_name']}  |  {api_pred['winner_comment']}")
        _row(f"⚽ Gols esperados: {h_name[:12]} {api_pred['goals_h']}  |  {a_name[:12]} {api_pred['goals_a']}")
        _row(f"📊 Prob API: Casa {api_pred['percent_home']}  |  Empate {api_pred['percent_draw']}  |  Fora {api_pred['percent_away']}")
        _sep()
        _row(f"Ataque (API):  {h_name[:14]} {api_pred['comp_att_h']}  vs  {a_name[:14]} {api_pred['comp_att_a']}")
        _row(f"Defesa (API):  {h_name[:14]} {api_pred['comp_def_h']}  vs  {a_name[:14]} {api_pred['comp_def_a']}")
        _row(f"Forma (API):   {h_name[:14]} {api_pred['comp_form_h']}  vs  {a_name[:14]} {api_pred['comp_form_a']}")
        _row(f"Poisson (API): {h_name[:14]} {api_pred['comp_poisson_h']}  vs  {a_name[:14]} {api_pred['comp_poisson_a']}")
        _sep()
        _row(f"Últ.5 {h_name[:12]}: {api_pred['h_last5_w']}V {api_pred['h_last5_d']}E {api_pred['h_last5_l']}D  GF:{api_pred['h_last5_gf']}/j  GA:{api_pred['h_last5_ga']}/j")
        _row(f"Últ.5 {a_name[:12]}: {api_pred['a_last5_w']}V {api_pred['a_last5_d']}E {api_pred['a_last5_l']}D  GF:{api_pred['a_last5_gf']}/j  GA:{api_pred['a_last5_ga']}/j")

    # ── MONTE CARLO ───────────────────────────────────────────────────
    _section(f"🎲 MONTE CARLO 100k  λ {h_name[:12]}={mc['lambda_used']['home']}  λ {a_name[:12]}={mc['lambda_used']['away']}")
    scores  = mc["top_scores"][:8]
    markets = [
        ("Vitória Mandante",    mc["home_win"]),
        ("Empate",              mc["draw"]),
        ("Vitória Visitante",   mc["away_win"]),
        ("BTTS (ambos marcam)", mc["btts"]),
        ("Over 1.5 gols",       mc["over15"]),
        ("Over 2.5 gols",       mc["over25"]),
        ("Over 3.5 gols",       mc["over35"]),
        ("Under 2.5 gols",      1 - mc["over25"]),
    ]
    _row(f"{'#':>2}  {'PLACAR':<8} {'%':>7}    {'MERCADO':<22} {'%':>6}  {'':12}")
    _sep()
    for i in range(max(len(scores), len(markets))):
        sc = f"{i+1:>2}  {scores[i][0]:<8} {scores[i][1]:>7.2f}%" if i < len(scores) else f"{'':>2}  {'':8} {'':>8}"
        if i < len(markets):
            mk_n, mk_v = markets[i]
            bar = _render_bar(int(mk_v*100), 100, 10)
            mk  = f"    {mk_n:<22} {mk_v*100:>5.1f}%  {bar}"
        else:
            mk = ""
        _row(f"{sc}{mk}")

    # ── ODDS COMPLETAS ────────────────────────────────────────────────
    if all_odds:
        _section("💰 ODDS DO MERCADO")
        market_labels = [
            ("home",    "1X2 — Casa"),
            ("draw",    "1X2 — Empate"),
            ("away",    "1X2 — Fora"),
            ("btts_yes","BTTS — Sim"),
            ("btts_no", "BTTS — Não"),
            ("over15",  "Over 1.5"),
            ("over25",  "Over 2.5"),
            ("over35",  "Over 3.5"),
            ("under25", "Under 2.5"),
            ("dc_1x",   "DC Casa/Empate"),
            ("dc_x2",   "DC Empate/Fora"),
            ("dc_12",   "DC Casa/Fora"),
            ("dnb_home","DNB — Casa"),
            ("dnb_away","DNB — Fora"),
            ("ht_home", "HT — Casa"),
            ("ht_draw", "HT — Empate"),
            ("ht_away", "HT — Fora"),
        ]
        row_buf = []
        for key, label in market_labels:
            val = all_odds.get(key)
            if val:
                row_buf.append(f"{label:<22}: {val:.2f}")
                if len(row_buf) == 2:
                    _row(f"{row_buf[0]}   {row_buf[1]}")
                    row_buf = []
        if row_buf:
            _row(row_buf[0])

    # ── VEREDICTO FINAL ───────────────────────────────────────────────
    if ensemble:
        print("╠" + "═"*W + "╣")
        gc_str = f"   |   Confiança Global: {global_confidence['global_score']}/100" if global_confidence else ""
        print(f"║  🏆 VEREDICTO FINAL — ENSEMBLE V3  (Confiança: {conf['score']}/100 — {conf['label']}{gc_str})".ljust(W+1) + "║")
        print("║" + "═"*W + "║")
        _row(f"{'MERCADO':<26}  {'PROB':>5}  {'':^12}  {'RECOMENDAÇÃO':<18}  {'EV':>7}")
        _sep()
        for label, key, odd_key in [
            (f"Vitória {h_name[:16]}", "home_win",   "home"),
            ("Empate",                  "draw",       "draw"),
            (f"Vitória {a_name[:16]}", "away_win",   "away"),
            ("BTTS (ambos marcam)",     "btts",       None),
            ("Over 2.5 gols",          "over25",     None),
            ("Under 2.5 gols",         "_under25",   None),
        ]:
            prob = (1.0 - ensemble.get("over25", 0)) if key == "_under25" else ensemble.get(key, 0)
            if prob == 0:
                continue
            pct = int(prob * 100)
            bar = _render_bar(pct, 100, 12)
            rec, stars = _market_recommendation(prob)
            rec_icon = {"ENTRADA FORTE": "🟢", "ENTRADA": "🟡",
                        "AGUARDAR": "🟠", "EVITAR": "🔴"}.get(rec, "⚪")
            ev_str = "  N/A "
            if ev_final and odd_key and odd_key in ev_final:
                ev_str = f"{ev_final[odd_key]*100:>+6.1f}%"
            _row(f"{label:<26}  {pct:>4}%  {bar}  {rec_icon} {rec:<18}  {ev_str}")
        _sep()
        if mc.get("top_scores"):
            _row(f"🎯 Placar mais provável: {mc['top_scores'][0][0]}  ({mc['top_scores'][0][1]:.2f}%)")
            top3 = "   ".join(f"{s[0]} {s[1]:.1f}%" for s in mc["top_scores"][:5])
            _row(f"   Top 5: {top3}")
        _row(f"📊 Fontes ensemble: {', '.join(ensemble.get('sources_used', []))}")

    # ── PERFIS TÁTICOS V5 ─────────────────────────────────────────────
    if h_tactical and a_tactical:
        _section("🧠 PERFIS TÁTICOS — V5")
        _row(f"{'ATRIBUTO':<26}  {h_name[:16]:>16}  {a_name[:16]:>16}")
        _sep()
        for attr, hk, ak in [
            ("Estilo Principal",  "style",          "style"),
            ("Posse",             "possession_style","possession_style"),
            ("Pressão",          "pressure",        "pressure"),
            ("Transição",        "transition",      "transition"),
            ("Zona de Ataque",   "attack_zone",     "attack_zone"),
            ("Linha Defensiva",  "defensive_line",  "defensive_line"),
            ("Construção",       "construction",    "construction"),
        ]:
            hv = h_tactical.get(hk, "?")
            av = a_tactical.get(ak, "?")
            _row(f"{attr:<26}  {str(hv)[:16]:>16}  {str(av)[:16]:>16}")

    # ── MATCHUP TÁTICO V2 ─────────────────────────────────────────────
    if tactical_matchup:
        score_tm = tactical_matchup.get("score", 50)
        _section(f"⚔️  MATCHUP TÁTICO V2 — Tactical Edge Score: {score_tm:.0f}/100")
        _row(f"Resumo: {tactical_matchup.get('summary', '?')}")
        # Edge breakdown
        eb = tactical_matchup.get("edge_breakdown", {})
        if eb:
            _sep()
            _row(f"{'FATOR':<16}  {'EDGE':>8}  (+ = vantagem {h_name[:10]})")
            for factor, delta in eb.items():
                icon = "▲" if delta > 0 else ("▼" if delta < 0 else "─")
                _row(f"  {factor:<14}  {delta:>+7.1f} pts  {icon}")
        _sep()
        for adv in (tactical_matchup.get("advantages") or []):
            _row(f"✅ {adv[:65]}")
        for vuln in (tactical_matchup.get("vulnerabilities") or []):
            _row(f"⚠️  {vuln[:65]}")
        # Narrativa tática
        narr = tactical_matchup.get("narrative") or []
        if narr:
            _sep()
            _row("📋 ANÁLISE NARRATIVA:")
            for line in narr:
                _row(f"  • {line[:65]}")

    # ── FADIGA E CALENDÁRIO V5 ────────────────────────────────────────
    if fatigue_h is not None or fatigue_a is not None:
        _section("🏃 FADIGA & CALENDÁRIO (SOS)")
        fat_h_val = fatigue_h or 0
        fat_a_val = fatigue_a or 0
        bar_h = _render_bar(int(fat_h_val), 100, 18)
        bar_a = _render_bar(int(fat_a_val), 100, 18)
        _row(f"{h_name[:22]:<22}  Fadiga: {fat_h_val:>5.1f}/100  {bar_h}")
        _row(f"{a_name[:22]:<22}  Fadiga: {fat_a_val:>5.1f}/100  {bar_a}")
        if sos_h and sos_a:
            _sep()
            _h_elo_s = f"{sos_h.get('avg_opp_elo'):.0f}" if sos_h.get('avg_opp_elo') is not None else "N/A"
            _a_elo_s = f"{sos_a.get('avg_opp_elo'):.0f}" if sos_a.get('avg_opp_elo') is not None else "N/A"
            _row(f"SOS {h_name[:14]}: {sos_h.get('label','?')} (ELO médio oponentes: {_h_elo_s})")
            _row(f"SOS {a_name[:14]}: {sos_a.get('label','?')} (ELO médio oponentes: {_a_elo_s})")

    # ── IMPACTO CLIMÁTICO AVANÇADO V5 ────────────────────────────────
    if climate_impact:
        _section(f"🌦️  IMPACTO CLIMÁTICO AVANÇADO — {climate_impact.get('impact_label','?')}")
        _row(f"{'COEFICIENTE':<24}  {'VALOR':>10}  {'EFEITO':<30}")
        _sep()
        for label, key in [("xG coeff", "xg_coeff"), ("Ritmo coeff", "rhythm_coeff"),
                            ("Chutes coeff", "shots_coeff"), ("Pressão coeff", "pressure_coeff"),
                            ("Escanteios coeff", "corner_coeff")]:
            val = climate_impact.get(key, 1.0)
            effect = "Neutro" if abs(val-1.0) < 0.02 else ("Reduz" if val < 1.0 else "Aumenta")
            effect_icon = "🟢" if val >= 1.0 else ("🟡" if val >= 0.92 else "🔴")
            _row(f"{label:<24}  {val:>10.3f}  {effect_icon} {effect}")
        _row(f"Penalidade Total: {climate_impact.get('total_penalty',0):+.3f}  |  Temp: {climate_impact.get('temp_c',20)}°C  Vento: {climate_impact.get('wind_kmph',0)}km/h  Precip: {climate_impact.get('precip_mm',0)}mm")

    # ── PPDA e FIELD TILT V5 ─────────────────────────────────────────
    _section("🎯 PPDA & DOMINÂNCIA TERRITORIAL")
    for pname, ppd in [(h_name, ppda_h), (a_name, ppda_a)]:
        if ppd and ppd.get("ppda") is not None:
            ppda_val = ppd["ppda"]
            interp   = ppd.get("interpretation", "")
            _row(f"PPDA {pname[:16]}: {ppda_val:.2f}  → {ppd.get('label','?')}  ({ppd.get('games',0)} jogos)")
            if interp:
                _row(f"   ↳ {interp[:62]}")
        else:
            _row(f"PPDA {pname[:16]}: DADOS INSUFICIENTES (sem stats de desarmes/interc.)")
    _row("  Referência: PPDA <6=Extremo | 6-9=MAlto | 9-12=Alto | 12-15=Médio | 15+=Baixo")
    _sep()
    if field_tilt and field_tilt.get("home_tilt") is not None:
        bar_ht = _render_bar(int(field_tilt.get("home_tilt", 50)), 100, 20)
        bar_at = _render_bar(int(field_tilt.get("away_tilt", 50)), 100, 20)
        _row(f"Field Tilt {h_name[:12]}: {field_tilt.get('home_tilt',50):.1f}%  {bar_ht}")
        _row(f"Field Tilt {a_name[:12]}: {field_tilt.get('away_tilt',50):.1f}%  {bar_at}")
        _row(f"Diagnóstico: {field_tilt.get('label','?')}")
    else:
        _row("Field Tilt: DADOS INSUFICIENTES (sem estatísticas de posse por jogo)")

    # ── xTHREAT AVANÇADO V5 ──────────────────────────────────────────
    if xthreat:
        _section("⚡ xTHREAT — AMEAÇA ESPERADA")
        _row(f"{'TIME':<22}  {'xT Criado':>10}  {'xT Conced.':>10}  {'Saldo':>8}  {'Label':<20}")
        _sep()
        for name, key in [(h_name, "home"), (a_name, "away")]:
            xt = xthreat.get(key, {})
            if xt.get("created") is None:
                _row(f"{name[:22]:<22}  DADOS INSUFICIENTES")
                continue
            created  = xt.get("created", 0)
            conceded = xt.get("conceded", 0)
            net      = xt.get("net", 0)
            label    = xt.get("label", "?")
            net_icon = "🟢" if net >= 8 else ("🟡" if net >= -8 else "🔴")
            _row(f"{name[:22]:<22}  {created:>10.1f}  {conceded:>10.1f}  {net_icon}{net:>+7.1f}  {label:<20}")

    # ── AÇÕES PROGRESSIVAS V5 ────────────────────────────────────────
    if prog_h or prog_a:
        _section("🔄 AÇÕES PROGRESSIVAS")
        _row(f"{'MÉTRICA':<26}  {h_name[:16]:>16}  {a_name[:16]:>16}")
        _sep()
        for label, key in [
            ("Passes Progressivos", "prog_passes"),
            ("Conduções Prog.",     "prog_carries"),
            ("Finalizações Profundas","deep_completions"),
            ("Total",              "total"),
        ]:
            hv = (prog_h or {}).get(key, 0)
            av = (prog_a or {}).get(key, 0)
            _row(f"{label:<26}  {hv:>16.1f}  {av:>16.1f}")
        _row(f"{h_name[:14]}: {(prog_h or {}).get('label','?')}  |  {a_name[:14]}: {(prog_a or {}).get('label','?')}")

    # ── PRESSÃO POR ZONAS V5 ─────────────────────────────────────────
    if zones_h or zones_a:
        _section("🗺️  PRESSÃO POR ZONAS")
        _row(f"{'ZONA':<20}  {h_name[:16]:>16}  {a_name[:16]:>16}")
        _sep()
        for label, key in [
            ("Alta Pressão", "high_press"),
            ("Pressão Média","mid_press"),
            ("Bloco Baixo",  "low_press"),
        ]:
            hv = (zones_h or {}).get(key, 0)
            av = (zones_a or {}).get(key, 0)
            _row(f"{label:<20}  {hv:>16.1f}  {av:>16.1f}")
        _row(f"Alta Pressão %: {h_name[:10]} {(zones_h or {}).get('high_pct',0):.0f}%  |  {a_name[:10]} {(zones_a or {}).get('high_pct',0):.0f}%")

    # ── DISTRIBUIÇÃO TEMPORAL — GOLS V5 ──────────────────────────────
    periods_list = ["0-15", "16-30", "31-45", "46-60", "61-75", "76-90"]

    def _period_header():
        _row(f"{'TIME':<14}" + "".join(f"  {p:>7}" for p in periods_list))
        _sep()

    # Gols marcados
    _section("⏱️  GOLS POR PERÍODO — MARCADOS (média/j)")
    if goals_period_h or goals_period_a:
        _period_header()
        for name, data in [(h_name[:14], goals_period_h), (a_name[:14], goals_period_a)]:
            if data and data.get("games", 0) > 0:
                vals = data.get("scored", {})
                pcts = data.get("scored_pct", {})
                row  = f"{name:<14}" + "".join(f"  {vals.get(p,0):>7.2f}" for p in periods_list)
                _row(row)
                prow = f"{'%':<14}" + "".join(f"  {pcts.get(p,0):>6.1f}%" for p in periods_list)
                _row(prow)
                _row(f"   ↳ Pico ofensivo: {data.get('peak_scored','?')}  |  Total: {data.get('total_scored',0)} gols em {data.get('games',0)} jogos")
                _sep()
            else:
                _row(f"{name:<14}  DADOS INSUFICIENTES — eventos não retornados pela API")
    else:
        _row("DADOS INSUFICIENTES — a API não retornou eventos para estes jogos")

    # Gols sofridos
    _section("⏱️  GOLS POR PERÍODO — SOFRIDOS (média/j)")
    if goals_period_h or goals_period_a:
        _period_header()
        for name, data in [(h_name[:14], goals_period_h), (a_name[:14], goals_period_a)]:
            if data and data.get("games", 0) > 0:
                vals = data.get("conceded", {})
                row  = f"{name:<14}" + "".join(f"  {vals.get(p,0):>7.2f}" for p in periods_list)
                _row(row)
                _row(f"   ↳ Pico defensivo vulnerável: {data.get('peak_conceded','?')}")
                _sep()
    else:
        _row("DADOS INSUFICIENTES")

    # Escanteios
    _section("🚩 ESCANTEIOS — RESUMO HISTÓRICO")
    if corners_period_h or corners_period_a:
        for name, data in [(h_name[:14], corners_period_h), (a_name[:14], corners_period_a)]:
            if data and data.get("avg_corners_per_game") is not None:
                _row(f"{name}: {data['avg_corners_per_game']:.2f} escanteios/j  ({data.get('games',0)} jogos)")
                _row(f"   ↳ {data.get('note', '')[:60]}")
            else:
                _row(f"{name}: DADOS INSUFICIENTES")
    else:
        _row("DADOS INSUFICIENTES")

    # Cartões
    _section("🟨 CARTÕES POR PERÍODO — AMARELOS (média/j)")
    if cards_period_h or cards_period_a:
        _period_header()
        for name, data in [(h_name[:14], cards_period_h), (a_name[:14], cards_period_a)]:
            if data and data.get("games", 0) > 0:
                vals = data.get("yellows", {})
                pcts = data.get("yellows_pct", {})
                row  = f"{name:<14}" + "".join(f"  {vals.get(p,0):>7.2f}" for p in periods_list)
                _row(row)
                prow = f"{'%':<14}" + "".join(f"  {pcts.get(p,0):>6.1f}%" for p in periods_list)
                _row(prow)
                _row(f"   ↳ Pico de cartões: {data.get('peak_yellow','?')}  |  Total: {data.get('total_yellows',0)} em {data.get('games',0)} jogos")
                _sep()
            else:
                _row(f"{name:<14}  DADOS INSUFICIENTES")
    else:
        _row("DADOS INSUFICIENTES — eventos não disponíveis")

    # ── DOMINANCE SCORE V5 ───────────────────────────────────────────
    if dominance_score:
        _section("🏆 EXPECTED DOMINANCE SCORE")
        ds = dominance_score.get("score", 50)
        ds_label = dominance_score.get("label", "?")
        bar_d = _render_bar(int(ds), 100, 30)
        _row(f"Score: {ds:.1f}/100  {bar_d}")
        _row(f"Diagnóstico: {ds_label}")
        _row(f"  (ELO + xG + PPDA + Field Tilt + Forma + Clima + Fadiga)")

    # ── CENÁRIOS V5 ──────────────────────────────────────────────────
    if scenarios:
        _section("🎬 CENÁRIOS PROBABILÍSTICOS")
        for sc in scenarios:
            _row(f"{'★' * sc['id']}  [{sc['prob']*100:.0f}%]  {sc['title']}")
            _row(f"   Gols esperados: {sc['goals']}")
            _row(f"   {sc['desc'][:65]}")
            for k in sc.get("keys", []):
                _row(f"   • {k[:60]}")
            _sep()

    # ── NARRATIVA V5 ─────────────────────────────────────────────────
    if narrative:
        _section("📖 NARRATIVA DA PARTIDA")
        words = narrative.split()
        line = ""
        for word in words:
            if len(line) + len(word) + 1 > 64:
                _row(line)
                line = word
            else:
                line = (line + " " + word).strip()
        if line:
            _row(line)

    # ── PREDICTION CONFIDENCE INDEX V5 ───────────────────────────────
    if prediction_confidence:
        _section(f"🔬 ÍNDICE DE CONFIANÇA DA PREDIÇÃO")
        pc_score = prediction_confidence.get("score", 50)
        pc_label = prediction_confidence.get("label", "?")
        bar_pc = _render_bar(int(pc_score), 100, 25)
        _row(f"Score: {pc_score:.1f}/100  {bar_pc}  {pc_label}")
        _sep()
        for note in (prediction_confidence.get("notes") or []):
            _row(f"  • {note[:65]}")

    # ── MOTOR DE EXPLICABILIDADE V5 ──────────────────────────────────
    if explainability:
        _section("🔎 POR QUE O MODELO ACREDITA NISSO?")
        hw_pct = explainability.get("home_win_pct", 0)
        dr_pct = explainability.get("draw_pct", 0)
        aw_pct = explainability.get("away_win_pct", 0)
        _row(f"Vitória {h_name[:14]}: {hw_pct:.1f}%  |  Empate: {dr_pct:.1f}%  |  Vitória {a_name[:14]}: {aw_pct:.1f}%")
        _sep()
        _row(f"{'FATOR':<20}  {'CASA':>8}  {'EMPATE':>8}  {'FORA':>8}")
        _sep()
        for factor, contrib in (explainability.get("contributions") or {}).items():
            h_c = contrib.get("home", 0)
            d_c = contrib.get("draw", 0)
            a_c = contrib.get("away", 0)
            h_s = f"{h_c:>+7.1f}%" if h_c != 0 else f"{'0.0%':>8}"
            d_s = f"{d_c:>+7.1f}%" if d_c != 0 else f"{'0.0%':>8}"
            a_s = f"{a_c:>+7.1f}%" if a_c != 0 else f"{'0.0%':>8}"
            _row(f"{factor:<20}  {h_s}  {d_s}  {a_s}")

    # ── IMPACTO DE JOGADORES V5 ──────────────────────────────────────
    if player_impact:
        _section("⭐ IMPACTO INDIVIDUAL DE JOGADORES")
        _row(f"{'JOGADOR':<20}  {'TIME':<14}  {'POS':>4}  {'G':>3}  {'A':>3}  {'xG/j':>6}  {'Part%':>6}  {'Impact%':>8}")
        _sep()
        for side, tname in [("home", h_name), ("away", a_name)]:
            for p in (player_impact.get(side) or []):
                _row(f"{p['name'][:20]:<20}  {tname[:14]:<14}  {p['position'][:4]:>4}  "
                     f"{p['goals']:>3}  {p['assists']:>3}  {p['xg_ind']:>6.3f}  "
                     f"{p['participation_pct']:>5.1f}%  {p['absence_impact_pct']:>7.1f}%")
        absences = player_impact.get("absences") or []
        if absences:
            _sep()
            _row("⚠️  AUSÊNCIAS DETECTADAS:")
            for ab in absences:
                _row(f"  🔴 {ab['player'][:20]} ({ab['team'][:14]}): {ab['note'][:45]}")

    # ── QUALIDADE DOS DADOS V5 ───────────────────────────────────────
    if data_quality:
        _section("📋 RELATÓRIO DE QUALIDADE DOS DADOS")
        dq  = data_quality.get("data_score", 0)
        tq  = data_quality.get("tactical_score", 0)
        sq  = data_quality.get("stats_score", 0)
        rel = data_quality.get("reliability", 0)
        ph  = data_quality.get("placeholders", 0)
        bar_rel = _render_bar(rel, 100, 22)
        _row(f"Confiabilidade Geral:   {rel:>3}/100  {bar_rel}")
        _row(f"Qualidade dos Dados:    {dq:>3}/100  |  Cobertura Tática: {tq}/100  |  Cobertura Stats: {sq}/100")
        _row(f"Placeholders ativos:    {ph}  {'✅ Zero placeholders' if ph == 0 else '⚠️  Valores neutros presentes — interpretar com cautela'}")
        _sep()
        for note in (data_quality.get("notes") or []):
            _row(f"  {note[:65]}")

    print("╚" + "═"*W + "╝")

    # ── EV+ REPORT ──────────────────────────────────────────────────
    if ev_report:
        print()
        render_ev_report(ev_report, h_name, a_name, W=W)

    # ── ENTRY RECOMMENDATIONS ────────────────────────────────────────
    if recommendations is not None:
        print()
        render_entry_recommendations(recommendations, h_name, a_name, W=W)

    # ── FASE DE CALIBRAÇÃO PROFISSIONAL ──────────────────────────────
    if any(x is not None for x in [
            lambda_trace, model_audit, lambda_explainer_data, confidence_v2,
            backtest_pro, placeholder_detector, ev_validation, explainability_total]):
        print()
        _render_calibration_panels(
            lambda_trace=lambda_trace,
            model_audit=model_audit,
            lambda_explainer=lambda_explainer_data,
            confidence_v2=confidence_v2,
            backtest_pro=backtest_pro,
            placeholder_detector=placeholder_detector,
            ev_validation=ev_validation,
            explainability_total=explainability_total,
            consistency_audit=consistency_audit,
            global_confidence=global_confidence,
            h_name=h_name, a_name=a_name, W=W,
        )


def execute_advanced_pre_live_analysis_v3():
    """Análise pré-jogo V3 PRO — relatório completo com todos os módulos."""
    global selected_match

    # V3 analysis only — V2.1 removed

    h_id        = selected_match["home_id"]
    a_id        = selected_match["away_id"]
    h_name      = selected_match["home_name"]
    a_name      = selected_match["away_name"]
    fixture_id  = selected_match["fixture_id"]
    raw_fixture = selected_match["raw_data"]

    print("\n" + "═"*70)
    print("⏳ Coletando dados V3 PRO — aguarde (múltiplas APIs)...")
    print("═"*70)

    def _fetch_hist(team_id, n=10):
        try:
            res = requests.get(f"{BASE_URL}/fixtures", headers=headers,
                               params={"team": team_id, "status": "FT", "last": n}).json()
            return res.get("response", [])
        except Exception:
            return []

    h_hist = _fetch_hist(h_id, 10)
    a_hist = _fetch_hist(a_id, 10)

    real_referee  = raw_fixture.get("fixture", {}).get("referee")
    real_odds     = get_fixture_odds(fixture_id)
    match_datetime = raw_fixture.get("fixture", {}).get("date", "")
    league_name   = raw_fixture.get("league", {}).get("name", "")
    season        = raw_fixture.get("league", {}).get("season") or 2024
    league_id     = raw_fixture.get("league", {}).get("id") or WORLD_CUP_LEAGUE_ID

    print("  ▸ Forma recente e H2H...")
    h_form   = _format_recent_form(h_hist, h_id)
    a_form   = _format_recent_form(a_hist, a_id)
    h2h_list = _fetch_h2h_summary(h_id, a_id, n=8)

    print("  ▸ Classificações na liga...")
    h_standing = _fetch_team_standings(h_id, league_id, season)
    a_standing = _fetch_team_standings(a_id, league_id, season)

    print("  ▸ Jogadores-chave / artilheiros...")
    h_players = _fetch_top_players(h_id, season, league_id)
    a_players = _fetch_top_players(a_id, season, league_id)

    print("  ▸ Escalações...")
    lineups = _fetch_fixture_lineups(fixture_id)

    print("  ▸ Predição nativa da API-Football...")
    api_pred = _fetch_api_predictions(fixture_id)

    print("  ▸ Estádio e clima...")
    venue   = _fetch_venue_info(raw_fixture)
    weather = _fetch_weather(venue["city"]) if venue and venue.get("city") and venue["city"] != "?" else None

    print("  ▸ Odds — múltiplos mercados...")
    all_odds = _fetch_all_odds_markets(fixture_id, real_odds)

    print("  ▸ Estatísticas históricas (casa/fora + blend)...")
    h_home_fix = fetch_home_away_fixtures(h_id, "home", 10)
    a_away_fix = fetch_home_away_fixtures(a_id, "away", 10)
    h_home_m   = compile_home_away_metrics(h_home_fix, h_id, "home")
    a_away_m   = compile_home_away_metrics(a_away_fix, a_id, "away")
    h_gen      = _fetch_real_general_stats(h_hist, h_id)
    a_gen      = _fetch_real_general_stats(a_hist, a_id)
    h_blended  = blend_home_away_general(h_home_m, h_gen)
    a_blended  = blend_home_away_general(a_away_m, a_gen)

    print("  ▸ Módulos matemáticos (xG, ELO, Monte Carlo)...")

    # M1 — xG + Lambda calibrado (GF blend + sanity floor)
    h_wxg, h_wxga = calculate_weighted_xg(get_team_xg_history(h_hist, h_id))
    a_wxg, a_wxga = calculate_weighted_xg(get_team_xg_history(a_hist, a_id))
    xg_lh, xg_la  = calculate_xg_lambdas(
        h_wxg, a_wxga, a_wxg, h_wxga,
        avg_gf_home=h_blended.get("avg_gf"),
        avg_gf_away=a_blended.get("avg_gf"),
    )

    # M3 — ELO
    h_elo     = calculate_team_elo(h_id)
    a_elo     = calculate_team_elo(a_id)
    elo_probs = elo_win_probability(h_elo["elo"], a_elo["elo"])

    # M4 — Pressure Index
    h_pi = calculate_historical_pressure_index(
        h_blended.get("avg_shots", 12), h_blended.get("avg_sot", 4.5), h_blended.get("avg_corners", 5))
    a_pi = calculate_historical_pressure_index(
        a_blended.get("avg_shots", 12), a_blended.get("avg_sot", 4.5), a_blended.get("avg_corners", 5))

    # M5 — Poisson (lambdas serão refinados pelo Lambda Trace Engine abaixo)
    # Usar lambdas preliminares do xG calibrado; recalculados após o trace.
    lh = xg_lh if xg_lh else h_blended.get("avg_gf", 1.2)
    la = xg_la if xg_la else a_blended.get("avg_gf", 0.9)
    # Poisson preliminar (será substituído após Lambda Trace Engine)
    xg_model_probs = {"home_win": 0.33, "draw": 0.33, "away_win": 0.34, "btts": 0.50, "over25": 0.50}

    # M6 — Odds Movement
    odds_movement_result = track_odds_movement(fixture_id, real_odds) if real_odds else None

    # M7 — Referee
    ref_stats = None
    if real_referee:
        ref_stats = get_referee_stats(real_referee, season=2024, sample=15)

    # M8 — Escanteios
    adv_corners = calculate_advanced_corners(h_blended, a_blended, h_pi["index"], a_pi["index"])

    # M9 — Monte Carlo (placeholder; será recalculado após Lambda Trace Engine)
    mc = None
    mc_probs = None

    # M10 — ML
    h_rest = calculate_rest_days(h_hist[0]["fixture"]["date"][:10] if h_hist else None)
    a_rest = calculate_rest_days(a_hist[0]["fixture"]["date"][:10] if a_hist else None)
    ml_probs = ml_model_predict(extract_ml_features(
        h_blended, a_blended, h_elo, a_elo, h_pi, a_pi, h_rest, a_rest, real_odds, ref_stats))

    # M11 e M12 são calculados após o Lambda Trace Engine (abaixo)
    # Placeholders para dependências anteriores ao trace:
    conf    = {"score": 50, "label": "calculando...", "notes": []}
    ensemble = None

    # EV Final (legacy)
    ev_final = {}
    if real_odds and ensemble:
        for side, odd_key in [("home_win","home"), ("draw","draw"), ("away_win","away")]:
            odd = real_odds.get(odd_key)
            if odd:
                ev_final[odd_key] = (ensemble.get(side, 0) * odd) - 1.0

    # EV+ Report (V4)
    ev_report = build_ev_report(ensemble, all_odds, h_name, a_name)

    # ── V5 MODULES ────────────────────────────────────────────────────
    print("  ▸ V5 — Dados detalhados por jogo (stats + eventos)...")
    detailed_h = _fetch_detailed_game_data(h_hist, h_id, n=7)
    detailed_a = _fetch_detailed_game_data(a_hist, a_id, n=7)

    print("  ▸ V5 — Perfis táticos...")
    h_tactical = calculate_tactical_profile(h_hist, h_blended, h_id, lineups)
    a_tactical = calculate_tactical_profile(a_hist, a_blended, a_id, lineups)

    print("  ▸ V5 — Fadiga & SOS (ELO real por adversário)...")
    fatigue_h_v5 = calculate_fatigue_index(h_hist, match_datetime)
    fatigue_a_v5 = calculate_fatigue_index(a_hist, match_datetime)
    sos_h_v5 = calculate_sos(h_hist, h_id)
    sos_a_v5 = calculate_sos(a_hist, a_id)

    print("  ▸ V5 — Impacto climático avançado...")
    climate_impact_v5 = calculate_advanced_climate_impact(weather)

    print("  ▸ V5 — PPDA real, Field Tilt real, xThreat...")
    ppda_h_v5   = calculate_ppda(detailed_h, h_id)
    ppda_a_v5   = calculate_ppda(detailed_a, a_id)
    field_tilt_v5 = calculate_field_tilt(detailed_h, detailed_a)
    xthreat_v5  = calculate_enhanced_xthreat(h_blended, a_blended)

    print("  ▸ V5 — Ações progressivas & zonas de pressão...")
    prog_h_v5  = calculate_progressive_actions(h_blended)
    prog_a_v5  = calculate_progressive_actions(a_blended)
    zones_h_v5 = calculate_pressure_zones(h_blended)
    zones_a_v5 = calculate_pressure_zones(a_blended)

    print("  ▸ V5 — Matchup tático V2 (PPDA + Field Tilt + xThreat + Zonas)...")
    tactical_matchup_v5 = calculate_tactical_matchup(
        h_tactical, a_tactical, h_name, a_name,
        ppda_h=ppda_h_v5, ppda_a=ppda_a_v5,
        field_tilt=field_tilt_v5, xthreat=xthreat_v5,
        zones_h=zones_h_v5, zones_a=zones_a_v5,
        lineups=lineups,
    )

    print("  ▸ V5 — Distribuições temporais (eventos reais)...")
    goals_period_h_v5   = calculate_goals_by_period(detailed_h, h_id)
    goals_period_a_v5   = calculate_goals_by_period(detailed_a, a_id)
    corners_period_h_v5 = calculate_corners_by_period(detailed_h, h_id)
    corners_period_a_v5 = calculate_corners_by_period(detailed_a, a_id)
    cards_period_h_v5   = calculate_cards_by_period(detailed_h, h_id)
    cards_period_a_v5   = calculate_cards_by_period(detailed_a, a_id)

    print("  ▸ V5 — Dominance Score & Confidence Index...")
    dominance_score_v5 = calculate_dominance_score(
        h_elo, a_elo, h_pi, a_pi, ensemble,
        ppda_h_v5, ppda_a_v5,
        field_tilt_v5, xthreat_v5,
        climate_impact_v5, fatigue_h_v5, fatigue_a_v5,
    )
    prediction_confidence_v5 = calculate_prediction_confidence_index(
        h_hist, a_hist, ensemble, conf,
        xthreat_v5, dominance_score_v5, sos_h_v5, sos_a_v5,
    )

    print("  ▸ V5 — Impacto de jogadores e ausências...")
    player_impact_v5 = calculate_player_impact(h_players, a_players, lineups, h_name, a_name)

    print("  ▸ V5 — Motor de explicabilidade...")
    explainability_v5 = generate_explainability(
        ensemble, h_elo, a_elo, h_pi, a_pi,
        field_tilt_v5, xthreat_v5, climate_impact_v5,
        fatigue_h_v5, fatigue_a_v5, h_name, a_name,
    )

    print("  ▸ V5 — Qualidade dos dados...")
    data_quality_v5 = calculate_data_quality(
        h_hist, a_hist, h_blended, a_blended, weather, lineups,
        detailed_h, detailed_a, ppda_h_v5, ppda_a_v5,
        field_tilt_v5, goals_period_h_v5, goals_period_a_v5,
    )

    print("  ▸ V5 — Cenários & Narrativa avançada...")
    scenarios_v5 = generate_scenarios(
        ensemble, mc, tactical_matchup_v5,
        climate_impact_v5, fatigue_h_v5, fatigue_a_v5,
        h_name, a_name,
    )
    narrative_v5 = generate_narrative(
        scenarios_v5, h_name, a_name,
        tactical_matchup_v5, climate_impact_v5,
        fatigue_h_v5, fatigue_a_v5, ensemble,
    )

    # ── LAMBDA TRACE ENGINE ───────────────────────────────────────────
    print("  ▸ Lambda Trace Engine...")
    lambda_trace_v6 = calculate_lambda_trace(
        h_wxg, a_wxga, a_wxg, h_wxga,
        avg_gf_home=h_blended.get("avg_gf"),
        avg_gf_away=a_blended.get("avg_gf"),
        climate_impact=climate_impact_v5,
        fatigue_h=fatigue_h_v5, fatigue_a=fatigue_a_v5,
        field_tilt=field_tilt_v5,
        ppda_h=ppda_h_v5, ppda_a=ppda_a_v5,
        h_name=h_name, a_name=a_name,
    )
    # Usar lambdas do trace engine (mais precisos — incluem Field Tilt e PPDA)
    lh = lambda_trace_v6["h_lambda_final"]
    la = lambda_trace_v6["a_lambda_final"]

    # Log de rastreamento
    th = lambda_trace_v6["home"]
    ta = lambda_trace_v6["away"]
    print(f"\n  📊 LAMBDA TRACE ENGINE:")
    print(f"     {h_name[:16]}: GF={th['base_gf']:.2f}  xG={th['base_xg']:.3f}  blend={th['blend_inicial']:.3f}  "
          f"def={th['def_adj']:+.3f}  FT={th['field_tilt_adj']:+.3f}  PPDA={th['ppda_adj']:+.3f}  "
          f"clima={th['clima_adj']:+.3f}  fat={th['fadiga_adj']:+.3f}  λ={lh:.3f}"
          + ("  ⚠️ COMPRESSÃO" if th["warning"] else ""))
    print(f"     {a_name[:16]}: GF={ta['base_gf']:.2f}  xG={ta['base_xg']:.3f}  blend={ta['blend_inicial']:.3f}  "
          f"def={ta['def_adj']:+.3f}  FT={ta['field_tilt_adj']:+.3f}  PPDA={ta['ppda_adj']:+.3f}  "
          f"clima={ta['clima_adj']:+.3f}  fat={ta['fadiga_adj']:+.3f}  λ={la:.3f}"
          + ("  ⚠️ COMPRESSÃO" if ta["warning"] else ""))

    # Recalcular Poisson e Monte Carlo com lambdas finais do trace
    _hw = _dr = _aw = _btts = _o25 = 0.0
    for _hg in range(10):
        for _ag in range(10):
            _p = poisson_probability(lh, _hg) * poisson_probability(la, _ag)
            if _hg > _ag:    _hw   += _p
            elif _hg == _ag: _dr   += _p
            else:            _aw   += _p
            if _hg > 0 and _ag > 0:    _btts += _p
            if (_hg + _ag) > 2:        _o25  += _p
    _s = _hw + _dr + _aw
    if _s > 0:
        _hw /= _s; _dr /= _s; _aw /= _s
    xg_model_probs = {"home_win": _hw, "draw": _dr, "away_win": _aw, "btts": _btts, "over25": _o25}

    # Monte Carlo com lambdas finais (sem double-blend)
    print("  ▸ Monte Carlo (lambdas calibrados pelo trace engine)...")
    mc = run_monte_carlo(
        lh, la,
        n_simulations=100000,
        elo_weight=elo_probs["elo_diff"],
    )
    mc_probs = {"home_win": mc["home_win"], "draw": mc["draw"], "away_win": mc["away_win"],
                "btts": mc["btts"], "over25": mc["over25"]}

    # M11 — Enhanced Confidence Score (agora com dados reais de mc_probs/xg_model_probs)
    conf = calculate_enhanced_confidence(
        h_sample=len(h_hist), a_sample=len(a_hist),
        poisson_probs=xg_model_probs,
        mc_probs=mc_probs,
        elo_probs={"home_win": elo_probs["home_win"], "draw": elo_probs["draw"],
                   "away_win": elo_probs["away_win"]},
        xg_probs=xg_model_probs,
        real_odds=real_odds,
    )

    # M12 — Ensemble (com API como modelo real + Model Integrity Check)
    _api_probs = None
    if api_pred:
        try:
            ph = float(str(api_pred.get("percent_home", "0")).replace("%", "") or 0) / 100.0
            pd = float(str(api_pred.get("percent_draw", "0")).replace("%", "") or 0) / 100.0
            pa = float(str(api_pred.get("percent_away", "0")).replace("%", "") or 0) / 100.0
            if ph > 0 or pd > 0 or pa > 0:
                _api_probs = {"home_win": ph, "draw": pd, "away_win": pa}
        except Exception:
            _api_probs = None

    ensemble = calculate_ensemble_probability(
        poisson_probs=xg_model_probs,
        mc_probs=mc_probs,
        ml_probs=ml_probs,
        xg_probs=xg_model_probs,
        elo_probs={"home_win": elo_probs["home_win"], "draw": elo_probs["draw"],
                   "away_win": elo_probs["away_win"]},
        api_probs=_api_probs,
    )

    # Rebuild EV report now that ensemble is finalized
    ev_report = build_ev_report(ensemble, all_odds, h_name, a_name)
    if real_odds and ensemble:
        for side, odd_key in [("home_win","home"), ("draw","draw"), ("away_win","away")]:
            odd = real_odds.get(odd_key)
            if odd:
                ev_final[odd_key] = (ensemble.get(side, 0) * odd) - 1.0

    # ── CONSISTENCY AUDIT & GLOBAL CONFIDENCE (Corrections 4 & 6) ────
    print("  ▸ Consistency Audit...")
    consistency_audit_v6 = calculate_consistency_audit(
        ensemble, mc_probs, xg_model_probs,
        {"home_win": elo_probs["home_win"], "draw": elo_probs["draw"], "away_win": elo_probs["away_win"]},
        ml_probs, _api_probs, scenarios_v5,
    )
    print(f"     Consistência: {consistency_audit_v6['level']}  σ={consistency_audit_v6['std_dev']:.3f}  impacto={consistency_audit_v6['impact_on_confidence']:+d}pts")

    # ── FASE DE CALIBRAÇÃO PROFISSIONAL ──────────────────────────────
    print("  ▸ CALIB — Model Auditor...")
    model_audit_v6 = calculate_model_audit(
        xg_model_probs, mc_probs,
        {"home_win": elo_probs["home_win"], "draw": elo_probs["draw"], "away_win": elo_probs["away_win"]},
        ml_probs, api_pred,
    )

    print("  ▸ CALIB — Lambda Explainer...")
    lambda_explainer_v6 = calculate_lambda_explainer(
        h_blended, a_blended,
        h_wxg, a_wxg, h_wxga, a_wxga,
        climate_impact=climate_impact_v5,
        fatigue_h=fatigue_h_v5, fatigue_a=fatigue_a_v5,
        xg_lh=xg_lh, xg_la=xg_la,
    )

    print("  ▸ CALIB — Lambdas ajustados por clima + fadiga...")
    lh_adj, la_adj = apply_climate_fatigue_to_lambdas(
        lh, la, climate_impact=climate_impact_v5,
        fatigue_h=fatigue_h_v5, fatigue_a=fatigue_a_v5,
    )
    if abs(lh_adj - lh) > 0.01 or abs(la_adj - la) > 0.01:
        print(f"     λ ajustado: {h_name[:14]} {lh:.3f}→{lh_adj:.3f}  {a_name[:14]} {la:.3f}→{la_adj:.3f}")

    print("  ▸ CALIB — Placeholder Detector...")
    placeholder_detector_v6 = detect_placeholders(
        h_blended, a_blended,
        ppda_h_v5, ppda_a_v5, field_tilt_v5,
        goals_period_h_v5, goals_period_a_v5,
        sos_h_v5, sos_a_v5, weather, lineups,
        ml_probs, detailed_h, detailed_a,
    )

    print("  ▸ CALIB — Confidence Score 2.0...")
    confidence_v2_v6 = calculate_confidence_v2(
        h_sample=len(h_hist), a_sample=len(a_hist),
        model_audit=model_audit_v6,
        placeholder_detector=placeholder_detector_v6,
        data_quality=data_quality_v5,
        lineups=lineups, weather=weather,
        detailed_h=detailed_h, detailed_a=detailed_a,
        h_hist=h_hist, a_hist=a_hist,
    )

    print("  ▸ CALIB — Global Confidence (Unified)...")
    global_confidence_v6 = calculate_global_confidence(
        ensemble_conf=confidence_v2_v6,
        data_quality=data_quality_v5,
        placeholder_detector=placeholder_detector_v6,
        lineups=lineups,
        weather=weather,
        h_hist=h_hist,
        a_hist=a_hist,
        consistency_audit=consistency_audit_v6,
    )
    print(f"     Confiança Global: {global_confidence_v6['global_score']}/100")

    print("  ▸ CALIB — Backtest Profissional (Brier + LogLoss)...")
    backtest_pro_v6 = calculate_backtest_professional()

    print("  ▸ CALIB — EV+ Validation...")
    ev_validation_v6 = validate_high_ev(ev_report, model_audit_v6, ensemble, threshold=0.20)

    print("  ▸ CALIB — ML features V2 + Logistic Regression...")
    ml_features_v2 = extract_ml_features_v2(
        h_blended, a_blended, h_elo, a_elo,
        h_pi, a_pi, h_rest, a_rest, real_odds,
        ppda_h=ppda_h_v5, ppda_a=ppda_a_v5,
        h_hist=h_hist, a_hist=a_hist,
    )
    ml_probs_v2 = ml_logistic_predict(ml_features_v2)
    if ml_probs_v2:
        print(f"     LR: Casa={ml_probs_v2['home_win']*100:.1f}%  Empate={ml_probs_v2['draw']*100:.1f}%  Fora={ml_probs_v2['away_win']*100:.1f}%")

    print("  ▸ CALIB — Explainability Total...")
    explainability_total_v6 = generate_explainability_total(
        ensemble, model_audit_v6, lambda_explainer_v6,
        h_elo, a_elo, h_pi, a_pi,
        field_tilt_v5, xthreat_v5, climate_impact_v5,
        fatigue_h_v5, fatigue_a_v5,
        ppda_h_v5, ppda_a_v5, sos_h_v5, sos_a_v5,
        h_name=h_name, a_name=a_name,
    )

    # False pressure for home/away (default snap-less — use blended stats proxy)
    _fp_snap_h = {
        "h_dangerous": h_blended.get("avg_dangerous_attacks", 0) if h_blended else 0,
        "h_possession": 52, "h_sot": h_blended.get("avg_sot", 0) if h_blended else 0,
    }
    _fp_snap_a = {
        "a_dangerous": a_blended.get("avg_dangerous_attacks", 0) if a_blended else 0,
        "a_possession": 48, "a_sot": a_blended.get("avg_sot", 0) if a_blended else 0,
    }
    false_pressure_h = detect_false_pressure(_fp_snap_h, "h_", 90)
    false_pressure_a = detect_false_pressure(_fp_snap_a, "a_", 90)

    # Entry recommendations (V4)
    recommendations = recommend_entry(
        ev_report=ev_report,
        confidence=conf,
        false_pressure_h=false_pressure_h,
        false_pressure_a=false_pressure_a,
    )

    # Kelly for best EV market
    if recommendations:
        best = recommendations[0]
        print("  ✅ Dados coletados — renderizando relatório...\n")
        render_kelly_panel(
            prob_model=best["ev"] + (1.0 / best["odd"] if best["odd"] else 0),
            odd=best["odd"],
            ev=best["ev"],
            confidence=conf.get("score", 0),
        )
    else:
        print("  ✅ Dados coletados — renderizando relatório...\n")

    _render_pre_game_dashboard(
        h_name=h_name, a_name=a_name, fixture_id=fixture_id,
        h_id=h_id, a_id=a_id,
        h_form=h_form, a_form=a_form,
        h2h_list=h2h_list,
        h_blended=h_blended, a_blended=a_blended,
        h_elo=h_elo, a_elo=a_elo, elo_probs=elo_probs,
        h_pi=h_pi, a_pi=a_pi,
        adv_corners=adv_corners,
        mc=mc, ref_stats=ref_stats, real_referee=real_referee,
        ensemble=ensemble, conf=conf,
        ev_final=ev_final,
        xg_lh=xg_lh, xg_la=xg_la,
        h_standing=h_standing, a_standing=a_standing,
        h_players=h_players, a_players=a_players,
        lineups=lineups,
        api_pred=api_pred,
        weather=weather,
        venue=venue,
        all_odds=all_odds,
        match_datetime=match_datetime,
        league_name=league_name,
        ev_report=ev_report,
        recommendations=recommendations,
        # V5 new modules
        h_tactical=h_tactical, a_tactical=a_tactical,
        tactical_matchup=tactical_matchup_v5,
        scenarios=scenarios_v5,
        narrative=narrative_v5,
        climate_impact=climate_impact_v5,
        fatigue_h=fatigue_h_v5, fatigue_a=fatigue_a_v5,
        sos_h=sos_h_v5, sos_a=sos_a_v5,
        ppda_h=ppda_h_v5, ppda_a=ppda_a_v5,
        field_tilt=field_tilt_v5,
        xthreat=xthreat_v5,
        prog_h=prog_h_v5, prog_a=prog_a_v5,
        zones_h=zones_h_v5, zones_a=zones_a_v5,
        goals_period_h=goals_period_h_v5, goals_period_a=goals_period_a_v5,
        corners_period_h=corners_period_h_v5, corners_period_a=corners_period_a_v5,
        cards_period_h=cards_period_h_v5, cards_period_a=cards_period_a_v5,
        dominance_score=dominance_score_v5,
        prediction_confidence=prediction_confidence_v5,
        player_impact=player_impact_v5,
        explainability=explainability_v5,
        data_quality=data_quality_v5,
        # FASE DE CALIBRAÇÃO PROFISSIONAL
        lambda_trace=lambda_trace_v6,
        model_audit=model_audit_v6,
        lambda_explainer_data=lambda_explainer_v6,
        confidence_v2=confidence_v2_v6,
        backtest_pro=backtest_pro_v6,
        placeholder_detector=placeholder_detector_v6,
        ev_validation=ev_validation_v6,
        explainability_total=explainability_total_v6,
        global_confidence=global_confidence_v6,
        consistency_audit=consistency_audit_v6,
    )

    input("\nPressione ENTER para retornar ao menu da partida...")





# =====================================================================
# MÓDULO TRADING AO VIVO — DASHBOARD AUTOMÁTICO DE SINAIS
# =====================================================================
#
# Lógica central: polling a cada POLL_INTERVAL segundos.
# A cada ciclo, captura um snapshot das estatísticas ao vivo.
# Mantém histórico dos últimos HISTORY_SIZE snapshots.
# Calcula DELTAS entre snapshots para detectar aceleração de pressão.
# Gera sinais de GOL / ESCANTEIO / CARTÃO com força (1-5 estrelas).
#
# Limitação da API: /fixtures/statistics retorna apenas o acumulado
# total do jogo (não por minuto). A minutagem vem de /fixtures ao vivo
# (campo status.elapsed). O "por minuto" é inferido pelos deltas entre
# polls consecutivos — quanto mudou desde o último ciclo.

import time as _time_module
import os as _os_module

# Constantes do trading dashboard
POLL_INTERVAL = 30        # segundos entre consultas (respeita rate limit da API)
HISTORY_SIZE  = 8         # snapshots mantidos em memória (~4 minutos de histórico)
CLEAR_SCREEN  = True      # False se o terminal não suportar ANSI
DIAG_MODE     = False     # True para exibir nomes de stat reais retornados pela API


def _clear():
    if CLEAR_SCREEN:
        print("\033[H\033[J", end="", flush=True)


def _fetch_live_fixture(fixture_id):
    """Busca o estado atual da partida: placar, minuto, status."""
    try:
        res = requests.get(
            f"{BASE_URL}/fixtures",
            headers=headers,
            params={"id": fixture_id}
        ).json()
        data = res.get("response", [])
        if not data:
            return None
        f = data[0]
        return {
            "minute":  f["fixture"]["status"].get("elapsed") or 0,
            "status":  f["fixture"]["status"].get("short", "?"),
            "score_h": f["goals"].get("home") or 0,
            "score_a": f["goals"].get("away") or 0,
        }
    except Exception:
        return None


def _fetch_live_events(fixture_id):
    """Busca eventos ao vivo (gols, cartões, substituições)."""
    try:
        res = requests.get(
            f"{BASE_URL}/fixtures/events",
            headers=headers,
            params={"fixture": fixture_id}
        ).json()
        return res.get("response", [])
    except Exception:
        return []


def _extract_flex(block, *type_names):
    """
    Extração robusta de stats: case-insensitive, tenta múltiplos nomes.
    A API-Football usa capitalizações inconsistentes entre versões e planos.
    Ex: 'Shots off Goal' vs 'Shots Off Goal', 'Passes accurate' vs 'Passes Accurate'.
    Retorna 0 se nenhum nome corresponder — nunca lança exceção.
    """
    stats_list = block.get("statistics", [])
    targets = {n.lower().strip() for n in type_names}
    for stat in stats_list:
        if stat.get("type", "").lower().strip() in targets:
            raw = str(stat.get("value") or "0").replace("%", "").strip()
            try:
                return int(float(raw))
            except (ValueError, TypeError):
                return 0
    return 0


def _debug_stat_names(block):
    """Retorna todos os nomes de stat disponíveis no bloco (para diagnóstico)."""
    return [s.get("type", "") for s in block.get("statistics", [])]


def _snapshot(fixture_id, home_id):
    """
    Captura snapshot completo: estatísticas ao vivo + minuto + placar.
    Usa _extract_flex para tolerar variações de capitalização da API.
    Registra quais stats vieram como 0 para diagnóstico.
    """
    stats = get_fixture_statistics(fixture_id)
    live  = _fetch_live_fixture(fixture_id)
    if not stats or len(stats) < 2 or not live:
        return None

    if int(stats[0]["team"]["id"]) == int(home_id):
        hb, ab = stats[0], stats[1]
    else:
        hb, ab = stats[1], stats[0]

    # _v() tenta múltiplos nomes para cada stat — cobre variações da API
    def _v(block, *keys):
        return _extract_flex(block, *keys)

    snap = {
        "ts":            _time_module.time(),
        "minute":        live["minute"],
        "status":        live["status"],
        "score_h":       live["score_h"],
        "score_a":       live["score_a"],
        # ── Mandante ─────────────────────────────────────────────────
        "h_shots":    _v(hb, "Total Shots", "Shots Total", "total shots"),
        "h_sot":      _v(hb, "Shots on Goal", "Shots On Goal", "shots on goal",
                           "On Goal", "on goal"),
        "h_blocked":  _v(hb, "Blocked Shots", "Blocked", "blocked shots"),
        "h_woodwork": _v(hb, "Hit Woodwork", "Woodwork", "hit woodwork"),
        "h_corners":  _v(hb, "Corner Kicks", "Corners", "corner kicks"),
        "h_fouls":    _v(hb, "Fouls", "fouls"),
        "h_yellow":   _v(hb, "Yellow Cards", "Yellow", "yellow cards"),
        "h_red":      _v(hb, "Red Cards", "Red", "red cards"),
        "h_dangerous":_v(hb, "Dangerous Attacks", "dangerous attacks",
                           "Dangerous attacks"),
        "h_attacks":  _v(hb, "Attacks", "Total Attacks", "attacks"),
        "h_off_goal": _v(hb, "Shots off Goal", "Shots Off Goal",
                           "shots off goal", "Off Goal", "off goal"),
        "h_possession":_v(hb, "Ball Possession", "Possession", "ball possession"),
        "h_passes_acc":_v(hb, "Passes accurate", "Passes Accurate",
                            "passes accurate", "Accurate Passes"),
        # ── Visitante ────────────────────────────────────────────────
        "a_shots":    _v(ab, "Total Shots", "Shots Total", "total shots"),
        "a_sot":      _v(ab, "Shots on Goal", "Shots On Goal", "shots on goal",
                           "On Goal", "on goal"),
        "a_blocked":  _v(ab, "Blocked Shots", "Blocked", "blocked shots"),
        "a_woodwork": _v(ab, "Hit Woodwork", "Woodwork", "hit woodwork"),
        "a_corners":  _v(ab, "Corner Kicks", "Corners", "corner kicks"),
        "a_fouls":    _v(ab, "Fouls", "fouls"),
        "a_yellow":   _v(ab, "Yellow Cards", "Yellow", "yellow cards"),
        "a_red":      _v(ab, "Red Cards", "Red", "red cards"),
        "a_dangerous":_v(ab, "Dangerous Attacks", "dangerous attacks",
                           "Dangerous attacks"),
        "a_attacks":  _v(ab, "Attacks", "Total Attacks", "attacks"),
        "a_off_goal": _v(ab, "Shots off Goal", "Shots Off Goal",
                           "shots off goal", "Off Goal", "off goal"),
        "a_possession":_v(ab, "Ball Possession", "Possession", "ball possession"),
        "a_passes_acc":_v(ab, "Passes accurate", "Passes Accurate",
                            "passes accurate", "Accurate Passes"),
        # Meta: nomes reais da API (para diagnóstico)
        "_h_stat_names": _debug_stat_names(hb),
        "_a_stat_names": _debug_stat_names(ab),
    }

    # Fallback: se h_sot==0 mas h_shots>0, estima SOT por taxa histórica (~33%)
    # Garante que xG nunca seja 0 só por falha de nome de stat
    if snap["h_sot"] == 0 and snap["h_shots"] > 0:
        snap["h_sot"] = max(1, round(snap["h_shots"] * 0.33))
        snap["_h_sot_estimated"] = True
    if snap["a_sot"] == 0 and snap["a_shots"] > 0:
        snap["a_sot"] = max(1, round(snap["a_shots"] * 0.33))
        snap["_a_sot_estimated"] = True

    # Fallback: dangerous attacks via proxy se não disponível no plano
    if snap["h_dangerous"] == 0 and snap["h_shots"] > 0:
        snap["h_dangerous"] = round(snap["h_shots"] * 2.2)
        snap["_da_estimated"] = True
    if snap["a_dangerous"] == 0 and snap["a_shots"] > 0:
        snap["a_dangerous"] = round(snap["a_shots"] * 2.2)

    return snap


def _delta(new, old):
    """
    Calcula o delta (variação) entre dois snapshots.
    Retorna dict com campos prefixados por 'd_'.
    """
    keys = [
        "h_shots","h_sot","h_blocked","h_corners","h_fouls",
        "h_yellow","h_red","h_dangerous","h_attacks","h_off_goal",
        "a_shots","a_sot","a_blocked","a_corners","a_fouls",
        "a_yellow","a_red","a_dangerous","a_attacks","a_off_goal",
    ]
    return {f"d_{k}": max(0, new.get(k, 0) - old.get(k, 0)) for k in keys}


# ── SINAIS DE TRADING ─────────────────────────────────────────────────

def _rolling_pressure(snapshots, prefix):
    """
    Taxa média de pressão ofensiva calculada a partir dos deltas entre
    snapshots consecutivos. Retorna (taxa_recente, taxa_anterior, aceleracao).

    Usa a janela completa de snapshots passada — sem threshold mínimo fixo.
    Com 2 snapshots já calcula 1 delta e retorna aceleração = 0.
    Com 3+ snapshots compara janelas recente vs anterior.
    """
    if len(snapshots) < 2:
        return 0.0, 0.0, 0.0

    deltas = []
    for i in range(1, len(snapshots)):
        d = _delta(snapshots[i], snapshots[i-1])
        press = (d[f"d_{prefix}sot"] * 4
                 + d[f"d_{prefix}shots"] * 2
                 + d[f"d_{prefix}dangerous"] * 1
                 + d[f"d_{prefix}blocked"] * 1)
        deltas.append(press)

    # Taxa recente: média dos últimos 2 deltas (ou o único disponível)
    recent_window  = deltas[-2:] if len(deltas) >= 2 else deltas[-1:]
    earlier_window = deltas[:-2] if len(deltas) > 2 else []

    recent  = sum(recent_window) / max(len(recent_window), 1)
    earlier = sum(earlier_window) / max(len(earlier_window), 1) if earlier_window else 0.0
    accel   = round(recent - earlier, 2)
    return round(recent, 2), round(earlier, 2), accel


def _signal_goal(snap, hist, h_name, a_name):
    """
    Avalia probabilidade de gol iminente.

    Componentes:
    1. UPI acumulado — pressão total no jogo inteiro
    2. Taxa de pressao recente — variacao por ciclo de poll (detecta ondas)
    3. Aceleracao — taxa recente vs janela anterior (onda crescendo ou nao)
    4. xG acumulado + xG pace projetado ate 90min

    Correcoes vs versao anterior:
    - _rolling_pressure() calcula deltas desde o 2o ciclo (antes: exigia 3)
    - xG nunca e 0 graças ao fallback SOT estimado no _snapshot()
    - Score reequilibrado: UPI 45% + taxa 8pt + aceleracao 12pt + xG 6pt
    """
    signals = []
    minute = max(snap["minute"], 1)

    # ── 1. UPI acumulado ─────────────────────────────────────────────
    h_upi = (snap["h_shots"]*2 + snap["h_sot"]*4 + snap["h_blocked"]*2
             + snap["h_woodwork"]*5 + snap["h_corners"]*3)
    a_upi = (snap["a_shots"]*2 + snap["a_sot"]*4 + snap["a_blocked"]*2
             + snap["a_woodwork"]*5 + snap["a_corners"]*3)

    # ── 2 & 3. Taxa e aceleracao via rolling window ───────────────────
    window = hist + [snap]   # hist = snapshots anteriores; snap = atual
    h_rate, h_rate_prev, h_accel = _rolling_pressure(window, "h_")
    a_rate, a_rate_prev, a_accel = _rolling_pressure(window, "a_")
    trend_h = h_accel > 0
    trend_a = a_accel > 0

    # ── 4. xG acumulado e xG pace ────────────────────────────────────
    xg_acc_h = round(snap["h_sot"] / 4.5, 2)
    xg_acc_a = round(snap["a_sot"] / 4.5, 2)
    # Ritmo atual → projecao de xG adicional nos minutos restantes
    sot_rate_h = snap["h_sot"] / minute
    sot_rate_a = snap["a_sot"] / minute
    xg_proj_h = round(xg_acc_h + sot_rate_h * max(90 - minute, 0) / 4.5, 2)
    xg_proj_a = round(xg_acc_a + sot_rate_a * max(90 - minute, 0) / 4.5, 2)

    # ── Score combinado ───────────────────────────────────────────────
    score_h = (h_upi * 0.45
               + h_rate * 8
               + max(h_accel, 0) * 12
               + xg_acc_h * 6
               + (8 if trend_h else 0))
    score_a = (a_upi * 0.45
               + a_rate * 8
               + max(a_accel, 0) * 12
               + xg_acc_a * 6
               + (8 if trend_a else 0))

    def _stars(s):
        if s >= 80: return "★★★★★ ELITE"
        if s >= 55: return "★★★★☆ FORTE"
        if s >= 35: return "★★★☆☆ MODERADO"
        if s >= 18: return "★★☆☆☆ FRACO"
        return None

    for team, score, upi, rate, accel, trend, xg_acc, xg_proj, sot in [
        (h_name, score_h, h_upi, h_rate, h_accel, trend_h,
         xg_acc_h, xg_proj_h, snap["h_sot"]),
        (a_name, score_a, a_upi, a_rate, a_accel, trend_a,
         xg_acc_a, xg_proj_a, snap["a_sot"]),
    ]:
        label = _stars(score)
        if label:
            arrow = "↑↑" if (trend and accel > 1) else ("↑" if trend else "→")
            est = "~" if (
                snap.get("_h_sot_estimated") and team == h_name or
                snap.get("_a_sot_estimated") and team == a_name
            ) else ""
            signals.append({
                "type": "GOL",
                "team": team,
                "strength": label,
                "detail": (
                    f"UPI={upi} | SOT={est}{sot} | "
                    f"xG={xg_acc:.2f} (proj/90={xg_proj:.2f}) | "
                    f"Taxa={rate:.1f}/ciclo {arrow} | Daccel={accel:+.1f}"
                ),
                "score": score,
            })

    return sorted(signals, key=lambda x: x["score"], reverse=True)


def _signal_corner(snap, hist, h_name, a_name):
    """
    Avalia probabilidade de escanteio iminente.
    Base: chutes bloqueados + chutes para fora + ataques perigosos recentes.
    """
    signals = []

    for team, prefix, name in [("H", "h_", h_name), ("A", "a_", a_name)]:
        blocked   = snap[f"{prefix}blocked"]
        off_goal  = snap[f"{prefix}off_goal"]
        corners   = snap[f"{prefix}corners"]
        dangerous = snap[f"{prefix}dangerous"]

        # Número de chutes "candidatos a escanteio" ainda não convertidos
        candidate_ratio = (blocked + off_goal) / max(corners + 1, 1)

        # Delta recente de chutes bloqueados — usa window completa desde o 1o ciclo
        window = hist + [snap]
        d_blocked = 0
        if len(window) >= 2:
            d = _delta(window[-1], window[-2])
            d_blocked = d[f"d_{prefix}blocked"] + d[f"d_{prefix}off_goal"]

        ivl = blocked * 2.5 + off_goal * 1.2 + corners * 0.8 + d_blocked * 4

        if ivl >= 30 and candidate_ratio >= 1.5:
            strength = "★★★★★ ELITE" if ivl >= 55 else "★★★★☆ FORTE"
        elif ivl >= 18:
            strength = "★★★☆☆ MODERADO"
        elif ivl >= 10:
            strength = "★★☆☆☆ FRACO"
        else:
            continue

        signals.append({
            "type": "ESCANTEIO",
            "team": name,
            "strength": strength,
            "detail": (f"Bloqueados={blocked} | Fora={off_goal} | "
                       f"Cantos={corners} | Δ recente={d_blocked} | IVL={ivl:.0f}"),
            "score": ivl,
        })

    return sorted(signals, key=lambda x: x["score"], reverse=True)


def _signal_card(snap, hist, h_name, a_name, minute):
    """
    Avalia probabilidade de cartão iminente.
    Fatores: volume de faltas no período recente + tensão do jogo (placar, minuto).
    """
    signals = []

    score_diff = abs(snap["score_h"] - snap["score_a"])
    losing_team_pressure = (
        (snap["score_h"] < snap["score_a"] and snap["h_dangerous"] > snap["a_dangerous"])
        or
        (snap["score_a"] < snap["score_h"] and snap["a_dangerous"] > snap["h_dangerous"])
    )
    # Minuto crítico: 75-90 com time perdendo gera mais faltas táticas
    critical_minute = minute >= 75

    for prefix, name in [("h_", h_name), ("a_", a_name)]:
        fouls   = snap[f"{prefix}fouls"]
        yellows = snap[f"{prefix}yellow"]

        # Taxa de faltas acumuladas
        foul_rate = fouls / max(minute, 1) * 90  # projeção para 90 min

        # Delta de faltas recentes — disponível desde o 2o ciclo
        window = hist + [snap]
        d_fouls = 0
        if len(window) >= 2:
            d = _delta(window[-1], window[-2])
            d_fouls = d[f"d_{prefix}fouls"]

        # Score de risco de cartão
        card_score = (
            foul_rate * 0.4
            + d_fouls * 5
            + yellows * 8          # 2º amarelo iminente
            + (10 if critical_minute else 0)
            + (8 if losing_team_pressure else 0)
            + (5 if score_diff >= 2 else 0)
        )

        if card_score >= 50:
            strength = "★★★★★ ALTO RISCO" if card_score >= 75 else "★★★★☆ RISCO ELEVADO"
        elif card_score >= 30:
            strength = "★★★☆☆ RISCO MODERADO"
        elif card_score >= 18:
            strength = "★★☆☆☆ RISCO BAIXO"
        else:
            continue

        signals.append({
            "type": "CARTÃO",
            "team": name,
            "strength": strength,
            "detail": (f"Faltas={fouls} (proj/90={foul_rate:.0f}) | "
                       f"Δ recente={d_fouls} | Amarelos={yellows} | "
                       f"Min={minute}{'🔴' if critical_minute else ''}"),
            "score": card_score,
        })

    return sorted(signals, key=lambda x: x["score"], reverse=True)


def _render_bar(value, max_val, width=20, char="█"):
    """Renderiza uma barra de progresso ASCII para o painel."""
    filled = int((value / max(max_val, 1)) * width)
    filled = min(filled, width)
    return char * filled + "░" * (width - filled)


def _sparkline(values, width=12):
    """Mini gráfico de barras ASCII para série temporal."""
    if not values:
        return "─" * width
    blocks = " ▁▂▃▄▅▆▇█"
    mx = max(values) or 1
    chars = []
    for v in values[-width:]:
        idx = int(v / mx * (len(blocks) - 1))
        chars.append(blocks[idx])
    # pad left with spaces if needed
    return " " * (width - len(chars)) + "".join(chars)


def _xg_live(snap, minute):
    """Calcula xG acumulado e ritmo projetado para 90min."""
    m = max(minute, 1)
    xg_h = round(snap["h_sot"] / 4.5, 2)
    xg_a = round(snap["a_sot"] / 4.5, 2)
    xg_proj_h = round(xg_h + (snap["h_sot"] / m) * max(90 - minute, 0) / 4.5, 2)
    xg_proj_a = round(xg_a + (snap["a_sot"] / m) * max(90 - minute, 0) / 4.5, 2)
    return xg_h, xg_a, xg_proj_h, xg_proj_a


def _live_narrative(snap, consciousness, regime, h_name, a_name):
    """Gera frase de narrativa contextual para o momento atual do jogo."""
    minute  = snap["minute"]
    score_h = snap["score_h"]
    score_a = snap["score_a"]
    diff    = score_h - score_a

    phase_name = consciousness["phase"]["phase"] if consciousness else "jogo"
    sc_state   = consciousness.get("score_state", {}) if consciousness else {}
    behavior   = sc_state.get("behavior", "")

    # Regime dominante
    regime_lbl = ""
    if regime and regime.get("label"):
        regime_lbl = f" [{regime['label'].split('–')[0].strip()}]"

    # Pressão dominante
    h_upi = snap["h_shots"]*2 + snap["h_sot"]*4 + snap["h_blocked"]*2 + snap["h_corners"]*3
    a_upi = snap["a_shots"]*2 + snap["a_sot"]*4 + snap["a_blocked"]*2 + snap["a_corners"]*3
    if h_upi > a_upi * 1.3:
        pressure_txt = f"{h_name[:14]} domina territorialmente."
    elif a_upi > h_upi * 1.3:
        pressure_txt = f"{a_name[:14]} controla o jogo."
    else:
        pressure_txt = "Jogo equilibrado em volume."

    # Score context
    if diff == 0:
        score_ctx = f"Empate {score_h}x{score_a} — {behavior[:50]}" if behavior else f"Empate {score_h}x{score_a}."
    elif diff > 0:
        score_ctx = f"{h_name[:12]} vence por {diff}. {behavior[:40]}" if behavior else f"{h_name[:12]} +{diff}."
    else:
        score_ctx = f"{a_name[:12]} vence por {abs(diff)}. {behavior[:40]}" if behavior else f"{a_name[:12]} +{abs(diff)}."

    return f"{minute}' | {phase_name}{regime_lbl}. {pressure_txt} {score_ctx}"


def _render_dashboard(snap, hist, h_name, a_name, home_id,
                       goal_sigs, corner_sigs, card_sigs,
                       poll_count, next_poll_in, consciousness=None,
                       live_fair=None, regime=None,
                       false_pressure_h=None, false_pressure_a=None,
                       live_events=None,
                       v5_momentum=None, v5_press_h=None, v5_press_a=None,
                       v5_gii=None, v5_anti_h=None, v5_anti_a=None,
                       v5_cashout=None, v5_corn_h=None, v5_corn_a=None,
                       v5_tactical=None, v5_fatigue=None, v5_xgm=None,
                       v5_red=None, v5_game_state=None, v5_win_prob=None,
                       v5_trader=None, v5_alerts=None):
    """Renderiza o painel de trading ao vivo — layout limpo e actionable."""
    _clear()

    W = 70
    minute  = snap["minute"]
    status  = snap["status"]
    score_h = snap["score_h"]
    score_a = snap["score_a"]

    h_upi = snap["h_shots"]*2 + snap["h_sot"]*4 + snap["h_blocked"]*2 + snap["h_woodwork"]*5 + snap["h_corners"]*3
    a_upi = snap["a_shots"]*2 + snap["a_sot"]*4 + snap["a_blocked"]*2 + snap["a_woodwork"]*5 + snap["a_corners"]*3
    xg_h, xg_a, xg_proj_h, xg_proj_a = _xg_live(snap, minute)

    # UPI histórico para sparkline
    h_upi_hist = [s["h_shots"]*2+s["h_sot"]*4+s["h_blocked"]*2+s["h_corners"]*3 for s in hist]
    a_upi_hist = [s["a_shots"]*2+s["a_sot"]*4+s["a_blocked"]*2+s["a_corners"]*3 for s in hist]
    h_spark = _sparkline(h_upi_hist + [h_upi], 10)
    a_spark = _sparkline(a_upi_hist + [a_upi], 10)

    # Posse
    h_poss = snap.get("h_possession", 50) or 50
    a_poss = snap.get("a_possession", 50) or (100 - h_poss)

    # Alerta crítico
    critical_alert = ""
    if consciousness:
        tension = consciousness.get("score_state", {}).get("tension", 0)
        if tension >= 0.80:
            critical_alert = "🔴 ALTA TENSÃO"
        elif tension >= 0.55:
            critical_alert = "🟠 TENSÃO CRESCENTE"

    # ── HEADER ────────────────────────────────────────────────────────
    print("╔" + "═"*W + "╗")
    hn14 = h_name[:16]
    an14 = a_name[:16]
    header = f"║  📡  {hn14}  {score_h} x {score_a}  {an14}"
    print(header.ljust(W+1) + "║")
    status_line = f"║  ⏱ {minute}' [{status}]  •  Ciclo #{poll_count}  •  Próx: {next_poll_in}s"
    if critical_alert:
        status_line += f"  {critical_alert}"
    print(status_line.ljust(W+1) + "║")

    # Narrativa ao vivo
    if consciousness:
        narr = _live_narrative(snap, consciousness, regime, h_name, a_name)
        print(f"║  {narr[:W-2]}".ljust(W+1) + "║")

    print("╠" + "═"*W + "╣")

    # ── xG AO VIVO ────────────────────────────────────────────────────
    print(f"║  ⚡ xG   {h_name[:14]}: {xg_h:.2f} acc  ({xg_proj_h:.2f}/90)   "
          f"{a_name[:14]}: {xg_a:.2f} acc  ({xg_proj_a:.2f}/90)".ljust(W+1) + "║")
    print(f"║  🏃 Posse  {h_name[:14]}: {h_poss:.0f}%   {a_name[:14]}: {a_poss:.0f}%".ljust(W+1) + "║")

    print("╠" + "═"*W + "╣")

    # ── ESTATÍSTICAS (tabela compacta) ────────────────────────────────
    print(f"║  {'STAT':<18} {'CASA':>5}  {'GRÁF':^14}  {'VISIT':>5}".ljust(W+1) + "║")
    print("║" + "─"*W + "║")

    def _row(label, hv, av):
        mv = max(hv, av, 1)
        hb = _render_bar(hv, mv, 5)
        ab = _render_bar(av, mv, 5)
        print(f"║  {label:<18} {hv:>4}  {hb}║{ab}  {av:>4}".ljust(W+1) + "║")

    _row("UPI (Pressão)",   h_upi,              a_upi)
    _row("Chutes Totais",   snap["h_shots"],    snap["a_shots"])
    _row("No Alvo",         snap["h_sot"],      snap["a_sot"])
    _row("Bloqueados",      snap["h_blocked"],  snap["a_blocked"])
    _row("Para Fora",       snap["h_off_goal"], snap["a_off_goal"])
    _row("Escanteios",      snap["h_corners"],  snap["a_corners"])
    _row("At. Perigosos",   snap["h_dangerous"],snap["a_dangerous"])
    _row("Faltas",          snap["h_fouls"],    snap["a_fouls"])
    _row("Amarelos/Verm.",  snap["h_yellow"],   snap["a_yellow"])

    # ── SPARKLINE UPI ─────────────────────────────────────────────────
    if len(hist) >= 2:
        print("║" + "─"*W + "║")
        print(f"║  📊 Tendência UPI  {h_name[:12]}: [{h_spark}]={h_upi}  "
              f"{a_name[:12]}: [{a_spark}]={a_upi}".ljust(W+1) + "║")

    # ── EVENTOS AO VIVO (gols, cartões, substituições) ─────────────────
    if live_events:
        relevant = [e for e in live_events
                    if e.get("type", "").lower() in ("goal", "card", "subst")]
        if relevant:
            print("╠" + "═"*W + "╣")
            print(f"║  📋 EVENTOS DO JOGO".ljust(W+1) + "║")
            print("║" + "─"*W + "║")
            icons = {"goal": "⚽", "card": "🟨", "subst": "🔄"}
            for ev in relevant[-6:]:
                t    = ev.get("time", {}).get("elapsed", "?")
                typ  = ev.get("type", "").lower()
                team = ev.get("team", {}).get("name", "?")[:14]
                player = ev.get("player", {}).get("name", "")[:16]
                detail = ev.get("detail", "")[:12]
                ic   = icons.get(typ, "•")
                print(f"║  {ic} {t:>3}' {team:<14} {player:<16} {detail}".ljust(W+1) + "║")

    # ── SINAIS DE TRADING ─────────────────────────────────────────────
    print("╠" + "═"*W + "╣")
    print(f"║  🚦 SINAIS ATIVOS".ljust(W+1) + "║")
    print("║" + "─"*W + "║")

    all_signals = (
        [(s, "GOL")       for s in goal_sigs]   +
        [(s, "ESCANTEIO") for s in corner_sigs] +
        [(s, "CARTÃO")    for s in card_sigs]
    )

    if all_signals:
        for sig, _ in sorted(all_signals, key=lambda x: x[0]["score"], reverse=True)[:5]:
            icon = {"GOL": "⚽", "ESCANTEIO": "🚩", "CARTÃO": "🟨"}.get(sig["type"], "•")
            print(f"║  {icon} {sig['strength']} [{sig['type']}] {sig['team']}".ljust(W+1) + "║")
            print(f"║     {sig['detail'][:W-5]}".ljust(W+1) + "║")
    else:
        print(f"║    ⚪ Sem sinais relevantes no momento.".ljust(W+1) + "║")

    # ── MERCADOS — PRÓXIMOS 5 MINUTOS ────────────────────────────────
    if consciousness:
        pred = consciousness.get("pred", {})
        if pred:
            print("╠" + "═"*W + "╣")
            print(f"║  🎯 PRÓXIMOS 5 MIN  —  Prováveis eventos".ljust(W+1) + "║")
            print(f"║  {'MERCADO':<28} {'PROB':>4}  {'BARRA':^14}  {'SINAL':>12}".ljust(W+1) + "║")
            print("║" + "─"*W + "║")

            def _mkt_row(emoji, label, prob):
                pct = int(prob * 100)
                bar = _render_bar(pct, 100, 10)
                rec_label, _ = _market_recommendation(prob)
                rec_icons = {"ENTRADA FORTE": "🟢", "ENTRADA": "🟡",
                             "AGUARDAR": "🟠", "EVITAR": "🔴"}
                rec_icon = rec_icons.get(rec_label, "⚪")
                print(f"║  {emoji} {label:<26} {pct:>3}%  {bar}  {rec_icon} {rec_label}".ljust(W+1) + "║")

            _mkt_row("⚽", f"Gol qualquer",                        pred.get("p_goal_any", 0))
            _mkt_row("  ", f"  └ {h_name[:22]}",                   pred.get("p_goal_h",   0))
            _mkt_row("  ", f"  └ {a_name[:22]}",                   pred.get("p_goal_a",   0))
            _mkt_row("🚩", "Escanteio (qualquer)",                  pred.get("p_corner_any", 0))
            _mkt_row("🟨", "Cartão (qualquer)",                     pred.get("p_card_any",   0))

            # Quem é mais provável de marcar
            likely = pred.get("likely_scorer", "")
            if likely:
                print("║" + "─"*W + "║")
                print(f"║  📌 Mais provável marcar: {likely[:40]}".ljust(W+1) + "║")

            # Eventos críticos
            clusters = consciousness.get("clusters", [])
            criticals = [c for c in clusters if c.get("urgency") in ("crítica", "muito alta")]
            if criticals:
                print("║" + "─"*W + "║")
                for c in criticals[:3]:
                    urg_icon = "🔴" if c["urgency"] == "crítica" else "🟠"
                    print(f"║  {urg_icon} {c['msg'][:W-5]}".ljust(W+1) + "║")

    # ── V5: ALERTAS PROFISSIONAIS ─────────────────────────────────────
    if v5_alerts:
        top_alerts = [a for a in v5_alerts if a["priority"] <= 2][:5]
        if top_alerts:
            print("╠" + "═"*W + "╣")
            print(f"║  🔔 ALERTAS".ljust(W+1) + "║")
            print("║" + "─"*W + "║")
            for al in top_alerts:
                metrics_str = "  ".join(al.get("metrics", []))[:20]
                print(f"║  {al['icon']} {al['title']:<30} conf:{al['confidence']:>3}%  {metrics_str}".ljust(W+1) + "║")
                print(f"║     ↳ {al['reason'][:W-6]}".ljust(W+1) + "║")

    # ── V5: WIN PROBABILITY LIVE ──────────────────────────────────────
    if v5_win_prob:
        hw = v5_win_prob["h_win"]; dr = v5_win_prob["draw"]; aw = v5_win_prob["a_win"]
        bh = _render_bar(int(hw*100), 100, 8); bd = _render_bar(int(dr*100), 100, 8)
        ba = _render_bar(int(aw*100), 100, 8)
        print("╠" + "═"*W + "╣")
        print(f"║  🎲 WIN PROB LIVE   Casa: {hw*100:.1f}% {bh}  Emp: {dr*100:.1f}% {bd}  Fora: {aw*100:.1f}% {ba}".ljust(W+1) + "║")

    # ── V5: GAME STATE ────────────────────────────────────────────────
    if v5_game_state:
        print("╠" + "═"*W + "╣")
        print(f"║  🎮 GAME STATE   {v5_game_state['h_icon']} {h_name[:16]}: {v5_game_state['h_state']:<22}  "
              f"{v5_game_state['a_icon']} {a_name[:16]}: {v5_game_state['a_state']}".ljust(W+1) + "║")

    # ── V5: LIVE MOMENTUM ─────────────────────────────────────────────
    if v5_momentum:
        hs = v5_momentum["h_score"]; as_ = v5_momentum["a_score"]
        bh = _render_bar(int(hs), 100, 8); ba = _render_bar(int(as_), 100, 8)
        print("╠" + "═"*W + "╣")
        print(f"║  📈 MOMENTUM   {h_name[:14]}: {hs:>5.1f} {bh} {v5_momentum['h_label']:<12}  "
              f"{a_name[:14]}: {as_:>5.1f} {ba} {v5_momentum['a_label']}".ljust(W+1) + "║")
        print(f"║     {v5_momentum['diagnosis'][:W-5]}".ljust(W+1) + "║")

    # ── V5: GOAL IMMINENT INDEX ───────────────────────────────────────
    if v5_gii:
        hg = v5_gii["h_gii"]; ag = v5_gii["a_gii"]
        bh = _render_bar(int(hg), 100, 8); ba = _render_bar(int(ag), 100, 8)
        ah = "  🚨 GOL IMINENTE!" if v5_gii["alert_h"] else ""
        aa = "  🚨 GOL IMINENTE!" if v5_gii["alert_a"] else ""
        print("╠" + "═"*W + "╣")
        print(f"║  🎯 GOAL INDEX   {h_name[:14]}: {hg:>5.1f} {bh}{ah}".ljust(W+1) + "║")
        print(f"║                  {a_name[:14]}: {ag:>5.1f} {ba}{aa}".ljust(W+1) + "║")

    # ── V5: PRESSÃO ACUMULADA ─────────────────────────────────────────
    if v5_press_h and v5_press_a:
        print("╠" + "═"*W + "╣")
        print(f"║  🌊 PRESSÃO   {'CASA':>5}  /  {'FORA':>5}         1m    3m    5m   10m".ljust(W+1) + "║")
        print(f"║  {h_name[:14]:<14}: P1={v5_press_h['p1']:>5.1f}  P3={v5_press_h['p3']:>5.1f}  "
              f"P5={v5_press_h['p5']:>5.1f}  P10={v5_press_h['p10']:>5.1f}  [{v5_press_h['level']}]{'  ⚡SUSTENTADA' if v5_press_h['sustained_alert'] else ''}".ljust(W+1) + "║")
        print(f"║  {a_name[:14]:<14}: P1={v5_press_a['p1']:>5.1f}  P3={v5_press_a['p3']:>5.1f}  "
              f"P5={v5_press_a['p5']:>5.1f}  P10={v5_press_a['p10']:>5.1f}  [{v5_press_a['level']}]{'  ⚡SUSTENTADA' if v5_press_a['sustained_alert'] else ''}".ljust(W+1) + "║")

    # ── V5: xG MOMENTUM ──────────────────────────────────────────────
    if v5_xgm:
        hxm = v5_xgm.get("home", {}); axm = v5_xgm.get("away", {})
        print("╠" + "═"*W + "╣")
        print(f"║  ⚡ xG MOMENTUM   {h_name[:14]}: {hxm.get('icon','')} {hxm.get('trend','?')}  "
              f"(jogo={hxm.get('xg_game',0):.2f}  5c={hxm.get('xg5',0):.3f}  10c={hxm.get('xg10',0):.3f})".ljust(W+1) + "║")
        print(f"║                   {a_name[:14]}: {axm.get('icon','')} {axm.get('trend','?')}  "
              f"(jogo={axm.get('xg_game',0):.2f}  5c={axm.get('xg5',0):.3f}  10c={axm.get('xg10',0):.3f})".ljust(W+1) + "║")

    # ── V5: ESCANTEIO IMINENTE ────────────────────────────────────────
    if v5_corn_h is not None and v5_corn_a is not None:
        none_prob = max(0.0, 1.0 - v5_corn_h - v5_corn_a)
        print("╠" + "═"*W + "╣")
        print(f"║  🚩 ESCANTEIO ~5min   Casa: {v5_corn_h*100:.0f}%  "
              f"Fora: {v5_corn_a*100:.0f}%  Nenhum: {none_prob*100:.0f}%".ljust(W+1) + "║")

    # ── V5: ANTI-FALSO OVER ───────────────────────────────────────────
    if v5_anti_h and v5_anti_a:
        show_h = v5_anti_h["sterile"] or v5_anti_a["sterile"]
        if show_h:
            print("╠" + "═"*W + "╣")
        for aov, nm in [(v5_anti_h, h_name), (v5_anti_a, a_name)]:
            if aov.get("sterile") or aov.get("efficient"):
                print(f"║  {aov['icon']} {aov['type']} — {nm[:14]}  "
                      f"Posse={aov['possession']:.0f}%  Chutes={aov['shots']}  xG={aov['xg']:.2f}".ljust(W+1) + "║")
                print(f"║     ↳ {aov['recommendation'][:W-6]}".ljust(W+1) + "║")

    # ── V5: FADIGA AO VIVO ────────────────────────────────────────────
    if v5_fatigue and (v5_fatigue["h_score"] >= 50 or v5_fatigue["a_score"] >= 50):
        print("╠" + "═"*W + "╣")
        print(f"║  😓 FADIGA   {h_name[:14]}: {v5_fatigue['h_score']:.0f}/100 [{v5_fatigue['h_label']}]  "
              f"{a_name[:14]}: {v5_fatigue['a_score']:.0f}/100 [{v5_fatigue['a_label']}]".ljust(W+1) + "║")

    # ── V5: RED CARD IMPACT ───────────────────────────────────────────
    if v5_red and v5_red.get("detected"):
        print("╠" + "═"*W + "╣")
        print(f"║  🔴 VERMELHO — {v5_red['team']}".ljust(W+1) + "║")
        print(f"║     Ataque: {v5_red['attack_pct']:+.0f}%  Defesa: {v5_red['defense_pct']:+.0f}%  "
              f"Over adj: ×{v5_red['over_adj']:.2f}  BTTS adj: ×{v5_red['btts_adj']:.2f}".ljust(W+1) + "║")

    # ── V5: MUDANÇA TÁTICA ────────────────────────────────────────────
    if v5_tactical and v5_tactical.get("detected"):
        print("╠" + "═"*W + "╣")
        print(f"║  🔄 MUDANÇA TÁTICA: {v5_tactical['description'][:W-20]}".ljust(W+1) + "║")
        for side, ch in v5_tactical.get("changes", {}).items():
            nm = h_name if side == "home" else a_name
            print(f"║     {nm[:16]}: {ch['type']}  Δposs={ch['delta_poss']:+.1f}  Δatt={ch['delta_att']:+.1f}  "
                  f"Off: {ch['off_impact']:+d}%  Def: {ch['def_impact']:+d}%".ljust(W+1) + "║")

    # ── V5: SMART CASHOUT ─────────────────────────────────────────────
    if v5_cashout:
        ca = v5_cashout["action"]
        if ca != "MANTER POSIÇÃO" or True:  # sempre mostra
            print("╠" + "═"*W + "╣")
            print(f"║  {v5_cashout['icon']} CASHOUT: {ca}   ({v5_cashout['remaining']}min restantes)".ljust(W+1) + "║")
            print(f"║     ↳ {v5_cashout['reason'][:W-6]}".ljust(W+1) + "║")

    # ── V5: TRADER ASSISTANT ─────────────────────────────────────────
    if v5_trader:
        conf = v5_trader["confidence"]
        conf_bar = _render_bar(conf, 100, 10)
        print("╠" + "═"*W + "╣")
        print(f"║  🤖 TRADER ASSISTANT — {v5_trader['minute']}'".ljust(W+1) + "║")
        print(f"║  {v5_trader['narrative'][:W-2]}".ljust(W+1) + "║")
        print("║" + "─"*W + "║")
        rec_icon = "🟢" if conf >= 70 else ("🟡" if conf >= 50 else "🔴")
        print(f"║  {rec_icon} Recomendação: {v5_trader['recommendation']:<30}  Confiança: {conf}% {conf_bar}".ljust(W+1) + "║")
        if v5_trader["motivos"]:
            motivos_str = "  |  ".join(v5_trader["motivos"][:3])
            print(f"║     ↳ {motivos_str[:W-6]}".ljust(W+1) + "║")

    # ── MOMENTUM (consciência existente — mantido) ─────────────────────
    if consciousness and consciousness.get("momentum", {}).get("status") == "ok":
        mom = consciousness["momentum"]
        print("╠" + "═"*W + "╣")
        dom = mom.get("dominant")
        dom_txt = f"  ▶ Dominante: {dom}" if dom else "  Equilíbrio"
        print(f"║  📊 MOMENTUM (UPI){dom_txt}".ljust(W+1) + "║")
        print(f"║  {h_name[:20]:<20}: {mom['h_label'][:46]}".ljust(W+1) + "║")
        print(f"║  {a_name[:20]:<20}: {mom['a_label'][:46]}".ljust(W+1) + "║")

    # ── LIVE FAIR ODDS ────────────────────────────────────────────────
    if live_fair:
        print("╠" + "═"*W + "╣")
        print(f"║  ⚡ FAIR ODDS AO VIVO".ljust(W+1) + "║")
        print(f"║  {'MERCADO':<32} {'FAIR':>6}  {'MKT':>6}  {'EDGE':>7}".ljust(W+1) + "║")
        print("║" + "─"*W + "║")
        for _lf_label, _lf_key in [
            (f"Próx. Gol {h_name[:14]}", "next_goal_h"),
            (f"Próx. Gol {a_name[:14]}", "next_goal_a"),
            ("Gol restante",             "over_current_05"),
            ("Ambas Marcam",             "btts"),
        ]:
            _lf_val = live_fair.get(_lf_key)
            if _lf_val is not None:
                print(f"║  {_lf_label:<32} {_lf_val:>6.2f}".ljust(W+1) + "║")

    # ── GAME REGIME ───────────────────────────────────────────────────
    if regime:
        print("╠" + "═"*W + "╣")
        print(f"║  🎮 {regime.get('label','?')}  (conf: {regime.get('confidence',0)*100:.0f}%)".ljust(W+1) + "║")
        if regime.get("trading_advice"):
            print(f"║  💡 {regime['trading_advice'][:W-5]}".ljust(W+1) + "║")

    # ── PRESSÃO FALSA ────────────────────────────────────────────────
    fp_shown = False
    for fp, name in [(false_pressure_h, h_name), (false_pressure_a, a_name)]:
        if fp and fp.get("is_false_pressure"):
            if not fp_shown:
                print("╠" + "═"*W + "╣")
                fp_shown = True
            print(f"║  ⚠ PRESSÃO FALSA — {name[:18]}  ({fp['reason'][:W-26]})".ljust(W+1) + "║")

    # ── FADIGA (consciência existente — mantido) ───────────────────────
    if consciousness and consciousness.get("fatigue"):
        for fat in consciousness["fatigue"][:2]:
            if not fp_shown:
                print("╠" + "═"*W + "╣")
                fp_shown = True
            mod = fat.get("modifier", 1.0)
            icon = "💪" if mod >= 1.1 else "😓"
            print(f"║  {icon} {fat['msg'][:W-4]}".ljust(W+1) + "║")

    # ── DIAG ─────────────────────────────────────────────────────────
    if DIAG_MODE:
        print("╠" + "═"*W + "╣")
        for n in snap.get("_h_stat_names", [])[:5]:
            print(f"║  [DIAG] {n}".ljust(W+1) + "║")
        if snap.get("_h_sot_estimated"):
            print(f"║  ⚠ SOT estimado (33% shots)".ljust(W+1) + "║")

    print("╠" + "═"*W + "╣")
    print(f"║  [Q] Sair   Intervalo: {POLL_INTERVAL}s   [DIAG={DIAG_MODE}]".ljust(W+1) + "║")
    print("╚" + "═"*W + "╝")



def live_trading_dashboard(fixture_id, h_name, a_name, home_id):
    """
    Loop principal do dashboard de trading ao vivo.
    Atualiza automaticamente a cada POLL_INTERVAL segundos.
    Digite 'q' + ENTER para sair.
    """
    import select as _select
    import sys as _sys

    print("\n📡 Iniciando Trading Dashboard...")
