def main():
    mode = choose_mode()

    if mode == "1":
        list_world_cup_matches_today()
        return

    print("\n=== MODO ESTATÍSTICAS TRADICIONAIS (CLUBES) ===")
    team_id = input("Digite o ID do clube: ")
    team_name = get_team_name(team_id)
    season = input(f"Temporada: ")
    league_id = get_team_leagues(team_id, season)

    if not league_id: return

    while True:
        print(f"\nMenu Principal de Clubes ({team_name}):")
        print("0. Sair\n1. Classificação\n2. Últimos 5 jogos\n3. Estatísticas de Gols\n4. Confrontos Diretos\n6. Estatísticas por ID")
        choice = input("Escolha a opção (0-6): ")

        if choice == "0": break
        elif choice == "1": get_league_standings(team_id, league_id, season)
        elif choice == "2": get_last_five_league_matches(team_id, league_id)
        elif choice == "3": get_team_stats(team_id)
        elif choice == "4": get_head_to_head(team_id, input("ID do adversário: "))
        elif choice == "6":
            fid = input("Fixture ID: ")
            st = get_fixture_statistics(fid)
            if st:
                for s1, s2 in zip(st[0]["statistics"], st[1]["statistics"]):
                    print(f"{s1['type']}: {s1['value']}")


if __name__ == "__main__":
    main()